    all_keys = []
    all_values = []
    for k, v in items:
        all_keys.append(k)
        all_values.append(v)

    # If no specific keys are requested, return all
    if not keys:
        return dict(zip(all_keys, all_values))

    # Build the result dictionary
    result = {}
    for key in keys:
        if isinstance(key, int):
            # Handle Python style negative indices
            idx = key if key >= 0 else len(all_keys) + key
            if idx < 0 or idx >= len(all_keys):
                raise IndexError(f"Index {key} out of bounds for record of length {len(all_keys)}")
            result[all_keys[idx]] = all_values[idx]
        else:
            if key in all_keys:
                idx = all_keys.index(key)
                result[key] = all_values[idx]
            else:
                result[key] = None
