    # Build the result for the requested keys or indices
    result = {}
    for key in keys:
        if isinstance(key, int):
            # Handle integer index
            if key < 0 or key >= len(values):
                raise IndexError(f"index {key} is out of range")
            result[fields[key]] = values[key]
