    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer. """
    try:
        low_byte = self.data.pop()
        high_byte = self.data.pop()
    except IndexError:
        raise ValueError("Not enough data to pop a 16-bit integer") from None
    return (high_byte << 8) | low_byte

def pop_u16(self):
    """Remove the last two bytes of data, returning them as a big-endian 16‑bit unsigned integer."""
    if not hasattr(self, 'data'):
        raise AttributeError("Object must have a 'data' attribute.")
    data = self.data
    try:
        if len(data) < 2:
            raise ValueError("Insufficient data: at least two bytes required to pop a 16‑bit value.")
    except Exception as exc:
        raise TypeError("'data' must support len() and be a sequence of bytes") from exc

    high, low = data[-2], data[-1]
    value = (high << 8) | low

    if isinstance(data, (bytearray, bytes)):
        if isinstance(data, bytes):
            self.data = data[:-2]
        else:
            del data[-2:]
    else:
        data.pop()
        data.pop()
    return value

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Ensure the object has a data attribute
    if not hasattr(self, "data"):
        raise AttributeError("Object does not have a 'data' attribute")
    # Ensure there is enough data to pop
    if len(self.data) < 2:
        raise IndexError("Not enough data to pop two bytes")
    # Grab the last two bytes
    last_two = self.data[-2:]
    # Remove the last two bytes from the buffer
    try:
        if isinstance(self.data, bytearray):
            del self.data[-2:]
        elif isinstance(self.data, bytes):
            # bytes are immutable; replace with a sliced copy
            self.data = self.data[:-2]
        else:
            # Fallback for other sequence types
            try:
                del self.data[-2:]
            except Exception:
                self.data = self.data[:-2]
    except Exception as exc:
        raise RuntimeError("Failed to remove bytes from data buffer") from exc
    # Convert the two bytes to an integer (big endian)
    return int.from_bytes(bytes(last_two), byteorder="big")

