        raise TypeError("db must be a string if provided")
    if imp_user is not None and not isinstance(imp_user, str):
        raise TypeError("imp_user must be a string if provided")

    # Build the BEGIN message payload
    payload = {
        "mode": mode if mode else "WRITE",
        "bookmarks": bookmarks_list if bookmarks is not None else [],
        "metadata": metadata if metadata is not None else {},
        "timeout": timeout,
        "database": db,
        "impUser": imp_user,
    }

    # Attach hooks if they are provided and valid dictionaries
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict")
        payload["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict")
        payload["hydration_hooks"] = hydration_hooks

    # Try to append to an internal output queue if it exists
    try:
        if hasattr(self, "_output_queue"):
            self._output_queue.append(("BEGIN", payload))
        elif hasattr(self, "output_queue"):
            # older attribute
            self.output_queue.append(("BEGIN", payload))
        else:
            # If no queue exists, just log or raise
            raise AttributeError("Output queue not found on the instance")
    except Exception as e:
        # Log the exception (if a logger is available) and re-raise a generic runtime error
        try:
            if hasattr(self, "logger"):
                self.logger.error("Failed to queue BEGIN message: %s", e)
        except Exception:
            pass
        raise RuntimeError(f"Failed to queue BEGIN message: {e}") from e

    # Define a simple Response object that wraps the payload and handlers
    class Response:
        def __init__(self, payload, handlers):
            self.payload = payload
            self.handlers = handlers

        def __repr__(self):
            return f"<Response payload={self.payload!r} handlers={list(self.handlers.keys())!r}>"

    # Return the response instance
    return Response(payload, handlers)

def round_half_to_even(n):
    """
    Round a number to the nearest integer using "round half to even" (banker's rounding).

    Parameters
    ----------
    n : int or float
        The number to round.

    Returns
    -------
    int
        The rounded integer.

    Raises
    ------
    ValueError
        If the input cannot be converted to a numeric type.
    """
    # Validate input and cast to float
    try:
        value = float(n)
    except Exception as exc:
        raise ValueError(f"Input {n!r} is not a numeric type") from exc

    # For integer values, return immediately
    if value.is_integer():
        return int(value)

    import math
    floor_part = math.floor(value)
    frac = value - floor_part

    # Handle the exact half-case (.5)
    if abs(frac - 0.5) < 1e-10:
        # If the integer part is even, keep it; otherwise round up
        return int(floor_part) if int(floor_part) % 2 == 0 else int(floor_part + 1)

    # Regular rounding
    if frac > 0.5:
        return int(floor_part + 1)
    else:
        return int(floor_part)

