def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the class name
    if not isinstance(name, str) or not name.isidentifier():
        raise ValueError("`name` must be a valid Python identifier string")

    # Validate fields
    if fields is None:
        field_names = []
    elif isinstance(fields, dict):
        field_names = list(fields.keys())
    elif isinstance(fields, (list, tuple)):
        field_names = list(fields)
    else:
        raise TypeError("`fields` must be a list, tuple, dict, or None")

    for f in field_names:
        if not isinstance(f, str) or not f.isidentifier():
            raise ValueError(f"field name {f!r} is not a valid identifier")

    # Validate SRID map
    if not isinstance(srid_map, dict):
        raise TypeError("`srid_map` must be a dictionary")
    for key, val in srid_map.items():
        if not isinstance(key, str):
            raise TypeError(f"SRID map key {key!r} must be a string")
        if not isinstance(val, int):
            raise TypeError(f"SRID value for {key!r} must be an integer")

    # Dynamically create the subclass
    try:
        from shapely.geometry import Point as _BasePoint
    except Exception as exc:
        raise ImportError("shapely.geometry.Point is required to create a Point subclass") from exc

    # Capture fields and srid_map in the closure
    _fields = fields if isinstance(fields, dict) else {}
    _field_names = field_names
    _srid_map = srid_map

    def __init__(self, *coordinates, srid='unknown', **kwargs):
        if not coordinates:
            raise ValueError("At least a coordinate tuple or (x, y) must be provided")
        # Initialize the geometry base
        super(self.__class__, self).__init__(*coordinates)

        # Resolve SRID
        if isinstance(srid, str) and srid in _srid_map:
            self.srid = _srid_map[srid]
        else:
            self.srid = srid

        # Assign field values
        defaults = _fields.copy() if isinstance(_fields, dict) else {}
        for key in _field_names:
            if key in kwargs:
                setattr(self, key, kwargs[key])
            else:
                setattr(self, key, defaults.get(key, None))

    # Add documentation
    doc = f"{name} subclass of Point with fields {list(_fields.keys() if isinstance(_fields, dict) else _field_names)}"

    # Compose class dictionary
    class_dict = {'__init__': __init__, '__doc__': doc}

    try:
        new_cls = type(name, (_BasePoint,), class_dict)
    except Exception as exc:
        raise RuntimeError(f"Failed to create subclass `{name}`") from exc

    return new_cls

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Basic input validation
    if not isinstance(name, str) or not name:
        raise TypeError("name must be a non-empty string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of field names")
    if not fields:
        raise ValueError("fields must contain at least one attribute name")
    for field in fields:
        if not isinstance(field, str) or not field:
            raise TypeError("each field name must be a non-empty string")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Dynamically build the class dictionary
    class_attrs = {'__slots__': tuple(fields)}

    def __init__(self, *args, **kwargs):
        if args and kwargs:
            raise TypeError("cannot mix positional and keyword arguments")
        if args:
            if len(args) != len(fields):
                raise TypeError(f"{name}() takes {len(fields)} arguments ({len(args)} given)")
            for key, value in zip(fields, args):
                setattr(self, key, value)
        else:
            for key in fields:
                if key not in kwargs:
                    raise TypeError(f"missing required keyword argument: '{key}'")
                setattr(self, key, kwargs[key])

    def __repr__(self):
        parts = [f"{k}={getattr(self, k)!r}" for k in fields]
        return f"{name}(" + ", ".join(parts) + ")"

    def to_dict(self):
        return {k: getattr(self, k) for k in fields}

    def _srid(self):
        # Return SRID from the map if available for this point type
        return srid_map.get(name)

    class_attrs['__init__'] = __init__
    class_attrs['__repr__'] = __repr__
    class_attrs['to_dict'] = to_dict
    class_attrs['srid'] = property(_srid)

    try:
        PointCls = type(name, (object,), class_attrs)
    except Exception as exc:
        raise RuntimeError(f"Failed to create point type '{name}': {exc}") from exc

    return PointCls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("Deprecated message must be a string.")
    import functools

    def decorator(func):
        if not callable(func):
            raise TypeError("Deprecated decorator can only be applied to callable objects.")
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper

    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if seq is None:
        raise TypeError("seq must not be None")
    try:
        seq_list = list(seq)
    except TypeError:
        raise TypeError("seq must be a Sequence")
    if not all(isinstance(item, str) for item in seq_list):
        raise TypeError("All elements in seq must be str")
    if not seq_list:
        return []

    # Deterministic seeding based on the sequence content
    import hashlib
    import random
    seq_bytes = "".join(seq_list).encode("utf-8")
    seed = int(hashlib.sha256(seq_bytes).hexdigest(), 16)
    rng = random.Random(seed)
    rng.shuffle(seq_list)
    return seq_list

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle a sequence of strings without altering the original."""
    # Validate input is a sequence of strings
    try:
        iter(seq)
    except TypeError:
        raise TypeError("Input must be a sequence") from None
    result = list(seq)
    for item in result:
        if not isinstance(item, str):
            raise TypeError("All elements must be strings")

    # Create a deterministic seed from the concatenated string content
    seed = 0
    for s in result:
        for ch in s:
            seed = (seed * 31 + ord(ch)) & 0xffffffff

    # Linear Congruential Generator parameters (constant seed-derived)
    state = seed
    n = len(result)

    # Fisher–Yates shuffle using the custom PRNG
    for i in range(n - 1, 0, -1):
        state = (state * 1103515245 + 12345) & 0xffffffff
        r = (state >> 16) & 0xffff  # 16-bit pseudo-random
        j = r % (i + 1)
        result[i], result[j] = result[j], result[i]

    return result

def parse_version(s: str) -> tuple[int, ...]:
    """Parse a version string into a tuple of integers.

    The function splits the input string by dots and attempts to convert
    each component to an integer.  Non-digit components are ignored.
    If the entire component contains digits only at the start and
    is followed by non-digits, only those leading digits are used.
    For example:
        "1.2.3rc1" -> (1, 2, 3)
        "v0.9"     -> (0, 9)
        "invalid"  -> ()
    Invalid input types raise a TypeError.
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected a string for version parsing, got {type(s).__name__}")

    try:
        import re
        parts = s.split('.')
        version = []
        for part in parts:
            # Extract the leading numeric portion of the component.
            m = re.match(r'\d+', part.strip())
            if m:
                try:
                    version.append(int(m.group()))
                except ValueError:
                    # Rare case: conversion fails despite a numeric match; skip.
                    continue
        return tuple(version)
    except Exception as exc:
        # Return an empty tuple for any unexpected exception during parsing.
        return ()

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError('Input must be a string')
    import re
    numbers = re.findall(r'\d+', s)
    return tuple(int(n) for n in numbers)

def cached(cache, key=hashkey, lock=None):
    """
    Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    if cache is None:
        raise ValueError("Cache must not be None")
    if key is None:
        # Fallback key function if hashkey is not provided
        def _default_key(*args, **kwargs):
            try:
                return hash((args, frozenset(kwargs.items())))
            except Exception as e:
                raise TypeError("Default key function failed to hash arguments") from e
        key = _default_key
    if not callable(key):
        raise TypeError("key must be a callable that returns a hashable value")

    def _get_cache_value(k):
        try:
            if hasattr(cache, "get"):
                return cache.get(k)
            else:
                # Assume cache is subscriptable
                return cache[k]
        except Exception:
            return None

    def _set_cache_value(k, v):
        try:
            if hasattr(cache, "set"):
                cache.set(k, v)
            else:
                cache[k] = v
        except Exception:
            # If caching fails, silently ignore
            pass

    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                cache_key = key(*args, **kwargs)
            except Exception as e:
                raise ValueError("Key function raised an exception") from e

            # Attempt to retrieve from cache
            if lock:
                try:
                    with lock:
                        cached_val = _get_cache_value(cache_key)
                except Exception:
                    cached_val = None
            else:
                cached_val = _get_cache_value(cache_key)

            if cached_val is not None:
                return cached_val

            # Compute the value
            result = func(*args, **kwargs)

            # Store in cache
            if lock:
                try:
                    with lock:
                        _set_cache_value(cache_key, result)
                except Exception:
                    # Ignore caching errors when a lock is used
                    pass
            else:
                _set_cache_value(cache_key, result)

            return result

        # Preserve basic function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__qualname__ = getattr(func, "__qualname__", func.__name__)
        wrapper.__module__ = func.__module__
        return wrapper

    return decorator

def cached(cache, key=hashkey, lock=None):
    """
    Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute a key for the cache
            try:
                k = key(args, kwargs)
            except Exception:
                raise

            # Fast path: try reading from the cache without locking
            try:
                if isinstance(cache, dict):
                    return cache[k]
                else:
                    return cache.get(k)
            except Exception:
                pass

            # If a lock was provided, use it to avoid duplicate work
            if lock:
                lock.acquire()
                try:
                    # Double-check inside the lock
                    try:
                        if isinstance(cache, dict):
                            return cache[k]
                        else:
                            return cache.get(k)
                    except Exception:
                        pass

                    # Compute the result
                    result = func(*args, **kwargs)

                    # Store in the cache
                    try:
                        cache[k] = result
                    except Exception:
                        try:
                            cache.set(k, result)
                        except Exception:
                            pass

                    return result
                finally:
                    lock.release()
            else:
                # No lock: compute and cache the result
                result = func(*args, **kwargs)
                try:
                    cache[k] = result
                except Exception:
                    try:
                        cache.set(k, result)
                    except Exception:
                        pass
                return result

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper

    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize < 1:
        raise TypeError(f"maxsize must be a positive integer (got {maxsize!r})")
    if not isinstance(ttl, (int, float)) or ttl <= 0:
        raise ValueError(f"ttl must be a positive number (got {ttl!r})")
    if not callable(timer):
        raise TypeError(f"timer must be callable (got {timer!r})")

    def wrapper(func):
        cache = {}
        hit_counter = 0
        miss_counter = 0

        def make_key(args, kwargs):
            key = args
            if kwargs:
                # Using a unique marker to separate args from kwargs
                key += (object(),)
                for k in sorted(kwargs):
                    key += (k, kwargs[k])
            if typed:
                key += tuple(type(v) for v in args)
                for k in sorted(kwargs):
                    key += (type(kwargs[k]),)
            return key

        def decorator(*args, **kwargs):
            nonlocal hit_counter, miss_counter
            key = make_key(args, kwargs)
            now = timer()
            entry = cache.get(key)
            if entry is not None:
                value, exp = entry
                if exp > now:
                    hit_counter += 1
                    # Move key to the end to mark as recently used
                    cache.move_to_end(key)
                    return value
                else:
                    # Expired entry
                    del cache[key]
            miss_counter += 1
            # Compute new value
            value = func(*args, **kwargs)
            exp = now + ttl
            cache[key] = (value, exp)
            # Evict least-recently used if over size
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return value

        def cache_clear():
            cache.clear()

        def cache_info():
            return {"hits": hit_counter, "misses": miss_counter, "maxsize": maxsize, "currsize": len(cache)}

        decorator.cache_clear = cache_clear
        decorator.cache_info = cache_info
        return decorator

    return wrapper()

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    # Disable caching if maxsize is not positive
    if not isinstance(maxsize, int) or maxsize <= 0:
        def decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper
        return decorator

    def decorator(func):
        cache = {}
        timestamps = {}
        order = []

        def _make_key(args, kwargs):
            """Build a cache key from positional and keyword arguments.
            Raises TypeError if any component is unhashable.
            """
            kw_items = tuple(sorted(kwargs.items()))
            if typed:
                arg_types = tuple(type(v) for v in args)
                kw_types = tuple(type(v) for v in kw_items)
                return (args, kw_items, arg_types, kw_types)
            return (args, kw_items)

        def wrapper(*args, **kwargs):
            # Generate key; if fails due to unhashable argument skip cache
            try:
                key = _make_key(args, kwargs)
            except TypeError:
                return func(*args, **kwargs)

            now = timer()

            # Expire stale entries
            while order:
                oldest = order[0]
                if timestamps.get(oldest, 0) + ttl <= now:
                    order.pop(0)
                    cache.pop(oldest, None)
                    timestamps.pop(oldest, None)
                else:
                    break

            # Check cached value
            if key in cache:
                # Update recency
                try:
                    order.remove(key)
                except ValueError:
                    pass  # should not happen; safe to ignore
                order.append(key)
                return cache[key]

            # Compute fresh result and cache it
            result = func(*args, **kwargs)
            cache[key] = result
            timestamps[key] = now
            order.append(key)

            # Enforce maxsize by evicting LRU item if necessary
            if len(order) > maxsize:
                lru = order.pop(0)
                cache.pop(lru, None)
                timestamps.pop(lru, None)

            return result

        return wrapper

    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    import functools
    if maxsize is not None and maxsize <= 0:
        raise ValueError("maxsize must be greater than 0 or None")
    if ttl <= 0:
        raise ValueError("ttl must be positive")

    def _make_key(args, kwargs):
        """Construct a hashable key from positional and keyword arguments.
        If `typed` is True, include the types of positional arguments in the key.
        """
        key = args
        if kwargs:
            key += tuple(sorted(kwargs.items()))
        if typed:
            key += tuple(type(arg) for arg in args)
        return key

    def decorating_function(func):
        cache = {}
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs)
            now = timer()
            try:
                result, expiry = cache[key]
            except KeyError:
                pass
            else:
                if expiry > now:
                    # Refresh order for LRU
                    cache[key] = (result, expiry)
                    return result
                # Expired entry
                del cache[key]
            # Compute result
            result = func(*args, **kwargs)
            expiry = now + ttl
            cache[key] = (result, expiry)
            # Maintain LRU order; dict preserves insertion order,
            # so we move the key to the end on each access.
            # In Python 3.7+, dict.move_to_end is available.
            try:
                dict.move_to_end(cache, key)
            except AttributeError:
                # For older Python versions, we skip reordering.
                pass
            # Enforce maximum size
            if maxsize is not None and len(cache) > maxsize:
                # popitem(last=False) removes the oldest (LRU) entry
                try:
                    cache.popitem(last=False)
                except AttributeError:
                    # For dicts lacking popitem(last=False), emulate by deleting first key
                    first_key = next(iter(cache))
                    del cache[first_key]
            return result

        return wrapper

    return decorating_function

def mru_cache(maxsize=128, typed=False):
    """
    Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")

    def decorating_function(user_function):
        cache = {}
        order = []  # keep key order, most recent at the end

        def make_key(args, kwargs):
            key = args
            if kwargs:
                # sort kwargs items to make key deterministic
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            try:
                hash(key)
            except TypeError:
                raise TypeError("Argument types must be hashable for caching")
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                # move key to the end to mark it as most recent
                try:
                    order.remove(key)
                except ValueError:
                    pass
                order.append(key)
                return cache[key]
            result = user_function(*args, **kwargs)
            cache[key] = result
            order.append(key)
            if len(cache) > maxsize:
                # evict the most recently used item
                evict_key = order.pop()
                cache.pop(evict_key, None)
            return result

        # Preserve function metadata
        wrapper.__name__ = user_function.__name__
        wrapper.__doc__ = user_function.__doc__
        wrapper.__module__ = user_function.__module__
        wrapper.__qualname__ = getattr(user_function, "__qualname__", user_function.__name__)
        return wrapper

    return decorating_function

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    def decorating_function(user_function):
        cache = {}
        order = []  # keeps keys in order; most recently used at the end
        def wrapper(*args, **kwargs):
            # Build cache key
            key = args
            if kwargs:
                try:
                    key += tuple(sorted(kwargs.items()))
                except Exception:
                    # If kwargs contain unhashable values, raise TypeError
                    raise TypeError("Kwargs must be hashable")
            if typed:
                try:
                    key += tuple(type(v) for v in args)
                except Exception:
                    raise TypeError("Arguments must be hashable for typed cache")
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            try:
                value = cache[key]
                # Move key to the end to mark it as most recently used
                order.remove(key)
                order.append(key)
                return value
            except KeyError:
                value = user_function(*args, **kwargs)
                cache[key] = value
                order.append(key)
                if len(order) > maxsize:
                    # Evict the most recently used item
                    evict_key = order.pop()  # last item is MRU
                    del cache[evict_key]
