def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    import traceback
    import os

    def _shorten_path(path, level):
        parts = path.split(os.sep)
        return os.sep.join(parts[-level:]) if len(parts) > level else path

    def _format_stack(tb):
        if tb is None:
            return ""
        extracted = traceback.extract_tb(tb)
        # Limit to max_level frames
        extracted = extracted[-max_level:]
        lines = []
        for frame in extracted:
            filename = _shorten_path(frame.filename, max_path_level)
            lines.append(f'  File "{filename}", line {frame.lineno}, in {frame.name}\n    {frame.line}')
        return "\n".join(lines)

    def _format_exception(ex, level=0):
        try:
            exc_type = type(ex).__name__
            exc_msg = str(ex)
        except Exception:
            exc_type = "<unknown>"
            exc_msg = "<error retrieving message>"
        header = f"{exc_type}: {exc_msg}"
        stack = _format_stack(ex.__traceback__)
        result = header
        if stack:
            result += "\nStack (most recent call last):\n" + stack
        # Handle causes
        if getattr(ex, "__cause__", None):
            result += "\nCaused by:\n" + _format_exception(ex.__cause__, level + 1)
        # Handle context (exception during handling)
        if getattr(ex, "__context__", None) and not getattr(ex, "__suppress_context__", False):
            result += "\nDuring handling of the above exception, another exception occurred:\n" + _format_exception(ex.__context__, level + 1)
        return result

    try:
        if not isinstance(e, BaseException):
            return f"Invalid exception object: {e!r}"
        return _format_exception(e)
    except Exception as err:
        return f"Error formatting exception: {err!r}"

def file_to_textbuffer(file_name, encoding):
    """
    Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    if not isinstance(file_name, str) or not isinstance(encoding, str):
        return None
    try:
        with open(file_name, mode='r', encoding=encoding) as f:
            return f.read()
    except (FileNotFoundError, PermissionError, UnicodeDecodeError, OSError):
        return None
    except Exception:
        return None

