def _reset_logging(cls):
    """
    Reset the root logger by removing all handlers and restoring the default
    logging level. This method can be safely called multiple times.
    """
    try:
        root = logging.getLogger()
        # Remove and close existing handlers
        for handler in root.handlers[:]:
            root.removeHandler(handler)
            try:
                handler.close()
            except Exception:
                # Ignore errors while closing handlers
                pass
        # Reset the level to the default
        root.setLevel(logging.WARNING)
    except Exception as exc:
        # If anything goes wrong we log the exception at the root logger
        # but do not propagate the exception
        try:
            logging.getLogger().error("Failed to reset logging: %s", exc)
        except Exception:
            pass
    return None

