def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            continue
        if cls in seen:
            continue
        redundant = False
        for base in result:
            try:
                if issubclass(cls, base) or issubclass(base, cls):
                    redundant = True
                    break
            except TypeError:
                # Skip non‑class arguments; they are not valid bases
                redundant = True
                break
        if redundant:
            continue
        result.append(cls)
        seen.add(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect
    if not isinstance(all, bool):
        raise ValueError("'all' must be a boolean")
    try:
        cls = self.__class__
        attrs = {}
        # Retrieve all non-callable, non-private attributes from the class
        for name, value in inspect.getmembers(cls):
            if name.startswith('_'):
                continue
            if callable(value):
                continue
            # Attempt to find a description for the attribute.
            # Common conventions: <name>_desc or <name>_description
            desc = ""
            for suffix in ("_desc", "_description", "description"):
                description_attr = f"{name}{suffix}"
                if hasattr(cls, description_attr):
                    desc_candidate = getattr(cls, description_attr)
                    if isinstance(desc_candidate, str):
                        desc = desc_candidate
                        break
            # If no explicit description, try to use the attribute's docstring (if any)
            if desc == "" and hasattr(value, "__doc__") and value.__doc__:
                desc = value.__doc__
            attrs[name] = desc
        # If all=False, return only attributes that have a non-empty description
        if not all:
            attrs = {k: v for k, v in attrs.items() if v}
        return attrs
    except Exception as exc:
        raise RuntimeError("Failed to retrieve interface names and descriptions") from exc

