def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # prepare output container
    if output is None:
        output = []

    # Helper to decide whether something is a simple interface/implements spec
    def _is_single_spec(obj):
        # A tuple of two non-iterable items is treated as a spec (e.g. (interface, impl))
        if isinstance(obj, tuple) and len(obj) == 2:
            a, b = obj
            for x in (a, b):
                if isinstance(x, (list, set, tuple)):
                    return False
                if isinstance(x, (str, bytes)):
                    continue
                # if not iterable or specifically a type, treat as spec
            return True
        return False

    # If sequence is None, nothing to do
    if sequence is None:
        return output

    # If sequence itself is not iterable (but we don't want to treat strings as iterable here)
    if not hasattr(sequence, "__iter__") or isinstance(sequence, (str, bytes, bytearray)):
        output.append(sequence)
        return output

    for elem in sequence:
        # Skip if elem is None (could be intentional placeholder)
        if elem is None:
            continue

        # Strings and bytes are treated as individual interfaces
        if isinstance(elem, (str, bytes, bytearray)):
            output.append(elem)
            continue

        # If element is a tuple and qualifies as a spec, don't expand
        if _is_single_spec(elem):
            output.append(elem)
            continue

        # For any other iterable (list, set, tuple, etc.), recursive normalization
        if hasattr(elem, "__iter__"):
            _normalizeargs(elem, output)
        else:
            # Scalar element; add directly
            output.append(elem)

    return output

