def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import os
        import sys
    except Exception:
        # Unable to import required modules; do not attempt C optimizations
        return False

    # If the PURE_PYTHON environment variable is explicitly set to a truthy value,
    # we should not attempt C optimizations (the user requested pure Python).
    try:
        pure_python_val = os.getenv('PURE_PYTHON')
        if pure_python_val is not None:
            # Common truthy values to interpret as "force pure Python"
            if pure_python_val.lower() in {'1', 'true', 'yes', 'y'}:
                return False
    except Exception:
        # Silently ignore any unexpected errors while checking the env var
        pass

    # Avoid using C extensions on PyPy, which may not support or may
    # require additional configuration.  The presence of the
    # 'implementation' attribute and its 'name' attribute is used to
    # determine the interpreter type.
    try:
        if getattr(sys, 'implementation', None) is not None:
            if getattr(sys.implementation, 'name', None) == 'pypy':
                return False
    except Exception:
        pass

    # If we made it here, we assume attempting C optimizations is safe
    return True

