    """
    # Reset the internal context
    if hasattr(self, "_context"):
        try:
            self._context.clear()
        except Exception:
            self._context = {}
    else:
        self._context = {}

    # Reinitialize bins
    if hasattr(self, "_initial_value"):
        self._bins = self._initial_value
    else:
        if hasattr(self, "make_bins") and callable(self.make_bins):
            try:
                self._bins = self.make_bins()
            except Exception as exc:
                raise RuntimeError("Failed to reinitialize bins") from exc
        else:
            # Fallback to an empty structure if no initialization logic is available
            self._bins = {}

def reset(self):
    """Reset the histogram.
