    Bins are reinitialized with the *initial_value* or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset context
        self.context = {}
        # Reinitialize bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Preserve the structure of existing bins if possible
            if isinstance(self.bins, dict):
                self.bins = {k: self.initial_value for k in self.bins}
            elif hasattr(self.bins, "__len__"):
                # If bins is a list-like, reinitialize with the same shape
                self.bins = type(self.bins)([self.initial_value] * len(self.bins))
            else:
                # Fallback: try to use make_bins if available
                if hasattr(self, "make_bins"):
                    self.bins = self.make_bins()
                else:
                    raise AttributeError("Cannot reinitialize bins: incompatible type and no make_bins")
        else:
            if hasattr(self, "make_bins"):
                self.bins = self.make_bins()
            else:
                raise AttributeError("Cannot reinitialize bins: no initial_value and no make_bins")
    except Exception as exc:
        raise RuntimeError(f"Histogram reset failed: {exc}") from exc

