    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset context
        if hasattr(self, "_context"):
            self._context = {}
        else:
            self.context = {}
    except Exception:
        # If context attribute is read-only or missing, ignore
        pass

    # Reinitialize bins
    try:
        # If an explicit initial value is defined
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Preserve the current number of bins
            if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                length = len(self.bins)
                self.bins = [self.initial_value] * length
            else:
                # If bins attribute is missing, start with a single bin
                self.bins = [self.initial_value]
        # If a make_bins callable is available
        elif hasattr(self, "make_bins") and callable(self.make_bins):
            self.bins = self.make_bins()
        else:
            # Fallback: empty bins
            self.bins = []
    except Exception:
        # If any error occurs during bin reinitialisation, set bins to empty
