def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset context to an empty dictionary
        self.context = {}
        # Reinitialize bins based on *initial_value* or *make_bins()*
        if getattr(self, "initial_value", None) is not None:
            # Make a defensive copy for mutable types to avoid shared references
            val = self.initial_value
            if isinstance(val, (list, tuple, set, dict)):
                # Preserve the exact container type
                if isinstance(val, list):
                    self.bins = list(val)
                elif isinstance(val, tuple):
                    self.bins = tuple(val)
                elif isinstance(val, set):
                    self.bins = set(val)
                else:  # dict
                    self.bins = dict(val)
            else:
                self.bins = val
        else:
            # Assume a callable make_bins exists; reinitialize bins
            make_bins = getattr(self, "make_bins", None)
            if make_bins is None:
                raise AttributeError("No 'make_bins' method found to reinitialize bins.")
            self.bins = make_bins()
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Ensure separator is a string
    try:
        separator = str(separator)
    except Exception:
        separator = ","

    lines = []

    # Add header if provided
    if header is not None:
        lines.append(str(header))

    # Helper to determine if an object is a sequence but not a string/bytes
    def is_sequence(obj):
        return (
            hasattr(obj, "__iter__") and
            not isinstance(obj, (str, bytes, bytearray))
        )

    # Iterate over all points in the graph
    try:
        iterable_points = iter(self.points)
    except Exception as e:
        raise TypeError(f"self.points is not iterable: {e}") from e

    for point in iterable_points:
        # Default: the string representation of the point
        line = str(point)

        try:
            # Try to interpret the point as a (coordinate, value) pair
            coord, val = point[0], point[1]
            # Handle coordinate: could be a single value or a sequence
            if is_sequence(coord):
                coord_str = separator.join(str(v) for v in coord)
            else:
                coord_str = str(coord)

            # Handle value: could be a single value or a sequence
            if is_sequence(val):
                val_str = separator.join(str(v) for v in val)
            else:
                val_str = str(val)

            line = separator.join([coord_str, val_str])
        except Exception:
            # If unpacking fails, fallback to string representation
            line = str(point)

        lines.append(line)

    # Join all lines into a single CSV string
    return "\n".join(lines)

def to_csv(self, separator=",", header=None):
        """
        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.
        """

        lines = []
        try:
            if header is not None:
                lines.append(str(header))
        except Exception:
            # If header cannot be converted to string, ignore it
            pass

        for point in self:
            try:
                # Try unpacking as (coord, value)
                coord, val = point
            except Exception:
                # Fallback: point may have attributes
                if hasattr(point, "coord") and hasattr(point, "value"):
                    coord, val = point.coord, point.value
                elif hasattr(point, "coord") and hasattr(point, "val"):
                    coord, val = point.coord, point.val
                else:
                    continue  # Cannot determine coordinate/value, skip this point

            try:
                # Convert coordinates
                coord_items = (
                    (coord,) if not hasattr(coord, "__iter__") or isinstance(coord, (str, bytes))
                    else tuple(coord)
                )
                coord_str = separator.join(str(c) for c in coord_items)
            except Exception:
                coord_str = ""

            try:
                # Convert value(s)
                if hasattr(val, "__iter__") and not isinstance(val, (str, bytes)):
                    val_str = separator.join(str(v) for v in val)
                else:
                    val_str = str(val)
            except Exception:
                val_str = ""

            # Combine coordinate and value parts
            if coord_str and val_str:
                line = coord_str + separator + val_str
            elif coord_str:
                line = coord_str
            elif val_str:
                line = val_str
            else:
                line = ""

            lines.append(line)

        return "\n".join(lines)

def to_csv(self, separator=",", header=None):
        """
        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional, for each point first its
        coordinate is converted to string (separated by *separator*), then
        each part of its value.

        Returns
        -------
        str
            CSV representation of the graph.
        """
        # Ensure separator is a string; if not, coerce it.
        try:
            sep = str(separator)
        except Exception:
            sep = ","

        # Collect points from the graph.  The graph object is expected to
        # expose its points via a `points` attribute; otherwise we fall
        # back to iterating over the graph itself.
        try:
            points_iter = iter(self.points)
        except AttributeError:
            points_iter = iter(self)

        rows = []
        for point in points_iter:
            # Attempt to extract coordinate and value parts.
            coords = None
            value = None

            # Case 1: point is an object with coordinates/value attributes
            if hasattr(point, "coordinates"):
                coords = getattr(point, "coordinates")
                value = getattr(point, "value", None)
            elif hasattr(point, "coord"):
                coords = getattr(point, "coord")
                value = getattr(point, "value", None)
            # Case 2: point is a 2‑tuple or sequence of (coords, value)
            elif hasattr(point, "__getitem__"):
                try:
                    coords = point[0]
                    value = point[1] if len(point) > 1 else None
                except Exception:
                    coords = point
                    value = None
            # Case 3: point is a scalar or simple type
            else:
                coords = point
                value = None

            # Normalize coordinates to an iterable of components.
            if isinstance(coords, (str, bytes)):
                coord_components = [coords]
            else:
                try:
                    coord_components = list(coords)
                except Exception:
                    coord_components = [coords]

            # Normalize value to components if present.
            if value is not None:
                if isinstance(value, (list, tuple)):
                    value_components = [str(v) for v in value]
                else:
                    value_components = [str(value)]
            else:
                value_components = []

            # Build a single CSV row.
            try:
                row = sep.join(str(c) for c in coord_components)
                if value_components:
                    row += sep + sep.join(value_components)
                rows.append(row)
            except Exception as exc:
                # Skip rows that cannot be processed.
                raise ValueError(f"Unable to convert point {point!r} to CSV: {exc}")

        csv_output = "\n".join(rows)

        # Prepend header if provided.
        if header is not None:
            csv_output = f"{header}\n{csv_output}"

        return csv_output

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional, for each point first its
    coordinate is converted to string (separated by *separator*), then
    each part of its value.
    """
    # Validate arguments
    if separator is None:
        separator = ","
    if not isinstance(separator, str):
        raise TypeError(f"separator must be a string, got {type(separator).__name__}")
    if header is not None and not isinstance(header, str):
        raise TypeError(f"header must be a string or None, got {type(header).__name__}")

    lines = []
    if header is not None:
        lines.append(header.rstrip("\n"))

    # Attempt to iterate over graph points
    try:
        points_iter = iter(self)
    except TypeError as exc:
        raise TypeError("The graph object is not iterable") from exc

    for point in points_iter:
        # Each point is expected to be a tuple (coord, value)
        # coord can be an iterable of coordinates
        # value can be a scalar or an iterable of values
        try:
            coord, value = point
        except Exception as exc:
            raise ValueError(f"Invalid point format {point!r}") from exc

        # Process coordinates
        if hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes)):
            coord_str = separator.join(str(v) for v in coord)
        else:
            coord_str = str(coord)

        # Process values
        if hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
            value_str = separator.join(str(v) for v in value)
        else:
            value_str = str(value)

        # Combine coordinate and values
        if value_str:
            line = separator.join([coord_str, value_str])
        else:
            line = coord_str
        lines.append(line)

    return "\n".join(lines) + ("\n" if lines else "")

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    try:
        points = getattr(self, "points", None)
        if points is None:
            raise ValueError("The object has no 'points' attribute.")
        rows = []

        if header is not None:
            rows.append(str(header))

        for pt in points:
            # Extract coordinates
            if hasattr(pt, "coords"):
                coords = pt.coords
            else:
                # Try to treat pt as a tuple/list of coordinates
                coords = pt

            # Extract value
            if hasattr(pt, "value"):
                val = pt.value
            elif hasattr(pt, "vals"):
                val = pt.vals
            else:
                # If pt itself has only coordinates (no value)
                val = None

            parts = []

            # Add coordinate parts
            try:
                for c in coords:
                    parts.append(str(c))
            except TypeError:
                # If coords is not iterable, treat as single coordinate
                parts.append(str(coords))

            # Add value parts
            if val is not None:
                if isinstance(val, (list, tuple)):
                    for v in val:
                        parts.append(str(v))
                else:
                    parts.append(str(val))

            rows.append(separator.join(parts))

        return "\n".join(rows)
    except Exception as exc:
        raise ValueError(f"Failed to convert graph to CSV: {exc}") from exc

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate the type of coord_name
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Attempt to retrieve the error indices mapping
    try:
        mapping = getattr(self, "_err_indices")
    except AttributeError as exc:
        raise AttributeError("Error indices mapping '_err_indices' not found on the instance.") from exc

    # Ensure the mapping is a dictionary
    if not isinstance(mapping, dict):
        raise TypeError("The attribute '_err_indices' should be a dictionary mapping coordinate names to indices.")

    # Check that the requested coordinate exists
    if coord_name not in mapping:
        raise KeyError(f"Coordinate '{coord_name}' is not present in the error indices mapping.")

    # Retrieve and validate the indices
    indices = mapping[coord_name]
    if not isinstance(indices, (list, tuple)):
        raise ValueError("Error indices for a coordinate must be a list or tuple.")

    # Return a copy to avoid accidental modifications of the original list
    return list(indices)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input type
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # Attempt to retrieve the error indices mapping attribute
    # It is expected that the class stores a dictionary mapping coordinate names
    # to iterable collections of indices (e.g., lists, tuples, numpy arrays).
    err_map = getattr(self, "_error_indices", None)

    # If no such mapping exists, fall back to an empty list
    if err_map is None:
        return []

    # Retrieve indices for the specified coordinate name
    try:
        indices = err_map[coord_name]
    except KeyError:
        # Coordinate name not present in the mapping
        return []

    # Normalize the result to a list
    try:
        return list(indices)
    except TypeError:
        # If indices is not iterable (unlikely but defensive), return empty list
        return []

def _update_context(self, context):
    """
    Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors. Example subcontext for a graph
    with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}. Note that error names are called "x", "y"
    and "z" (this corresponds to first three coordinates, if they are present),
    and existing values are not removed from *context.value*.
    """
    # Validate the input.
    if context is None:
        raise TypeError("context cannot be None")
    if not isinstance(context, dict):
        raise TypeError("context must be a dictionary")

    # Prepare the error container.
    errors_subctx = context.get("error")
    if errors_subctx is None:
        errors_subctx = {}
        context["error"] = errors_subctx
    elif not isinstance(errors_subctx, dict):
        # If error exists but is not a dict, we cannot safely merge.
        raise TypeError("context['error'] must be a dictionary")

    # Determine coordinate mapping: first three non‑error field names.
    # We consider the order of fields as they appear in self._fields dict.
    coordinates = [
        name for name in self._fields
        if not name.startswith("error_")
    ][:3]

    coord_to_axis = {}
    for idx, coord_name in enumerate(coordinates):
        if idx == 0:
            coord_to_axis[coord_name] = "x"
        elif idx == 1:
            coord_to_axis[coord_name] = "y"
        elif idx == 2:
            coord_to_axis[coord_name] = "z"

    # Iterate over error fields and add to the context.
    for field_name, field_obj in self._fields.items():
        if not field_name.startswith("error_"):
            continue

        # Expected format: error_<coordinate>_<suffix>
        parts = field_name.split("_", 2)
        if len(parts) < 3:
            # Skip malformed names silently.
            continue

        _, coord_part, suffix = parts
        axis = coord_to_axis.get(coord_part)
        if axis is None:
            # The coordinate is not among the first three; skip.
            continue

        key = f"{axis}_{suffix}"
        # Field objects are expected to have an 'index' attribute.
        index = getattr(field_obj, "index", None)
        if index is None:
            # If no index is available, we cannot record it.
            continue

        errors_subctx[key] = {"index": index}

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np
    # Ensure inputs are array-like
    bins = np.asarray(bins)
    try:
        edges_arr = np.asarray(edges)
    except Exception as exc:
        raise ValueError(f"edges must be array-like, got {type(edges)}") from exc

    # 1D histogram
    if edges_arr.ndim == 1:
        if bins.ndim != 1:
            raise ValueError(
                f"bins must be 1-D array for 1-D edges, got shape {bins.shape}"
            )
        if bins.size != (edges_arr.size - 1):
            raise ValueError(
                f"bins length {bins.size} does not match edges difference {edges_arr.size - 1}"
            )
        widths = np.diff(edges_arr)
        return float(np.sum(bins * widths))

    # Multi-dimensional histogram
    # edges should be a sequence of 1-D arrays
    if isinstance(edges, (list, tuple)):
        width_lists = []
        for i, e in enumerate(edges):
            e_arr = np.asarray(e)
            if e_arr.ndim != 1:
                raise ValueError(
                    f"edge at index {i} is not 1-D (got shape {e_arr.shape})"
                )
            if e_arr.size < 2:
                raise ValueError(
                    f"edge at index {i} must contain at least two points"
                )
            width_lists.append(np.diff(e_arr))
        # Compute weight product along each dimension
        try:
            weights = width_lists[0]
            for w in width_lists[1:]:
                weights = np.multiply.outer(weights, w)
            # Ensure shape matches bins
            if weights.shape != bins.shape:
                raise ValueError(
                    f"Product of bin widths shape {weights.shape} does not match bins shape {bins.shape}"
                )
            return float(np.sum(bins * weights))
        except Exception as exc:
            raise ValueError(f"Failed to compute integral: {exc}") from exc
    else:
        raise ValueError(
            f"edges must be 1-D array or sequence of 1-D arrays, got {type(edges)}"
        )

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic type checks
    try:
        bins_list = list(bins)
    except Exception as e:
        raise TypeError("bins must be an iterable") from e
    try:
        edges_list = list(edges)
    except Exception as e:
        raise TypeError("edges must be an iterable") from e

    if len(edges_list) < 2:
        raise ValueError("edges must contain at least two boundary values")
    if len(bins_list) != len(edges_list) - 1:
        raise ValueError("length of bins must be one less than length of edges")

    # Compute widths
    widths = []
    for i in range(len(edges_list) - 1):
        try:
            width = float(edges_list[i + 1]) - float(edges_list[i])
        except Exception as e:
            raise ValueError(f"edge values must be numeric: {e}") from e
        if width < 0:
            raise ValueError("edges must be in non-decreasing order")
        widths.append(width)

    # Compute integral
    total = 0.0
    for b, w in zip(bins_list, widths):
        try:
            val = float(b)
        except Exception as e:
            raise ValueError(f"bin value must be numeric: {e}") from e
        total += val * w

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Exclude Source sequences
        if isinstance(seq, Source):
            return False
        # Single element that's a FillRequest
        if isinstance(seq, FillRequest):
            return True
        # Iterable sequences
        if isinstance(seq, (list, tuple, set)):
            return any(isinstance(item, FillRequest) for item in seq)
        # If it's some other iterable (e.g., generator), try iterating once
        if hasattr(seq, "__iter__"):
            return any(isinstance(item, FillRequest) for item in seq)
    except Exception:
        # If Source/FillRequest is not defined or seq is not iterable, fall through
        pass
    return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Handle None or non-iterable inputs gracefully
    if seq is None:
        return False

    # Helper to get the class name in a safe way
    def _class_name(obj):
        try:
            return obj.__class__.__name__
        except Exception:
            return None

    # If seq itself is a Source, immediately reject
    if _class_name(seq) == "Source":
        return False

    # If seq is itself a FillRequest, accept
    if _class_name(seq) == "FillRequest":
        return True

    # Determine iterable items
    items = None
    if isinstance(seq, dict):
        # For dictionaries, consider the values
        items = seq.values()
    else:
        try:
            # Try to iterate directly
            iter(seq)
            items = seq
        except Exception:
            # seq is not iterable; cannot be a sequence of FillRequests
            return False

    # Scan for at least one FillRequest element
    for item in items:
        try:
            if _class_name(item) == "FillRequest":
                return True
        except Exception:
            # skip elements that raise on class name retrieval
            continue

    # No FillRequest found
    return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # First, rule out Source sequences if the class is available
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source class not defined; ignore this check
        pass

    # Check if seq itself is a FillRequest
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest class not defined; we will fall back to iterable logic
        pass

    # If seq is a concrete collection type, iterate over its elements
    if isinstance(seq, (list, tuple, set, frozenset)):
        for item in seq:
            try:
                if isinstance(item, FillRequest):
                    return True
            except NameError:
                # If FillRequest is undefined, ignore this item
                continue
        return False

    # For other iterable types, attempt to iterate
    try:
