            if isinstance(val1, dict) and isinstance(val2, dict):
                if depth == 0:
                    # depth limit reached: don't recurse
                    continue
                # Recurse with decremented depth unless infinite
                next_depth = -1 if depth == -1 else depth - 1
                sub_res = _diff(val1, val2, next_depth)
                if sub_res:                     # add only non‑empty diffs
                    result[key] = sub_res
                continue

            # For non‑dict values, include if they differ
            if val1 != val2 and depth != 0:
                result[key] = val1
        return result

    return _diff(d1, d2, level)

