            # If both are dicts and we can recurse
            if isinstance(val, dict) and isinstance(bval, dict) and lev != 1:
                # Determine next level: decrement only if lev > 0
                next_level = lev - 1 if lev > 0 else -1
                sub_diff = _diff(val, bval, next_level)
                if sub_diff:
