    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("difference requires two dictionaries")

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # Key missing in d2 – copy the value
            result[key] = val1 if isinstance(val1, dict) else val1
        else:
            val2 = d2[key]
            # Both values are dictionaries and recursion is allowed
            if isinstance(val1, dict) and isinstance(val2, dict) and (level != 0):
                # Determine the recursion depth for sub‑dictionary
                sublevel = level - 1 if level > 0 else -1
                subdiff = difference(val1, val2, sublevel)
