def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure that the histogram has the required attributes
    if not hasattr(self, "edges") or not hasattr(self, "data"):
        raise AttributeError("Histogram object must have 'edges' and 'data' attributes")

    # Convert coord to a numpy array for easier handling
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as e:
        raise TypeError(f"coord must be array-like or scalar, got {type(coord)}") from e

    # Support single coordinate for 1-D histograms
    if self.edges is not None and len(self.edges) == 1 and coord_arr.ndim == 0:
        coord_arr = np.array([coord_arr], dtype=float)

    # Verify dimensionality matches the histogram
    if coord_arr.ndim != 1 or coord_arr.shape[0] != len(self.edges):
        raise ValueError(
            f"coord dimension {coord_arr.shape[0]} does not match histogram dimensions {len(self.edges)}"
        )

    # Find the bin indices for each dimension
    bin_indices = []
    for i, (edge, c) in enumerate(zip(self.edges, coord_arr)):
        try:
            idx = np.searchsorted(edge, c, side="right") - 1
        except Exception as e:
            raise ValueError(f"Failed to compute bin for dimension {i}") from e

        # Check if coordinate is outside the range
        if idx < 0 or idx >= (len(edge) - 1):
            # Outside histogram edges: ignore
            return
        bin_indices.append(idx)

    # Increment the bin count by the specified weight
    try:
        self.data[tuple(bin_indices)] += weight
    except Exception as e:
        raise ValueError("Failed to update histogram bin with given weight") from e
    return None

