def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    try:
        import re
    except Exception as exc:
        raise RuntimeError("Required module 're' is missing") from exc

    # Regular expressions for label keys and values
    # These are typical Kubernetes label regexes; adjust if different patterns are required.
    LABEL_KEY_REGEX = re.compile(r'^[A-Za-z0-9._-]{1,63}$')
    LABEL_VALUE_REGEX = re.compile(r'^[A-Za-z0-9._-]{0,63}$')

    if not isinstance(labels, dict):
        raise TypeError("labels must be a dict")

    errors = []

    # Helper to record an error entry
    def _add_error(identifier, message):
        errors.append({str(identifier): message})

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            _add_error(repr(key), 'expected string or bytes-like object')
        else:
            # Apply key regex
            try:
                if not LABEL_KEY_REGEX.match(key):
                    _add_error(key, f"Label key '{key}' does not match the regex [...]")
            except Exception as exc:
                _add_error(key, f"Error applying key regex: {exc}")

        # Validate value type and content
        # Sentinels for iterable (but not string/bytes)
        iterable_types = (list, tuple, set, frozenset)
        if isinstance(value, iterable_types):
            # For iterable values we validate each element.
            for v in value:
                if not isinstance(v, (str, bytes)):
                    _add_error(repr(v), 'expected string or bytes-like object')
                else:
                    try:
                        if not LABEL_VALUE_REGEX.match(v):
                            _add_error(v, f"Label value '{v}' does not match the regex [...]")
                    except Exception as exc:
                        _add_error(v, f"Error applying value regex: {exc}")
        else:
            if not isinstance(value, (str, bytes)):
                _add_error(repr(value), 'expected string or bytes-like object')
            else:
                try:
                    if not LABEL_VALUE_REGEX.match(value):
                        _add_error(value, f"Label value '{value}' does not match the regex [...]")
                except Exception as exc:
                    _add_error(value, f"Error applying value regex: {exc}")

    if errors:
        # Assume ValidationError is defined elsewhere in the project.
        try:
            ValidationError  # Check existence
        except NameError:
            # Define a simple placeholder if not available
            class ValidationError(Exception):
                def __init__(self, messages):
                    self.messages = messages
                    super().__init__("Label validation failed")
        raise ValidationError(messages=errors)

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression.
    """
    errors = []

    # Assume a regular expression object for keys is available in the module scope.
    key_regex = None
    try:
        key_regex = _LABEL_KEY_REGEX  # should be defined elsewhere
    except NameError:
        # If no regex is defined, skip regex validation.
        pass

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key against regex if available
            if key_regex is not None:
                try:
                    # _LABEL_KEY_REGEX is assumed to be a compiled regex
                    if not key_regex.search(key):
                        errors.append({key: f"Label key '{key}' does not match the regex {key_regex.pattern}"})
                except Exception:
                    # If regex matching fails for any reason, ignore this check
                    pass

        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    if not isinstance(value, str):
        raise ValidationError("value must be a string")
    if not value:
        raise ValidationError("value cannot be empty")
    if not value.isalnum():
        raise ValidationError(f"value '{value}' must contain only alphanumeric characters")

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    # Basic sanity checks
    if not isinstance(key, str):
        raise ValidationError("Key must be a string.")

    # Define acceptance criteria (length and allowed characters)
    min_len, max_len = 8, 64
    if not (min_len <= len(key) <= max_len):
        raise ValidationError(
            f"Key length must be between {min_len} and {max_len} characters."
        )

    # Allowed characters: alphanumerics, hyphen, underscore
    for ch in key:
        if not (ch.isalnum() or ch in "-_"):
            raise ValidationError(
                f"Key contains invalid character: '{ch}'. Allowed characters are "
                "letters, digits, hyphens, and underscores."
            )

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    try:
        # Ensure key is a string
        if not isinstance(key, str):
            raise ValidationError("Key must be a string")

        # Define the expected pattern: 32 characters, only uppercase letters and digits
        if len(key) != 32:
            raise ValidationError("Key must be 32 characters long")

        for char in key:
            if not (char.isdigit() or (char.isalpha() and char.isupper())):
                raise ValidationError("Key must contain only uppercase letters and digits")

    except ValidationError:
        # Re‑raise ValidationError unchanged
        raise
    except Exception as exc:
        # Convert any other unexpected exception into a ValidationError
        raise ValidationError(f"Unexpected error during key validation: {exc}") from exc
    # If no exception was raised, the key is considered valid
    return None

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a default observer schema dictionary from a part of a Kubernetes
    resource definition.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): If ``True``, indicates that the dictionary
            represents the complete observer schema for a Kubernetes resource.

    Returns:
        dict: A dictionary mirroring the structure of ``manifest_dict`` but with
        all non-dict and non-list values replaced by ``None``. When
        ``first_level`` is ``True`` the top‑level primitive values are preserved
        (to retain identifying fields such as ``apiVersion`` and ``kind``).

    Raises:
        TypeError: If *manifest_dict* is not a mapping.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    def _process_list(l):
        processed = []
        for item in l:
            if isinstance(item, dict):
                processed.append(generate_default_observer_schema_dict(item, first_level=False))
            elif isinstance(item, list):
                processed.append(_process_list(item))
            else:
                processed.append(None)
        return processed

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries; never preserve values at
            # deeper levels unless explicitly allowed by the caller.
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            result[key] = _process_list(value)
        else:
            # Primitive values: keep them only when first_level is True,
            # otherwise replace with None.
            result[key] = value if first_level else None
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively build a default observer_schema dictionary from a manifest.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer_schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    The function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.  For the first level of recursion,
    values of the identifying top‑level fields (`apiVersion`, `kind`, `metadata`)
    are kept as‑is.
    """
    try:
        if not isinstance(manifest_dict, dict):
            return {}

        default_schema = {}
        id_fields = {"apiVersion", "kind", "metadata"}

        for key, value in manifest_dict.items():
            if isinstance(value, dict):
                # Recurse into nested dictionaries; they are not first level
                default_schema[key] = generate_default_observer_schema_dict(value, first_level=False)
            elif isinstance(value, list):
                # Preserve list structure but replace each element with None
                default_schema[key] = [None for _ in value]
            else:
                # Leaf value
                if first_level and key in id_fields:
                    default_schema[key] = value
                else:
                    default_schema[key] = None

        return default_schema
    except Exception as exc:
        # In case of unexpected errors, return an empty dict to maintain API contract
        return {}

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a default observer schema dictionary from a Kubernetes resource
    partial dictionary, replacing non-dict/non-list values with ``None``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If ``True``, this dictionary represents the
            root of the observer schema. Identifying fields are preserved from the
            source manifest.

    Returns:
        dict: The default observer schema.

    Raises:
        TypeError: If ``manifest_dict`` is not a dictionary.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("`manifest_dict` must be a dictionary")

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recursively build the schema for nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Preserve lists; they are handled by the list-specific routine
            result[key] = value
        else:
            # Replace scalar values with None
            result[key] = None

    if first_level:
        # Preserve identifying fields from the original manifest
        identifying_keys = ("apiVersion", "kind", "metadata")
        for key in identifying_keys:
            if key in manifest_dict:
                result[key] = manifest_dict[key]

    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Recursively update a partial ``last_applied_manifest`` list from a partial
    Kubernetes response, filling missing fields according to ``observer_schema``.

    Args:
        last_applied_manifest (list): The list to be updated in-place.
        observer_schema (list): List of schema descriptors describing the expected
            fields.  Each schema descriptor is expected to be a dict containing
            at least the key ``"field_name"``, and optionally ``"observer_schema"``
            for nested structures.
        response (list): Partial Kubernetes API response.

    Returns:
        list: The updated ``last_applied_manifest`` list (same object as passed in).

    Raises:
        TypeError: If ``response`` is not a list or contains non-dict elements.
    """
    # Defensive checks
    if response is None:
        return last_applied_manifest or []

    if not isinstance(response, list):
        raise TypeError("response must be a list")

    if last_applied_manifest is None:
        last_applied_manifest = []

    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")

    # Ensure observer_schema is a list; if None, set to empty
    if observer_schema is None:
        observer_schema = []
    elif not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")

    # Helper to find schema descriptor for a given field name
    def _find_schema(field_name):
        for s in observer_schema:
            if isinstance(s, dict) and s.get("field_name") == field_name:
                return s
        return None

    for idx, resp_item in enumerate(response):
        if not isinstance(resp_item, dict):
            raise TypeError("Items in response list must be dicts")

        # Ensure we have a corresponding dict in last_applied_manifest
        if idx >= len(last_applied_manifest):
            last_applied_manifest.append({})
        manifest_item = last_applied_manifest[idx]

        if not isinstance(manifest_item, dict):
            # Replace non-dict with a dict to safely merge
            last_applied_manifest[idx] = {}
            manifest_item = last_applied_manifest[idx]

        # Merge fields
        for key, val in resp_item.items():
            # Determine if this field needs nested handling
            schema_desc = _find_schema(key)
            sub_schema = schema_desc.get("observer_schema") if schema_desc else None

            if key not in manifest_item:
                # If key missing, set it directly, handling nested structures
                if isinstance(val, dict):
                    if sub_schema is not None:
                        # Ensure the nested dict exists
                        manifest_item[key] = {}
                        # Recursively update nested dict
                        update_last_applied_manifest_dict_from_resp(
                            manifest_item[key], sub_schema, val
                        )
                    else:
                        manifest_item[key] = val
                elif isinstance(val, list):
                    if sub_schema is not None:
                        manifest_item[key] = []
                        update_last_applied_manifest_list_from_resp(
                            manifest_item[key], sub_schema, val
                        )
                    else:
                        manifest_item[key] = val
                else:
                    manifest_item[key] = val
            else:
                # If key exists, merge nested structures if appropriate
                existing_val = manifest_item[key]
                if isinstance(val, dict) and isinstance(existing_val, dict):
                    if sub_schema is not None:
                        update_last_applied_manifest_dict_from_resp(
                            existing_val, sub_schema, val
                        )
                elif isinstance(val, list) and isinstance(existing_val, list):
                    if sub_schema is not None:
                        update_last_applied_manifest_list_from_resp(
                            existing_val, sub_schema, val
                        )
                # For scalar values we leave the existing value untouched

    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial `last_applied_manifest` list from a partial
    Kubernetes response.

    Parameters
    ----------
    last_applied_manifest : list
        Partial `last_applied_manifest` being updated.
    observer_schema : list
        Partial `observer_schema` describing the observed fields.
    response : list
        Partial response from the Kubernetes API.

    Notes
    -----
    * If an element in the response is a dict or a list and the matching
      element in `last_applied_manifest` is missing, it will be initialized
      by a recursive call to the corresponding update function.
    * If the matching element is present but empty (None or {} or []), it is
      preserved and not overwritten.
    * Missing indices in `last_applied_manifest` are filled with the response
      values.
    """
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    # Ensure last_applied_manifest is a list
    if last_applied_manifest is None:
        last_applied_manifest = []
    elif not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    # Ensure observer_schema is a list (required for consistency)
    if observer_schema is None:
        observer_schema = []
    elif not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")

    # Expand last_applied_manifest to match the length of response
    # indices that do not exist will be appended with None and then replaced
    # below if necessary.
    while len(last_applied_manifest) < len(response):
        last_applied_manifest.append(None)

    for idx, resp_elem in enumerate(response):
        try:
            last_elem = last_applied_manifest[idx]
        except IndexError:
            # Should not happen because we expanded list, but guard anyway
            last_applied_manifest.append(resp_elem)
            continue

        # If the last element is None or empty, we want to initialize it
        if last_elem is None or (isinstance(last_elem, (dict, list)) and not last_elem):
            # If the element is a dict and observer_schema provides info,
            # delegate to the dict updater
            if isinstance(resp_elem, dict):
                from __builtins__ import getattr as _getattr
                # We look for an update function for dicts
                update_dict = _getattr(
                    globals(), "update_last_applied_manifest_dict_from_resp", None
                )
                if update_dict:
                    # If observer_schema has a dict entry for this index,
                    # pass it, else pass an empty list/dict
                    sub_schema = (
                        observer_schema[idx]
                        if isinstance(observer_schema, (list, tuple))
                        and idx < len(observer_schema)
                        else {}
                    )
                    update_dict(last_elem or {}, sub_schema, resp_elem)
                    last_applied_manifest[idx] = last_elem or {}
                else:
                    # Fallback: simply copy the whole dict
                    last_applied_manifest[idx] = resp_elem.copy()
            elif isinstance(resp_elem, list):
                # Recursive call for list element
                update_last_applied_manifest_list_from_resp(
                    last_elem or [], observer_schema[idx] if idx < len(observer_schema) else [],
                    resp_elem,
                )
                last_applied_manifest[idx] = last_elem or []
            else:
                # Primitive type: simply copy
                last_applied_manifest[idx] = resp_elem
        else:
            # If last_elem is present and is a dict or list, we need to
            # recursively merge observed fields
            if isinstance(resp_elem, dict) and isinstance(last_elem, dict):
                update_dict = globals().get("update_last_applied_manifest_dict_from_resp")
                if update_dict:
                    sub_schema = (
                        observer_schema[idx]
                        if isinstance(observer_schema, (list, tuple))
                        and idx < len(observer_schema)
                        else {}
                    )
                    update_dict(last_elem, sub_schema, resp_elem)
            elif isinstance(resp_elem, list) and isinstance(last_elem, list):
                update_last_applied_manifest_list_from_resp(
                    last_elem, observer_schema[idx] if idx < len(observer_schema) else [],
                    resp_elem,
                )
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update ``last_applied_manifest`` with observed fields from
    ``response`` according to ``observer_schema``.

    Parameters
    ----------
    last_applied_manifest : dict
        The manifest to be updated.  It is modified in‑place.
    observer_schema : dict
        Schema describing which fields of ``response`` should be observed.
    response : dict
        Partial Kubernetes response containing the actual values.
    """
    # Basic sanity checks
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            f"last_applied_manifest must be a dict, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(observer_schema, dict):
        raise TypeError(
            f"observer_schema must be a dict, got {type(observer_schema).__name__}"
        )
    if not isinstance(response, dict):
        raise TypeError(
            f"response must be a dict, got {type(response).__name__}"
        )

    for key, sub_schema in observer_schema.items():
        # Ensure the key is present in the Kubernetes response
        if key not in response:
            raise KeyError(
                f"Observed field '{key}' not present in the Kubernetes response"
            )

        resp_val = response[key]

        # If the value in the response is a mapping, recurse
        if isinstance(resp_val, dict):
            # Initialise nested dict in the manifest if missing
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            # Recurse into nested structure, passing the corresponding sub‑schema
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], sub_schema, resp_val
            )
        else:
            # For leaf nodes, set the value only if it is absent in the manifest
            if key not in last_applied_manifest:
                last_applied_manifest[key] = resp_val

    return None  # The manifest is modified in place.

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its default observer schema.
    """
    # Validate input
    if app is None:
        raise TypeError("app must not be None")
    if not hasattr(app, "spec"):
        raise AttributeError("app must have a 'spec' attribute")
    manifest = getattr(app.spec, "manifest", None)
    if manifest is None:
        raise AttributeError("app.spec must have a 'manifest' attribute")

    default_schemas = {}
    try:
        for resource in manifest:
            if not isinstance(resource, dict):
                # Skip non‑dict entries in the manifest
                continue
            kind = resource.get("kind")
            if not kind:
                # Skip entries without a kind
                continue
            # If the resource already specifies an observer schema, skip it
            if "observer_schema" in resource:
                continue
            # Construct a very permissive default schema
            default_schema = {
                "type": "object",
                "properties": {}
            }
            default_schemas[kind] = default_schema
    except Exception:
        # In case of any unexpected error during iteration, just return what we have so far
        return default_schemas

    return default_schemas

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        None

    Raises:
        ValueError: If the input app or its expected attributes are missing.
        TypeError: If the manifest is not a mapping or list.
        RuntimeError: If any unexpected error occurs during processing.
    """
    # Basic input validation
    if app is None:
        raise ValueError("The 'app' argument must not be None.")
    spec = getattr(app, "spec", None)
    if spec is None:
        raise ValueError("The 'app' object does not have a 'spec' attribute.")
    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise ValueError("The 'spec' object does not have a 'manifest' attribute.")

    # Accept both dictionary and list of resources
    if not isinstance(manifest, (dict, list)):
        raise TypeError("The 'spec.manifest' attribute must be a dict or list.")

    # Default schema to apply
    default_schema = {"type": "object", "properties": {}}

    # Helper to apply default schema to a single resource
    def _apply_to_resource(resource):
        try:
            if isinstance(resource, dict):
                if resource.get("observer_schema") is None:
                    resource["observer_schema"] = default_schema
            else:
                # Use attribute access for object instances
                if getattr(resource, "observer_schema", None) is None:
                    setattr(resource, "observer_schema", default_schema)
        except Exception as exc:
            # Log the error and continue with the next resource
            # (Logging omitted due to constraints; re-raise if desired)
            raise RuntimeError(
                f"Failed to apply default schema to resource: {resource}"
            ) from exc

    # Iterate over resources
    try:
        if isinstance(manifest, dict):
            resources = manifest.values()
        else:
            resources = manifest
        for res in resources:
            _apply_to_resource(res)
    except Exception as exc:
        raise RuntimeError(
            "An error occurred while generating default observer schemas."
        ) from exc

    return None

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        spec = getattr(app, "spec", None)
        if spec is None:
            raise ValueError("The application object must have a 'spec' attribute")

        manifest = getattr(spec, "manifest", None)
        if not isinstance(manifest, dict):
            raise ValueError(
                "The 'spec.manifest' attribute must be a dictionary of resources"
            )

        observer_schema = getattr(spec, "observer_schema", None)
        if observer_schema is None or not isinstance(observer_schema, dict):
            # Ensure the attribute exists and is a dictionary
            setattr(spec, "observer_schema", {})
            observer_schema = spec.observer_schema

        for resource_name in manifest:
            if resource_name not in observer_schema:
                # Create a minimal default schema for the resource
                observer_schema[resource_name] = {"type": "object", "properties": {}}
    except Exception as exc:
        raise RuntimeError(
            f"Unable to generate default observer schema: {exc}"
        ) from exc

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of input
    if app is None:
        raise ValueError("The 'app' argument cannot be None.")

    # Attempt to access spec and manifest attributes safely
    spec = getattr(app, "spec", None)
    if spec is None:
        raise ValueError("The application does not contain a 'spec' attribute.")

    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise ValueError("The application spec does not contain a 'manifest' attribute.")

    # Ensure manifest is an iterable of resources
    if not isinstance(manifest, (list, tuple)):
        raise TypeError("The 'manifest' attribute must be a list or tuple of resources.")

    generated_schemas = []

    for resource in manifest:
        # Skip non-dict resources
        if not isinstance(resource, dict):
            continue

        # If a custom observer schema is already specified, skip this resource
        if "custom_observer_schema" in resource:
            continue

        # Extract name and namespace for naming the observer
        metadata = resource.get("metadata", {})
        name = metadata.get("name", "unknown-resource")
        namespace = metadata.get("namespace", "default")

        # Build a simple default observer schema
        default_schema = {
            "apiVersion": "v1",
            "kind": "Observer",
            "metadata": {
                "name": f"{name}-observer",
                "namespace": namespace,
                "labels": {
                    "generated-by": "krake",
                    "original-resource": name
                }
            },
            "spec": {
                "observedResource": {
                    "apiVersion": resource.get("apiVersion", "v1"),
                    "kind": resource.get("kind", "Unknown"),
                    "metadata": {
                        "name": name,
                        "namespace": namespace
                    },
                    "spec": resource.get("spec", {})
                },
                # Default configuration can be extended here
                "notify": {
                    "enabled": True
                }
            }
        }

        generated_schemas.append(default_schema)

    return generated_schemas

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.
    """
    import re
    # Ensure we work with string internally
    is_bytes = isinstance(sql, (bytes, bytearray, memoryview))
    sql_str = sql.decode("utf-8") if is_bytes else str(sql)

    in_style = getattr(self, "SQLParams", None) and getattr(self.SQLParams, "in_style", None)
    out_style = getattr(self, "SQLParams", None) and getattr(self.SQLParams, "out_style", None)

    if in_style is None or out_style is None:
        # Fallback – return the original SQL and parameters unchanged
        return sql, list(many_params)

    # Normalise out_style for consistency
    out_style = out_style.lower()

    # Prepare placeholders based on in_style
    placeholder_order: List[Union[str, int]] = []

    def _replace_named(match):
        name = match.group(1)
        placeholder_order.append(name)
        if out_style == "named":
            return f":{name}"
        elif out_style == "pyformat":
            return f"%({name})s"
        elif out_style == "qmark":
            return "?"
        elif out_style == "numeric":
            idx = placeholder_order.index(name) + 1
            return f":{idx}"
        elif out_style == "format":
            return "%s"
        return match.group(0)

    def _replace_ordinal(match):
        num = int(match.group(1))
        placeholder_order.append(num)
        if out_style == "named":
            return f":param{num}"
        elif out_style == "pyformat":
            return f"%({num})s"
        elif out_style == "qmark":
            return "?"
        elif out_style == "numeric":
            return f":{num}"
        elif out_style == "format":
            return "%s"
        return match.group(0)

    # Convert SQL
    if in_style.lower() == "named":
        pattern_named = re.compile(r":([a-zA-Z_][a-zA-Z0-9_]*)")
        formatted_sql = pattern_named.sub(_replace_named, sql_str)
    elif in_style.lower() == "ordinal":
        # Supports $1, $2, … placeholders
        pattern_ordinal = re.compile(r"\$(\d+)")
        formatted_sql = pattern_ordinal.sub(_replace_ordinal, sql_str)
    else:
        # Unknown in_style – return original
        formatted_sql = sql_str

    # Convert parameters
    out_params_list: List[Union[Dict[Union[str, int], Any], Sequence[Any]]] = []

    for param_set in many_params:
        if out_style in ("named", "pyformat"):
            # Output mapping – maintain keys
            if isinstance(param_set, Mapping):
                out_params_list.append(dict(param_set))
            else:
                # Convert sequence to mapping with generic keys if needed
                try:
                    out_params_list.append(
                        {f"param{i+1}": v for i, v in enumerate(param_set)}
                    )
                except Exception:
                    out_params_list.append(param_set)
        else:
            # Positional output – order according to placeholder_order
            if isinstance(param_set, Mapping):
                # Source values by key order
                try:
                    out_params_list.append([param_set.get(k) for k in placeholder_order])
                except Exception:
                    out_params_list.append(list(param_set.values()))
            else:
                # Sequence – ensure enough elements
                try:
                    out_params_list.append([param_set[k] for k in range(len(placeholder_order))])
                except Exception:
                    out_params_list.append(list(param_set))

    # Preserve original type
    out_sql: AnyStr = formatted_sql.encode("utf-8") if is_bytes else formatted_sql
    return out_sql, out_params_list

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    Returns a :class:`tuple` containing:

    - The formatted SQL query (:class:`str` or :class:`bytes`).
    - A :class:`list` containing each set of converted out-style
      parameters (:class:`dict` or :class:`list`).
    """
    try:
        # Prepare output list
        out_list: List[Sequence[Any]] = []

        # Helper to determine if an object behaves like a mapping
        def is_mapping(x):
            return isinstance(x, dict) or hasattr(x, "keys")

        # Helper to determine if an object is a sequence but not a string or bytes
        def is_sequence(x):
            return isinstance(x, (list, tuple, set)) and not isinstance(x, (str, bytes))

        for params in many_params:
            if is_mapping(params):
                # Convert mapping values to a list preserving order
                try:
                    out_list.append(list(params.values()))
                except Exception as exc:
                    raise ValueError(f"Cannot convert mapping to list: {exc}") from exc
            elif is_sequence(params):
                out_list.append(list(params))
            else:
                raise TypeError(
                    f"Expected each params to be a mapping or a sequence, got {type(params)!r}"
                )

        return sql, out_list

    except Exception as exc:
        # Wrap any exception into a ValueError for consistency
        raise ValueError(f"formatmany failed: {exc}") from exc

def formatmany(self, sql, many_params):
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    Returns a :class:`tuple` containing:

    - The formatted SQL query (:class:`str` or :class:`bytes`).

    - A :class:`list` containing each set of converted out-style
      parameters (:class:`dict` or :class:`list`).
    """
    # Basic type checks
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes, got %r" % type(sql))

    try:
        from collections.abc import Mapping, Sequence, Iterable
    except Exception:
        # Fallback for older Python versions
        from collections import Mapping, Sequence, Iterable

    # Determine styles; they should be attributes of `self`
    try:
        in_style = getattr(self, "in_style")
        out_style = getattr(self, "out_style")
    except AttributeError:
        raise AttributeError("self must have 'in_style' and 'out_style' attributes")

    # Validate styles
    valid_styles = {"named", "ordinal"}
    if in_style not in valid_styles or out_style not in valid_styles:
        raise ValueError("in_style and out_style must be 'named' or 'ordinal'")

    # Helper to detect placeholder pattern
    import re

    if in_style == "named":
        placeholder_pat_raw = r":(\w+)"
    else:  # ordinal
        placeholder_pat_raw = r"\?"

    placeholder_pat = re.compile(placeholder_pat_raw)
    placeholder_names = placeholder_pat.findall(sql if isinstance(sql, str) else sql.decode())

    # Build mapping from placeholder to output placeholder
    if out_style == "named":
        # For named output, placeholder format is %(name)s
        if in_style == "named":
            out_sql = re.sub(placeholder_pat, r"%(\1)s", sql if isinstance(sql, str) else sql.decode())
        else:  # in ordinal, generate sequential names
            tmp_names = [f"param{i+1}" for i in range(len(placeholder_names))]
            def repl(match, names=iter(tmp_names)):
                return "%(%s)s" % next(names)
            out_sql = placeholder_pat.sub(repl, sql if isinstance(sql, str) else sql.decode())
    else:  # out ordinal
        # Use %s for every placeholder
        out_sql = placeholder_pat.sub("%s", sql if isinstance(sql, str) else sql.decode())

    if isinstance(sql, bytes):
        out_sql = out_sql.encode()

    # Prepare output parameter list
    out_params_list = []

    for param_set_index, params in enumerate(many_params):
        # Normalize param_set
        if isinstance(params, Mapping):
            param_dict = dict(params)
        elif isinstance(params, Sequence) and not isinstance(params, (str, bytes)):
            param_list = list(params)
        else:
            raise TypeError(
                f"Each param set must be a mapping or sequence, got {type(params)} (index {param_set_index})"
            )

        if in_style == "named":
            # Ensure keys match placeholder names
            if out_style == "named":
                out_params_list.append(param_dict)
            else:  # out ordinal
                out_list = []
                for name in placeholder_names:
                    if name not in param_dict:
                        raise KeyError(f"Missing parameter '{name}' for placeholder at index {param_set_index}")
                    out_list.append(param_dict[name])
                out_params_list.append(out_list)
        else:  # in_style ordinal
            # Ensure list length matches number of placeholders
            if out_style == "named":
                if len(param_list) != len(placeholder_names):
                    raise ValueError(
                        f"Length of parameter list ({len(param_list)}) does not match number of placeholders "
                        f"({len(placeholder_names)}) at index {param_set_index}"
                    )
                out_dict = {name: param_list[i] for i, name in enumerate(placeholder_names)}
                out_params_list.append(out_dict)
            else:  # both ordinal
                if len(param_list) != len(placeholder_names):
                    raise ValueError(
                        f"Length of parameter list ({len(param_list)}) does not match number of placeholders "
                        f"({len(placeholder_names)}) at index {param_set_index}"
                    )
                out_params_list.append(param_list)

    return out_sql, out_params_list

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Resolve the root path
        root = os.path.abspath(str(path))
        if not os.path.isdir(root):
            return False

        # Check for .ocfl_version file
        ocfl_version_file = os.path.join(root, '.ocfl_version')
        if not os.path.isfile(ocfl_version_file):
            return False
        with open(ocfl_version_file, 'r', encoding='utf-8') as f:
            version = f.read().strip()
        if not version:
            return False
        try:
            int(version)
        except ValueError:
            return False

        # Check for objects directory
        objects_dir = os.path.join(root, 'objects')
        if not os.path.isdir(objects_dir):
            return False
        # Verify at least one object directory exists
        object_dirs = [
            d for d in os.listdir(objects_dir)
            if os.path.isdir(os.path.join(objects_dir, d))
        ]
        if not object_dirs:
            return False

        # Basic validation of the first object
        first_obj_path = os.path.join(objects_dir, object_dirs[0])
        content_dir = os.path.join(first_obj_path, 'content')
        metadata_file = os.path.join(first_obj_path, 'metadata')
        if not os.path.isdir(content_dir) or not os.path.isfile(metadata_file):
            return False

        # All checks passed
        return True
    except Exception:
        return False

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Helper to compute SHA‑256 digest of a file-like object in chunks
    def _sha256_file(file_obj, chunk_size=65536):
        import hashlib
        h = hashlib.sha256()
        while True:
            data = file_obj.read(chunk_size)
            if not data:
                break
            h.update(data)
        return h.hexdigest()

    # Detect whether path is a local filesystem path or a pyfs root
    is_pyfs = hasattr(path, "exists") and hasattr(path, "isdir") and hasattr(path, "listdir") \
               and hasattr(path, "open")

    try:
        if is_pyfs:
            root = None  # pyfs root itself
            pyfs = path
        else:
            # local filesystem path
            import os
            root = os.path.abspath(str(path))
            if not os.path.isdir(root):
                return False
            pyfs = None

        # Locate the manifest file
        manifest_name = None

        if pyfs:
            # pyfs: look for files at root level
            entries = pyfs.listdir("")
            for entry in entries:
                if entry.lower() == "manifest" or entry.lower().endswith(".manifest"):
                    manifest_name = entry
                    break
        else:
            import os
            for entry in os.listdir(root):
                if entry.lower() == "manifest" or entry.lower().endswith(".manifest"):
                    manifest_name = entry
                    break

        if manifest_name is None:
            # No manifest found – not a valid OCFL object
            return False

        # Read and parse the manifest
        if pyfs:
            with pyfs.open(manifest_name, "rb") as f:
                content = f.read().decode("utf-8", errors="replace")
        else:
            import os
            with open(os.path.join(root, manifest_name), "rb") as f:
                content = f.read().decode("utf-8", errors="replace")

        for line in content.splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                # Skip empty lines and comments
                continue
            # Expected format: "<digest>  <path>"
            parts = line.split(maxsplit=1)
            if len(parts) != 2:
                return False
            expected_digest, rel_path = parts
            # Normalize path separators
            import os
            rel_path = rel_path.replace("\\", "/")
            # Compute actual digest
            try:
                if pyfs:
                    if not pyfs.exists(rel_path):
                        return False
                    with pyfs.open(rel_path, "rb") as f:
                        actual_digest = _sha256_file(f)
                else:
                    full_path = os.path.join(root, rel_path)
                    if not os.path.isfile(full_path):
                        return False
                    with open(full_path, "rb") as f:
                        actual_digest = _sha256_file(f)
            except Exception:
                return False
            if actual_digest.lower() != expected_digest.lower():
                return False

        # All checks passed
        return True

    except Exception:
        # Any unexpected error invalidates the object
        return False

def status_str(self, prefix=''):
        """Return string of validator status, with optional prefix."""
        # Ensure prefix is a string
        try:
            prefix = str(prefix) if prefix is not None else ''
        except Exception:
            prefix = ''

        parts = []

        # Gather counts of various status elements if available
        errors = getattr(self, 'errors', [])
        failures = getattr(self, 'failures', [])
        warnings = getattr(self, 'warnings', [])

        try:
            error_count = len(errors) if isinstance(errors, (list, tuple, set)) else 0
        except Exception:
            error_count = 0

        try:
            failure_count = len(failures) if isinstance(failures, (list, tuple, set)) else 0
        except Exception:
            failure_count = 0

        try:
            warning_count = len(warnings) if isinstance(warnings, (list, tuple, set)) else 0
        except Exception:
            warning_count = 0

        # Build status description
        if error_count == 0 and failure_count == 0:
            parts.append('OK')
        else:
            if error_count:
                parts.append(f'{error_count} error{"s" if error_count != 1 else ""}')
            if failure_count:
                parts.append(f'{failure_count} failure{"s" if failure_count != 1 else ""}')
            if warning_count:
                parts.append(f'{warning_count} warning{"s" if warning_count != 1 else ""}')

        status = ', '.join(parts) if parts else 'UNKNOWN'

        return f'{prefix}{status}'

def status_str(self, prefix=''):
