                        "typeC": "3.0",
                    }
                    spec_version = type_to_version.get(type_value, spec_version)
                # else keep default

            # Simple validation rules based on spec_version
            if spec_version == "1.0":
                # Need 'name' and 'items' keys
                if "name" not in inventory or "items" not in inventory:
                    return False
                if not isinstance(inventory["items"], list):
                    return False
            elif spec_version == "2.0":
                # Need 'name', 'items', and 'metadata'
                if "name" not in inventory or "items" not in inventory or "metadata" not in inventory:
                    return False
                if not isinstance(inventory["items"], list):
                    return False
                if not isinstance(inventory["metadata"], dict):
                    return False
            elif spec_version == "3.0":
                # Need 'name', 'components', 'config'
                if "name" not in inventory or "components" not in inventory or "config" not in inventory:
                    return False
                if not isinstance(inventory["components"], list):
                    return False
                if not isinstance(inventory["config"], dict):
                    return False
            else:
                # Unknown spec version: consider it invalid
                return False

            # Generic checks: name should be non-empty string
            name = inventory.get("name")
            if not isinstance(name, str) or not name.strip():
                return False

            # If all checks passed
            return True

        except Exception:
            # In case of any unexpected exception during validation, treat as invalid
            return False

def validate(self, inventory, extract_spec_version=False):
