                    candidate_version = inventory.get("spec_version")
                    if candidate_version in supported_versions:
                        self.spec_version = candidate_version
            else:
                # If we can't determine it from ``type``, leave ``self.spec_version`` as it was
                pass

        # ---------- Inventory validation logic ----------
        # Determine the required fields for the current spec_version
        required_fields = getattr(
            getattr(self, "spec_definitions", {}), self.spec_version, {}
        ).get("required", [])
        if not isinstance(required_fields, list):
