def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input iterable types
    if not hasattr(manifest_files, "__iter__") or isinstance(manifest_files, (str, bytes)):
        raise TypeError("manifest_files must be an iterable of mapping objects.")
    if not hasattr(digests_used, "__iter__") or isinstance(digests_used, (str, bytes)):
        raise TypeError("digests_used must be an iterable of digests.")

    # Collect digests reported in the manifest
    digests_present = set()
    for entry in manifest_files:
        if isinstance(entry, dict):
            digest = entry.get("digest")
            if digest:
                digests_present.add(digest)

    # Convert the used digests to a set for efficient comparison
    digests_used_set = set(digests_used)

    # Identify any digests that are claimed to be used but not present in the manifest
    missing_in_manifest = digests_used_set - digests_present
    if missing_in_manifest:
        raise ValueError(f"Missing digests in manifest: {missing_in_manifest}")

    # All required digests are present; optional: warn about unused entries
    return True   # Indicate successful validation'''

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping filenames to digests")
    # Accept digests_used as any iterable – convert to a set for fast lookup.
    try:
        used_set = set(digests_used)
    except TypeError:
        raise TypeError("digests_used must be an iterable of digest values")
    # Collect all digest values declared in the manifest.
    manifest_set = set(manifest_files.values())
    # A digest that was used but does not appear in the manifest is an error.
    missing_in_manifest = used_set - manifest_set
    if missing_in_manifest:
        raise ValueError(
            f"Used digests missing from manifest: {sorted(missing_in_manifest)}"
        )
    # Optionally, warn if a digest is present in the manifest but never used.
    unused_in_manifest = manifest_set - used_set
    if unused_in_manifest:
        raise ValueError(
            f"Manifest digests that were never used: {sorted(unused_in_manifest)}"
        )
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure digests_used is iterable and can be converted to a set
    try:
        digests_used_set = set(digests_used)
    except Exception as exc:
        raise TypeError("digests_used must be an iterable of digest values") from exc

    required_digests = set()
    # Iterate over each manifest entry
    for idx, manifest in enumerate(manifest_files):
        # If the manifest is a dictionary, look for a 'digests' key or treat dict keys as digests
        if isinstance(manifest, dict):
            # Prefer explicit 'digests' entry if present
            if 'digests' in manifest:
                digests = manifest['digests']
                if isinstance(digests, (list, set, tuple)):
                    required_digests.update(digests)
                else:
                    # If not a standard iterable, try to convert
                    try:
                        required_digests.update(list(digests))
                    except Exception:
                        raise ValueError(f"Unsupported digest format in manifest at index {idx}")
            else:
                # If 'digests' key is missing, use all values of the dict as digests
                required_digests.update(manifest.values())
        elif hasattr(manifest, "__iter__") and not isinstance(manifest, (str, bytes)):
            # Assume any other iterable contains digest values
            try:
                required_digests.update(manifest)
            except Exception:
                raise ValueError(f"Unsupported digest format in manifest at index {idx}")
        else:
            # Non-iterable manifest entry is considered a single digest
            required_digests.add(manifest)

    # Identify missing digests
    missing = required_digests - digests_used_set
    if missing:
        missing_list = ", ".join(map(str, sorted(missing)))
        raise ValueError(f"The following digests are required by the manifest but were not used: {missing_list}")

    # Optionally, check for unexpected digests used but not required by the manifest
    # UNUSED = digests_used_set - required_digests
    # if UNUSED:
    #     raise ValueError(f"Unused digests detected: {', '.join(map(str, sorted(UNUSED)))}")

    # If everything checks out, simply return None (or True if preferred)
    return None

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    try:
        expected_digests = set()
        for file_entry in manifest_files or []:
            digests = None
            if isinstance(file_entry, dict):
                digests = file_entry.get('digests')
            elif hasattr(file_entry, 'digests'):
                digests = getattr(file_entry, 'digests')
            # ignore entries with no digests field
            if digests is None:
                continue
            if isinstance(digests, dict):
                expected_digests.update(digests.keys())
            elif isinstance(digests, (list, set, tuple)):
                for item in digests:
                    if isinstance(item, dict):
                        expected_digests.update(item.keys())
                    elif isinstance(item, str):
                        expected_digests.add(item)
            else:
                # if digests is a single string, treat as one name
                if isinstance(digests, str):
                    expected_digests.add(digests)
        used_digests = set(digests_used or [])
        missing = expected_digests - used_digests
        unused = used_digests - expected_digests
        if missing or unused:
            messages = []
            if missing:
                messages.append(f"Missing used digests: {', '.join(sorted(missing))}.")
            if unused:
                messages.append(f"Unused digests present: {', '.join(sorted(unused))}.")
            raise ValueError(' '.join(messages))
    except Exception as exc:
        raise ValueError(f"Error while checking digests: {exc}") from exc

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure that 'prior' is an InventoryValidator instance of the same class
    if not isinstance(prior, type(self)):
        raise TypeError(
            "prior must be an instance of the same InventoryValidator class"
        )

    # ----- Identifier consistency ------------------------------------------------
    # Common identifier attribute names that might be present in InventoryValidator
    id_attrs = ("inventory_id", "id", "identifier", "inventory_identifier")
    self_identifier = None
    prior_identifier = None
    for attr in id_attrs:
        if hasattr(self, attr) and hasattr(prior, attr):
            self_identifier = getattr(self, attr)
            prior_identifier = getattr(prior, attr)
            break

    if self_identifier is not None and prior_identifier is not None:
        if self_identifier != prior_identifier:
            raise ValueError(
                f"Inventory identifiers do not match: {self_identifier} vs {prior_identifier}"
            )

    # ----- Version comparison -----------------------------------------------------
    ver_attrs = ("version", "inventory_version")
    self_ver = None
    prior_ver = None
    for attr in ver_attrs:
        if hasattr(self, attr) and hasattr(prior, attr):
            self_ver = getattr(self, attr)
            prior_ver = getattr(prior, attr)
            break

    if self_ver is not None and prior_ver is not None:
        # Ensure that the current version is strictly greater
        try:
            if self_ver <= prior_ver:
                raise ValueError(
                    f"Current version {self_ver} must be greater than prior version {prior_ver}"
                )
        except TypeError:
            # If the objects are not directly comparable, we skip the numerical
            # comparison but still keep a warning flag for future consideration.
            pass

    # ----- Date comparison --------------------------------------------------------
    date_attrs = ("created", "created_date", "timestamp", "date", "modified")
    self_date = None
    prior_date = None
    for attr in date_attrs:
        if hasattr(self, attr) and hasattr(prior, attr):
            self_date = getattr(self, attr)
            prior_date = getattr(prior, attr)
            break

    if self_date is not None and prior_date is not None:
        # This block expects the objects to support ordering (<, >)
        try:
            if self_date <= prior_date:
                raise ValueError(
                    f"Current creation date {self_date} must be after prior creation date {prior_date}"
                )
        except TypeError:
            # If dates are not comparable (e.g., strings), ignore this check
            pass

    # ----- Items subset check -----------------------------------------------------
    # Assume both objects expose a collection of items under the same attribute
    # name (common patterns: 'items', 'entries', 'records')
    items_attr_candidates = ("items", "entries", "records")
    for attr in items_attr_candidates:
        if hasattr(self, attr) and hasattr(prior, attr):
            current_items = getattr(self, attr)
            prior_items = getattr(prior, attr)
            if (
                isinstance(current_items, (list, set, tuple))
                and isinstance(prior_items, (list, set, tuple))
            ):
                if not set(prior_items).issubset(set(current_items)):
                    raise ValueError(
                        f"Prior items are not a subset of the current inventory items"
                    )
            break

    # If all checks passed, nothing to return (validation succeeded)
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type and existence checks
    if prior is None:
        raise ValueError("prior is None")

    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an InventoryValidator instance")

    if not hasattr(self, "inventory") or not hasattr(prior, "inventory"):
        raise AttributeError("Both objects must have an 'inventory' attribute")

    curr_inv = self.inventory
    prior_inv = prior.inventory

    # Helper to extract id and version, supporting dicts or objects with attributes
    def _get_id(inv):
        if isinstance(inv, dict):
            return inv.get("id")
        return getattr(inv, "id", None)

    def _get_version(inv):
        if isinstance(inv, dict):
            return inv.get("version")
        return getattr(inv, "version", None)

    curr_id = _get_id(curr_inv)
    prior_id = _get_id(prior_inv)

    if curr_id != prior_id:
        raise ValueError(f"Inventory IDs do not match: {curr_id!r} vs {prior_id!r}")

    curr_version = _get_version(curr_inv)
    prior_version = _get_version(prior_inv)

    if curr_version is None or prior_version is None:
        raise ValueError("Version information is missing in one of the inventories")

    try:
        if prior_version >= curr_version:
            raise ValueError(
                f"Prior version {prior_version!r} must be less than current version {curr_version!r}"
            )
    except TypeError:
        # If versions are incomparable, skip this check but warn
        pass

    # Optionally compare the inventory structure (keys if dict)
    if isinstance(curr_inv, dict) and isinstance(prior_inv, dict):
        if set(curr_inv.keys()) != set(prior_inv.keys()):
            raise ValueError("Inventory structures differ between current and prior")

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Verify that the object is an InventoryValidator instance
    if not hasattr(prior, "inventory"):
        raise TypeError(
            "prior must be an InventoryValidator instance with an 'inventory' attribute"
        )

    # Both self and prior should have an 'inventory' attribute that is a mapping
    if not isinstance(getattr(self, "inventory", None), dict):
        raise ValueError("self.inventory must be a dictionary")
    if not isinstance(prior.inventory, dict):
        raise ValueError("prior.inventory must be a dictionary")

    # Check that the two inventories are of the same type
    self_type = self.inventory.get("type")
    prior_type = prior.inventory.get("type")
    if self_type != prior_type:
        raise ValueError(
            f"Inventory types differ: self is '{self_type}', prior is '{prior_type}'"
        )

    # Ensure that both inventories have an 'id' (or 'version') key
    self_id = self.inventory.get("id") or self.inventory.get("version")
    prior_id = prior.inventory.get("id") or prior.inventory.get("version")
    if self_id is None or prior_id is None:
        raise ValueError("Both inventories must contain an 'id' or 'version' key")

    # Attempt a numeric comparison of the ids to ensure prior is older
    try:
        if int(prior_id) >= int(self_id):
            raise ValueError(
                f"Prior version id ({prior_id}) must be less than current ({self_id})"
            )
    except Exception:
        # If ids cannot be compared as ints, fall back to string comparison
        if prior_id >= self_id:
            raise ValueError(
                f"Prior version id ('{prior_id}') must be less than current ('{self_id}')"
            )

    # If all checks pass, consider the validation successful
    return True

def validate_as_prior_version(self, prior):
    """
    Check that ``prior`` is a valid prior version of the current inventory object.

    The input variable ``prior`` is also expected to be an InventoryValidator object
    and both ``self`` and ``prior`` inventories are assumed to have been checked for
    internal consistency.

    The method performs the following checks:

    1. ``prior`` must be an instance of the same validator class as ``self``.
    2. The inventory version of ``prior`` must be strictly less than the current
       inventory version.
    3. All items present in ``prior`` must also be present in the current inventory.

    If any check fails, a ``ValueError`` or ``TypeError`` is raised with an
    explanatory message.

    Returns
    -------
    bool
        ``True`` if the validation passes.
    """
    # 1. Check that prior is the same type
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"Argument ``prior`` must be an instance of the same class as ``self`` (got {type(prior).__name__})"
        )

    # Helper for retrieving an attribute that may be named differently
    def _get_attr(obj, primary, fallback):
        return getattr(obj, primary, getattr(obj, fallback, None))

    # 2. Retrieve inventory version numbers
    try:
        curr_version = _get_attr(self, "inventory_version", "version")
        prior_version = _get_attr(prior, "inventory_version", "version")
    except Exception as exc:
        raise ValueError(
            f"Unable to determine inventory version for validation: {exc}"
        ) from exc

    if curr_version is None or prior_version is None:
        raise ValueError("Inventory versions are missing for one or both inventories.")

    # Ensure versions are comparable
    try:
        if prior_version >= curr_version:
            raise ValueError(
                f"Prior inventory version ({prior_version}) must be older than current inventory version ({curr_version})."
            )
    except TypeError as exc:
        raise ValueError(
            f"Inventory versions are not comparable (prior: {prior_version}, current: {curr_version}): {exc}"
        ) from exc

    # 3. Retrieve item collections
    try:
        curr_items = _get_attr(self, "item_ids", "items")
        prior_items = _get_attr(prior, "item_ids", "items")
    except Exception:
        curr_items, prior_items = None, None

    if curr_items is None or prior_items is None:
        # If item collections are unavailable, skip subset validation but return True
        return True

    # Convert to sets for subset check; if not iterable, raise
    try:
        curr_set = set(curr_items)
        prior_set = set(prior_items)
    except Exception as exc:
        raise ValueError(
            f"Items in inventories are not iterable or cannot be converted to sets: {exc}"
        ) from exc

    if not prior_set.issubset(curr_set):
        missing = prior_set - curr_set
        raise ValueError(
            f"Current inventory is missing the following items that exist in the prior inventory: {missing}"
        )

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is not None
    if prior is None:
        raise ValueError("prior inventory is None")

    # Ensure prior is same type (or compatible subclass)
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"prior must be an instance of {type(self).__name__}, got {type(prior).__name__}"
        )

    # Retrieve the version attributes safely
    try:
        self_version = getattr(self, "version", None)
        prior_version = getattr(prior, "version", None)
    except Exception as exc:
        raise ValueError(f"Error accessing version attributes: {exc}") from exc

    if self_version is None or prior_version is None:
        raise ValueError("Both inventories must have a 'version' attribute")

    # Helper to compare versions (numeric or semantic string)
    def _compare_versions(v1, v2):
        # numeric comparison
        try:
            return (v1 > v2) - (v1 < v2)
        except Exception:
            pass
        # attempt to parse semantic versions like '1.2.3'
        try:
            def parse(v):
                return [
                    int(p) if p.isdigit() else p
                    for p in str(v).replace("-", ".").replace("_", ".").split(".")
                ]

            parsed1, parsed2 = parse(v1), parse(v2)
            return (parsed1 > parsed2) - (parsed1 < parsed2)
        except Exception:
            pass
        return 0

    comp = _compare_versions(self_version, prior_version)
    if comp <= 0:
        raise ValueError(
            f"self.version ({self_version}) must be greater than prior.version ({prior_version})"
        )

    # If additional consistency checks are needed, insert them here.

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input types
    if not isinstance(inventory, dict):
        raise TypeError("Expected inventory to be a dictionary.")
    if not isinstance(version, (str, int)):
        raise TypeError("Version must be a string or integer identifier.")

    # Attempt to retrieve the state dict for the given version
    try:
        state = inventory.get("states", {}).get(version, {})
        if not isinstance(state, dict):
            # If state is not a dict, we cannot process it
            raise ValueError(f"State for version '{version}' is not a dictionary.")
    except Exception as exc:
        raise ValueError(f"Failed to retrieve state for version '{version}': {exc}") from exc

    path_map = {}
    for logical_path, content_files in state.items():
        if not isinstance(logical_path, str):
            continue  # Skip if logical_path is not a string
        try:
            # Normalize content_files to a set of file paths
            if isinstance(content_files, (list, tuple, set)):
                files_set = set(map(str, content_files))
            else:
                # If single file reference
                files_set = {str(content_files)}
            path_map[logical_path] = files_set
        except Exception:
            # Skip entries that cannot be processed
            continue

    return path_map

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input types
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list of entries")
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    # Helper to process a single entry
    def _process_entry(entry, path_map):
        if not isinstance(entry, dict):
            return
        lp = entry.get("logical_path")
        cf = entry.get("content_file")
        if lp is None or cf is None:
            return
        path_map.setdefault(lp, set()).add(cf)

    # Case 1: inventory is a dict mapping version -> list of entries
    if isinstance(inventory, dict):
        # Ensure the requested version exists
        if version not in inventory:
            # try to find lexicographically close version
            available = list(inventory.keys())
            raise ValueError(f"Version '{version}' not found in inventory; available versions: {available}")

        # Find order of versions (sorted lexicographically)
        sorted_versions = sorted(inventory.keys())
        try:
            v_index = sorted_versions.index(version)
        except ValueError:
            raise ValueError(f"Version '{version}' not in sorted inventory keys")

        # Aggregate entries from the requested version onward
        path_map = {}
        for vs in sorted_versions[v_index:]:
            entries = inventory[vs]
            if isinstance(entries, list):
                for entry in entries:
                    _process_entry(entry, path_map)
            else:
                # Unexpected format
                continue
        return path_map

    # Case 2: inventory is a list of entries each with a version field
    if isinstance(inventory, list):
        # Separate entries by version
        version_entries = {}
        for entry in inventory:
            if not isinstance(entry, dict):
                continue
            v = entry.get("version")
            if v is None:
                continue
            version_entries.setdefault(v, []).append(entry)

        if version not in version_entries:
            available = list(version_entries.keys())
            raise ValueError(f"Version '{version}' not found in inventory; available versions: {available}")

        sorted_versions = sorted(version_entries.keys())
        try:
            v_index = sorted_versions.index(version)
        except ValueError:
            raise ValueError(f"Version '{version}' not in sorted inventory keys")

        path_map = {}
        for vs in sorted_versions[v_index:]:
            entries = version_entries[vs]
            for entry in entries:
                # Skip the version key for this path map
                _process_entry(entry, path_map)
        return path_map

    # Fallback: unsupported inventory format
    raise TypeError("Unsupported inventory format; expected dict or list of entries")

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or a list of dicts")
    if not isinstance(version, (int, str)):
        raise TypeError("version must be an int or a string")

    mapping = {}

    def _search(obj):
        """
        Recursively search through the inventory structure. If a dictionary
        contains a matching version and the expected keys, update the mapping.
        """
        if isinstance(obj, dict):
            # Check for a direct representation of the mapping for this version
            if (
                obj.get("version") == version
                and "logical_path" in obj
                and "content_files" in obj
            ):
                lp = obj["logical_path"]
                files = obj["content_files"]
                if files is None:
                    return
                if isinstance(files, (list, set)):
                    mapping.setdefault(lp, set()).update(files)
                else:
                    # If a single file (string or Path-like)
                    mapping.setdefault(lp, set()).add(files)

            # Recurse into sub-dictionaries and lists
            for value in obj.values():
                _search(value)

        elif isinstance(obj, list):
            for item in obj:
                _search(item)

    try:
        _search(inventory)
    except Exception as err:
        # Log the error if desired; re-raise for caller to handle
        raise RuntimeError(f"Unexpected error during inventory traversal: {err}") from err

    return mapping

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for a given version in the inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in later versions than the version being described.
    """
    # Validate inventory type
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")

    # Ensure the requested version exists
    if version not in inventory:
        raise KeyError(f"Version {version!r} not found in inventory")

    state = inventory[version]
    if not isinstance(state, dict):
        raise TypeError(f"State for version {version!r} must be a dict, got {type(state).__name__}")

    path_map = {}
    for logical_path, content_files in state.items():
        # logical_path should be a string
        if not isinstance(logical_path, str):
            raise TypeError(f"Logical path keys must be strings, got {type(logical_path).__name__}")

        # content_files should be an iterable (but not a string)
        if isinstance(content_files, str):
            raise TypeError(f"Content files for path {logical_path!r} must be an iterable, got string")
        try:
            file_set = set(content_files)
        except Exception as e:
            raise TypeError(f"Content files for path {logical_path!r} must be convertible to a set: {e}") from e

        path_map[logical_path] = file_set

    return path_map

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    - `fixity` should be a mapping where each key is a checksum algorithm
      (e.g. 'sha256', 'md5', etc.) and each value is a mapping of file
      names to checksum strings.
    - `manifest_files` is an iterable of file names reference in the
      inventory manifest.

    The method returns True if validation succeeds; otherwise it raises
    a ValueError describing the problem.
    """
    try:
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")

        # Normalize manifest files to a set for fast lookup
        if isinstance(manifest_files, (list, tuple, set)):
            try:
                manifest_set = set(str(f) for f in manifest_files)
            except Exception as e:
                raise ValueError("Manifest files must be iterable of strings") from e
        else:
            raise ValueError("Manifest files must be an iterable of file names")

        # Validate each algorithm entry
        for algo, files_map in fixity.items():
            if not isinstance(algo, str):
                raise ValueError(f"Algorithm key '{algo}' must be a string")
            if not isinstance(files_map, dict):
                raise ValueError(f"Value for algorithm '{algo}' must be a dictionary")
            # Validate each file entry
            for file_name, checksum in files_map.items():
                if not isinstance(file_name, str):
                    raise ValueError(f"File name '{file_name}' under algorithm '{algo}' must be a string")
                if not isinstance(checksum, str):
                    raise ValueError(f"Checksum for file '{file_name}' under algorithm '{algo}' must be a string")
                if file_name not in manifest_set:
                    raise ValueError(f"File '{file_name}' referenced in fixity block is not present in the manifest")

        return True
    except Exception as exc:
        # Re‑raise as a ValueError to keep API consistent
        raise ValueError(f"Fixity validation failed: {exc}") from exc

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be an iterable of file paths.")

    errors = []
