def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure inputs are of expected types
    if not isinstance(fixity, dict):
        raise ValueError(f"Fixity must be a dictionary, got {type(fixity).__name__}")

    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError(f"manifest_files must be a list, set, or tuple, got {type(manifest_files).__name__}")

    manifest_set = set(manifest_files)

    for file_path, info in fixity.items():
        # Validate file path type
        if not isinstance(file_path, str):
            raise ValueError(f"Fixity file key must be a string, got {type(file_path).__name__} for entry {file_path!r}")

        # Validate that the file is listed in the manifest
        if file_path not in manifest_set:
            raise ValueError(f"Fixity references '{file_path}' which is not present in the manifest")

        # Validate info is a dict
        if not isinstance(info, dict):
            raise ValueError(f"Fixity info for '{file_path}' must be a dict, got {type(info).__name__}")

        # Check required keys
        required_keys = {"method", "checksum"}
        missing = required_keys - info.keys()
        if missing:
            raise ValueError(f"Fixity info for '{file_path}' missing required keys: {', '.join(sorted(missing))}")

        # Validate method
        method = info["method"]
        if not isinstance(method, str):
            raise ValueError(f"Method for '{file_path}' must be a string, got {type(method).__name__}")

        # Validate checksum
        checksum = info["checksum"]
        if not isinstance(checksum, str):
            raise ValueError(f"Checksum for '{file_path}' must be a string, got {type(checksum).__name__}")

        # Optional length validation
        if "length" in info:
            length = info["length"]
            if not isinstance(length, (int, float)):
                raise ValueError(f"'length' for '{file_path}' must be numeric, got {type(length).__name__}")

    # Ensure no extra files in manifest lacking fixity entries is not an error
    return True  # Explicitly indicate success (caller may ignore)

