def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Path to the source folder or zipfile (not used for grouping but validated).
    xmls : list of str
        List of XML filenames present in the source.
    files : list of str
        List of all files (paths or names) present in the source.

    Returns
    -------
    dict
        key: full XML filename as provided in `xmls`
        value: list of files that share the same basename as the XML file.
    """
    # Basic input validation
    if not isinstance(source, str):
        raise TypeError("`source` must be a string path")
    if not isinstance(xmls, list):
        raise TypeError("`xmls` must be a list")
    if not isinstance(files, list):
        raise TypeError("`files` must be a list")

    # Helper functions to avoid importing os
    def _basename(path):
        # Handles both '/' and '\\' separators
        if '/' in path:
            part = path.rsplit('/', 1)[-1]
        else:
            part = path
        if '\\' in part:
            part = part.rsplit('\\', 1)[-1]
        return part

    def _strip_extension(name):
        if '.' in name:
            return name.rsplit('.', 1)[0]
        return name

    # Build mapping from basename to full XML filename
    xml_map = {}
    for xml in xmls:
        if not isinstance(xml, str):
            raise ValueError("All items in `xmls` must be strings")
        base = _strip_extension(_basename(xml))
        xml_map[base] = xml

    # Group files
    result = {}
    for file_path in files:
        if not isinstance(file_path, str):
            raise ValueError("All items in `files` must be strings")
        base = _strip_extension(_basename(file_path))
        if base in xml_map:
            xml_key = xml_map[base]
            result.setdefault(xml_key, []).append(file_path)

    # Ensure that all XML files appear as a key, even if they have no matching files
    for xml_key in xml_map.values():
        result.setdefault(xml_key, [])

    return result

