def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping of XML file path (relative to the archive root) to a
        dictionary mapping each file name in the same directory to its
        contents as bytes.
    """
    import os
    from zipfile import ZipFile, BadZipFile

    if not zip_path or not isinstance(zip_path, str):
        return {}

    packages = {}
    xml_dirs = {}

    try:
        with ZipFile(zip_path, 'r') as zf:
            # First pass: Identify XML files and their directories
            for name in zf.namelist():
                if name.endswith('/') or not name.lower().endswith('.xml'):
                    continue
                dirpath = os.path.dirname(name)
                xml_dirs[dirpath] = name

            # Second pass: Collect files belonging to each XML directory
            for name in zf.namelist():
                if name.endswith('/'):
                    continue  # skip directories
                dirpath = os.path.dirname(name)
                if dirpath in xml_dirs:
                    pkg_key = xml_dirs[dirpath]
                    if pkg_key not in packages:
                        packages[pkg_key] = {}
                    # Store file content; use the file name relative to the package dir
                    rel_name = os.path.basename(name)
                    try:
                        data = zf.read(name)
                    except Exception:
                        # If file can't be read, skip it
                        continue
                    packages[pkg_key][rel_name] = data
    except FileNotFoundError:
        # If the zip file does not exist, return empty dictionary
        return {}
    except BadZipFile:
        raise ValueError(f"The file at {zip_path} is not a valid ZIP archive.")
    except Exception as exc:
        raise RuntimeError(f"An unexpected error occurred while exploring {zip_path}: {exc}")

    return packages

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Dictionary where keys are the base names of XML files (without extension) and
        values are dictionaries mapping the full path of each file in the package to
        its decoded textual content (if XML) or raw bytes (for other file types).
    """
    import os
    import zipfile

    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            packages = {}
            for info in zf.infolist():
                if info.is_dir():
                    continue
                full_path = info.filename
                # ignore path separators for base name extraction
                base_name = os.path.splitext(os.path.basename(full_path))[0]
                try:
