                except RuntimeError:
                    # If the file cannot be read, skip it
                    continue

                ext = os.path.splitext(full_path)[1].lower()
                if ext == ".xml":
                    try:
                        content = raw.decode("utf-8")
                    except Exception:
                        # fall back to None if decoding fails
                        content = None
                else:
                    content = raw

                if base_name not in packages:
                    packages[base_name] = {}
                packages[base_name][full_path] = content

            return packages
    except FileNotFoundError:
        raise FileNotFoundError(f"Zip file not found: {zip_path}")
    except zipfile.BadZipFile as exc:
        raise ValueError(f"Invalid or corrupt zip file: {zip_path}") from exc

