def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.

    Parameters
    ----------
    node : object
        Objeto de nó XML que deve suportar o método xpath.
    pubdate_xpaths : iterable of str
        Lista de expressões XPath para buscar data de publicação.

    Returns
    -------
    str or None
        O conteúdo textual encontrado na primeira expressão XPath
        compatível, ou None caso nenhuma expressão produza resultado.
    """
    # Verificar tipos básicos
    if node is None:
        return None
    try:
        iterable = iter(pubdate_xpaths)
    except TypeError:
        # Não é iterável
        return None

    for xpath_expr in iterable:
        if not isinstance(xpath_expr, str):
            # Ignorar expressões inválidas
            continue
        try:
            # Tentar executar XPath; pode lançar exceção em caso de erro de sintaxe.
            result = node.xpath(xpath_expr)
            # Result could be list, bool, number or string depending on XPath.
            # Normalmente esperamos lista de nós ou string.
            if isinstance(result, list) and result:
                first = result[0]
                # Se for string ou número, converter para string e retornar.
                if isinstance(first, (str, bytes)):
                    return str(first).strip()
                # Se for elemento XML, try to get text content.
                try:
                    text = first.text
                    if text is not None:
                        return text.strip()
                except Exception:
                    pass
                # Se não houver texto, retornar representação string do nó.
                return str(first).strip()
            # Se o resultado não é lista ou está vazio, pode ser bool, number, string
            if isinstance(result, (str, bytes)):
                return str(result).strip()
            if isinstance(result, (int, float)):
                return str(result).strip()
        except Exception:
            # Ignorar exceções de expressão XPath inválida e continuar.
            continue
    # Se nenhuma expressão deu resultado, retornar None
    return None

