def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re
    if not isinstance(issue, str):
        raise ValueError("issue must be a string")
    text = issue.strip().lower()
    number = None
    suppl = None

    # Extract the first integer as the main number
    m_num = re.search(r'(\d+)', text)
    if m_num:
        try:
            number = int(m_num.group(1))
        except ValueError:
            number = None

    # Patterns that indicate a supplement
    sup_keywords = ['suppl', 'supp', 'suppr', 'pr', 'spe', 's']
    # Search for any of the keywords
    keyword_pos = None
    for kw in sup_keywords:
        pos = text.find(kw)
        if pos != -1:
            keyword_pos = pos
            kw_len = len(kw)
            break

    if keyword_pos is not None:
        # Grab substring after the keyword
        sub_text = text[keyword_pos + kw_len:].strip()
        # Look for an integer in the remaining text
        m_suppl = re.search(r'(\d+)', sub_text)
        if m_suppl:
            try:
                suppl = int(m_suppl.group(1))
            except ValueError:
                suppl = None
        else:
            # If no number follows the keyword, check if keyword itself is numeric (e.g., 's2')
            m_kw_num = re.search(r'(\d+)', kw)
            if m_kw_num:
                try:
                    suppl = int(m_kw_num.group(1))
                except ValueError:
                    suppl = None
    else:
        # Check for patterns like 's2' or similar at the start
        m_start = re.match(r'^s(\d+)', text)
        if m_start:
            try:
                suppl = int(m_start.group(1))
            except ValueError:
                suppl = None

    return number, suppl

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    spaces = " " * indent
    try:
        # If the object provides its own pretty method, use it
        if hasattr(self, "pretty") and callable(self.pretty):
            # Avoid infinite recursion: only use pretty if we are not the top-level call
            if indent > 0:
                return self.pretty(indent, debug)
            else:
                return self.pretty(indent, debug)

        # Try to format using attributes if possible
        if hasattr(self, "__dict__"):
            items = []
            for key, val in self.__dict__.items():
                # Indent nested pretty objects
                if hasattr(val, "pretty") and callable(val.pretty):
                    val_str = val.pretty(indent + 2, debug)
                elif isinstance(val, (list, tuple)):
                    val_items = []
                    for item in val:
                        if hasattr(item, "pretty") and callable(item.pretty):
                            val_items.append(item.pretty(indent + 2, debug))
                        else:
                            val_items.append(repr(item))
                    val_str = "[" + ", ".join(val_items) + "]"
                else:
                    val_str = repr(val) if debug else str(val)
                items.append(f"{key}={val_str}")
            body = ", ".join(items)
            return f"{self.__class__.__name__}({body})"

        # Fallback to repr
        return repr(self)
    except Exception:
        # If representation fails, fall back to str
        return str(self)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    visited = set()

    def _pretty(obj, level):
        # Avoid infinite recursion
        obj_id = id(obj)
        if obj_id in visited:
            return ' ' * level + '<recursion>'
        # Primitive types are represented directly
        if isinstance(obj, (int, float, bool, str, type(None))):
            return ' ' * level + repr(obj)

        visited.add(obj_id)

        # Containers
        if isinstance(obj, (list, tuple, set)):
            open_br, close_br = ('[', ']') if isinstance(obj, list) else ('(', ')') if isinstance(obj, tuple) else ('{', '}')
            items = []
            for item in obj:
                items.append(_pretty(item, level + 4))
            return f'{open_br}\n' + ',\n'.join(items) + f'\n{" " * level}{close_br}'

        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                key_str = _pretty(k, level + 4).strip()
                val_str = _pretty(v, level + 4).strip()
                items.append(f"{' ' * (level + 4)}{key_str}: {val_str}")
            return f'{{\n' + ',\n'.join(items) + f'\n{" " * level}}}'

        # Other objects
        try:
            # Prefer vars() for objects that expose attributes
            attrs = vars(obj)
        except Exception:
            # Fall back to __dict__ if vars() fails
            attrs = obj.__dict__ if hasattr(obj, '__dict__') else {}

        lines = []
        for key, value in attrs.items():
            val_str = _pretty(value, level + 4).strip()
            lines.append(f"{' ' * (level + 4)}{key} = {val_str}")

        body = ',\n'.join(lines)
        result = f"{' ' * level}{obj.__class__.__name__}(\n{body}\n{' ' * level})"

        if debug and level == 0:
            # Include debug info only at the top level
            result = f"{' ' * level}# {obj.__class__.__name__} @{hex(obj_id)}\n{result}"

        return result

    try:
        return _pretty(self, indent)
    except Exception as e:
        return f"<error producing pretty output: {e}>"

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Ensure indent is a non-negative integer
    try:
        indent = int(indent)
    except Exception:
        indent = 0
    if indent < 0:
        indent = 0

    seen = set()

    def _pretty(obj, level):
        ind = '    ' * level
        obj_id = id(obj)
        if obj_id in seen:
            return '...'
        seen.add(obj_id)

        # Primitive types
        if isinstance(obj, (str, bytes)):
            s = repr(obj)
        elif obj is None or isinstance(obj, (int, float, bool)):
            s = repr(obj)
        # Containers
        elif isinstance(obj, dict):
            if not obj:
                return '{}'
            lines = ['{']
            for k, v in obj.items():
                lines.append(f"{ind}    {_pretty(k, level+1)}: {_pretty(v, level+1)},")
            lines.append(f"{ind}}}")
            s = '\n'.join(lines)
        elif isinstance(obj, (list, tuple, set, frozenset)):
            type_name = type(obj).__name__
            if isinstance(obj, set):
                type_name = 'set'
            if not obj:
                return f'{type_name}()'
            lines = [f'{type_name}(']
            for item in obj:
                lines.append(f"{ind}    {_pretty(item, level+1)},")
            lines.append(f"{ind})")
            s = '\n'.join(lines)
        # Custom objects
        else:
            attrs = None
            try:
                attrs = obj.__dict__
            except Exception:
                pass
            if attrs is None and hasattr(obj, "__slots__"):
                try:
                    attrs = {slot: getattr(obj, slot) for slot in obj.__slots__ if hasattr(obj, slot)}
                except Exception:
                    attrs = None
            if attrs:
                type_name = obj.__class__.__name__
                lines = [f'{type_name}(']
                for k, v in attrs.items():
                    lines.append(f"{ind}    {k}={_pretty(v, level+1)},")
                lines.append(f"{ind})")
                s = '\n'.join(lines)
            else:
                s = repr(obj)

        # Append debug information if requested (only for primitives and non-collections)
        if debug and not isinstance(obj, (dict, list, tuple, set, frozenset)):
            s += f' ; type={type(obj).__name__}'
        return s

    return _pretty(self, indent)

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        visited = set()

        def _format(obj, level):
            if id(obj) in visited:
                return "[Circular]"
            visited.add(id(obj))

            current_indent = " " * (indent + level * 2)

            # Handle basic types
            if isinstance(obj, (str, int, float, bool, type(None))):
                return repr(obj)

            # Handle dictionaries
            if isinstance(obj, dict):
                items = []
                for k, v in obj.items():
                    formatted_key = repr(k)
                    formatted_val = _format(v, level + 1)
                    items.append(f"{current_indent}{formatted_key}: {formatted_val}")
                return "{\n" + ",\n".join(items) + f"\n{current_indent}}}"

            # Handle lists, tuples, sets
            if isinstance(obj, (list, tuple, set)):
                open_sym, close_sym = ("[", "]") if isinstance(obj, list) else ("(", ")") if isinstance(obj, tuple) else ("{", "}")
                items = []
                for item in obj:
                    items.append(_format(item, level + 1))
                indented_items = ",\n".join(f"{current_indent}  {item}" for item in items)
                return f"{open_sym}\n{indented_items}\n{current_indent}{close_sym}"

            # Handle objects with __dict__
            if hasattr(obj, "__dict__"):
                attrs = _format(obj.__dict__, level + 1)
                return f"{obj.__class__.__name__}({attrs})"

            # Fallback to repr
            return repr(obj)

        try:
            return _format(self, 0)
        except Exception as exc:
            return f"<pretty error: {exc}>"

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        # Validate indent
        if not isinstance(indent, int) or indent < 0:
            raise ValueError("indent must be a non-negative integer")

        # Helper to recursively format objects
        def _format_obj(obj, cur_indent, visited):
            if id(obj) in visited:
                return "<Circular Reference>"
            visited.add(id(obj))

            if hasattr(obj, "pretty") and callable(getattr(obj, "pretty")) and obj is not self:
                try:
                    return obj.pretty(cur_indent, debug=debug)
                except Exception:
                    pass  # fall back to repr if custom pretty fails

            if isinstance(obj, (list, tuple, set)):
                opening = "[" if isinstance(obj, list) else "(" if isinstance(obj, tuple) else "{"
                closing = "]" if isinstance(obj, list) else ")" if isinstance(obj, tuple) else "}"
                items = []
                for item in obj:
                    items.append(_format_obj(item, cur_indent + 2, visited))
                joined = ",\n".join(" " * (cur_indent + 2) + item for item in items)
                return f"{opening}\n{joined}\n{' ' * cur_indent}{closing}"
            elif isinstance(obj, dict):
                items = []
                for k, v in obj.items():
                    formatted_k = _format_obj(k, cur_indent + 2, visited)
                    formatted_v = _format_obj(v, cur_indent + 2, visited)
                    items.append(f"{formatted_k}: {formatted_v}")
                joined = ",\n".join(" " * (cur_indent + 2) + item for item in items)
                return f"{{\n{joined}\n{' ' * cur_indent}}}"
            else:
                return repr(obj)

        try:
            if debug:
                print(f"[DEBUG] pretty called on {self.__class__.__name__} with indent={indent}")

            visited_objs = set()
            representation = _format_obj(self, indent, visited_objs)

            # Format the outermost representation with proper indentation
            lines = representation.splitlines()
            if len(lines) == 1:
                return representation
            else:
                indented = "\n".join((" " * indent) + line if line else "" for line in lines)
                return indented
        except Exception as exc:
            return f"<Error during pretty(): {exc!r}>"

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper to inspect expression type
    def _op(expr):
        return getattr(expr, "op", None)

    def _args(expr):
        if hasattr(expr, "args"):
            return expr.args
        if hasattr(expr, "left") and hasattr(expr, "right"):
            return (expr.left, expr.right)
        return ()

    # Logical simplification according to the rules
    def _simplify_absorption(a, b):
        try:
            # A & (A | B)
            if _op(a) == "and":
                a_left, a_right = _args(a)
                if _op(b) == "or" and (a_left == _args(b)[0] or a_left == _args(b)[1]):
                    # Return the common part
                    return a_left if a_left == _args(b)[0] else _args(b)[1]
            # A | (A & B)
            if _op(a) == "or":
                a_left, a_right = _args(a)
                if _op(b) == "and" and (a_left == _args(b)[0] or a_left == _args(b)[1]):
                    return a_left if a_left == _args(b)[0] else _args(b)[1]
            # Negative absorption: A & (~A | B) = A & B
            if _op(a) == "and":
                a_left, a_right = _args(a)
                if _op(b) == "or":
                    b_left, b_right = _args(b)
                    if _op(b_left) == "not" and _args(b_left)[0] == a_left:
                        return a_left & b_right
                    if _op(b_right) == "not" and _args(b_right)[0] == a_left:
                        return a_left & b_left
            # Negative absorption: A | (~A & B) = A | B
            if _op(a) == "or":
                a_left, a_right = _args(a)
                if _op(b) == "and":
                    b_left, b_right = _args(b)
                    if _op(b_left) == "not" and _args(b_left)[0] == a_left:
                        return a_left | b_right
                    if _op(b_right) == "not" and _args(b_right)[0] == a_left:
                        return a_left | b_left
        except Exception:
            # In case of unexpected structure, ignore
            pass
        return None

    try:
        new_args = list(args)
        # Duplicate removal to keep list small
        seen = set()
        unique = []
        for expr in new_args:
            try:
                key = str(expr)
            except Exception:
                key = id(expr)
            if key not in seen:
                seen.add(key)
                unique.append(expr)
        new_args = unique

        # Apply absorption simplification iteratively
        changed = True
        while changed:
            changed = False
            for i in range(len(new_args)):
                a = new_args[i]
                for j in range(len(new_args)):
                    if i == j:
                        continue
                    b = new_args[j]
                    simplified = _simplify_absorption(a, b)
                    if simplified is not None:
                        new_args[i] = simplified
                        changed = True
                        break
                if changed:
                    break

        # Final duplicate removal after simplification
        seen = set()
        final = []
        for expr in new_args:
            try:
                key = str(expr)
            except Exception:
                key = id(expr)
            if key not in seen:
                seen.add(key)
                final.append(expr)
        return final
    except Exception as exc:
        # Re-raise as RuntimeError to indicate processing issue
        raise RuntimeError(f"Failed to absorb expressions: {exc}") from exc

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    The function assumes expressions are represented as nested tuples:
    - ('&', left, right) for conjunction
    - ('|', left, right) for disjunction
    - ('~', operand) for negation

    The resulting list contains the simplified arguments.
    """
    # Helper functions for expression handling
    def is_op(expr, op):
        return isinstance(expr, tuple) and len(expr) == 3 and expr[0] == op

    def is_not(expr):
        return isinstance(expr, tuple) and len(expr) == 2 and expr[0] == '~'

    def get_inner(expr):
        return expr[1]

    def contains(sub, expr):
        if sub == expr:
            return True
        if isinstance(expr, tuple):
            return any(contains(sub, e) for e in expr[1:])
        return False

    def get_other_operand(container, target):
        """Return the other operand if container is '&' or '|' and contains target."""
        if not isinstance(container, tuple) or len(container) != 3:
            return None
        op, a, b = container
        if a == target:
            return b
        if b == target:
            return a
        return None

    def process_pair(e1, e2):
        """Detect absorption patterns between e1 and e2 and return simplified expr if any."""
        # Positive absorption: A & (A | B) = A, A | (A & B) = A
        if is_op(e2, '|') and contains(e1, e2):
            return e1
        if is_op(e1, '|') and contains(e2, e1):
            return e2
        if is_op(e2, '&') and contains(e1, e2):
            return e1
        if is_op(e1, '&') and contains(e2, e1):
            return e2

        # Negative absorption: A & (~A | B) = A & B, A | (~A & B) = A | B
        # Pattern A & ( ~A | B )
        if is_op(e2, '|'):
            if is_not(e1) and contains(e1, e2):
                # e1 is ~A, find other
                B = get_other_operand(e2, e1)
                if B is not None:
                    return ('&', get_inner(e1), B)
            # e2 is Or, check if it contains Not(e1)
            if any(is_not(arg) and contains(get_inner(arg), e1) for arg in e2[1:]):
                for arg in e2[1:]:
                    if is_not(arg) and contains(get_inner(arg), e1):
                        B = get_other_operand(e2, arg)
                        if B is not None:
                            return ('&', e1, B)

        # Pattern A | ( ~A & B )
        if is_op(e2, '&'):
            if is_not(e1) and contains(e1, e2):
                B = get_other_operand(e2, e1)
                if B is not None:
                    return ('|', get_inner(e1), B)
            if any(is_not(arg) and contains(get_inner(arg), e1) for arg in e2[1:]):
                for arg in e2[1:]:
                    if is_not(arg) and contains(get_inner(arg), e1):
                        B = get_other_operand(e2, arg)
                        if B is not None:
                            return ('|', e1, B)

        # Symmetric cases where e1 is the complex expression
        # Pattern (~A | B) with A
        if is_op(e1, '|'):
            if is_not(e2) and contains(e2, e1):
                B = get_other_operand(e1, e2)
                if B is not None:
                    return ('&', get_inner(e2), B)
            if any(is_not(arg) and contains(get_inner(arg), e2) for arg in e1[1:]):
                for arg in e1[1:]:
                    if is_not(arg) and contains(get_inner(arg), e2):
                        B = get_other_operand(e1, arg)
                        if B is not None:
                            return ('&', e2, B)

        if is_op(e1, '&'):
            if is_not(e2) and contains(e2, e1):
                B = get_other_operand(e1, e2)
                if B is not None:
                    return ('|', get_inner(e2), B)
            if any(is_not(arg) and contains(get_inner(arg), e2) for arg in e1[1:]):
                for arg in e1[1:]:
                    if is_not(arg) and contains(get_inner(arg), e2):
                        B = get_other_operand(e1, arg)
                        if B is not None:
                            return ('|', e2, B)

        # No pattern matched
        return None

    n = len(args)
    used = [False] * n
    result = []

    for i in range(n):
        if used[i]:
            continue
        matched = False
        for j in range(i + 1, n):
            if used[j]:
                continue
            simplified = process_pair(args[i], args[j])
            if simplified is not None:
                used[i] = used[j] = True
                result.append(simplified)
                matched = True
                break
        if not matched and not used[i]:
            result.append(args[i])

    return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    if hook is None:
        raise ValueError("Hook cannot be None")

    # Ensure the registry exists on the instance
    if not hasattr(self, "registry"):
        self.registry = {}

    def decorator(func):
        if not callable(func):
            raise TypeError("Registered handler must be a callable")

        # Register the function under the specified hook
        try:
            self.registry.setdefault(hook, []).append(func)
        except Exception as e:
            raise RuntimeError(f"Failed to register handler for hook {hook!r}") from e
        return func

    return decorator

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

