        # split a string command into parts safely
        base_cmd = shlex.split(str(commands))

    # Normalize args to a list
    if args is None:
        args = []
    elif isinstance(args, (list, tuple)):
        args = list(args)
    else:
        args = [str(args)]

    # Build the full command
    full_cmd = base_cmd + args

    # Verbose output
    if verbose:
        print("Running command:", " ".join(shlex.quote(c) for c in full_cmd))

    # Prepare subprocess parameters
    kwargs = {
        "cwd": cwd,
        "env": env,
        "capture_output": True,
        "text": True,
    }

    # Handle stderr redirection
