            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False
        )
    except FileNotFoundError as fnf_error:
        raise RuntimeError(f"Command not found: {commands}") from fnf_error
    except OSError as os_error:
        raise RuntimeError(f"Failed to execute command {commands}: {os_error}") from os_error
    except subprocess.SubprocessError as sub_error:
        raise RuntimeError(f"Error running command {commands}: {sub_error}") from sub_error

    if verbose:
        print(f"Return code: {result.returncode}")
        if result.stdout:
            print("Stdout:")
            print(result.stdout)
        if not hide_stderr and result.stderr:
            print("Stderr:")
            print(result.stderr)

    if result.returncode != 0:
        # Include stdout and stderr in the exception message for debugging
        msg = (
            f"Command {commands} failed with exit code {result.returncode}\n"
            f"Stdout:\n{result.stdout}\n"
            f"Stderr:\n{result.stderr}"
        )
        raise RuntimeError(msg)

    return result

