def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib
    import warnings

    # Determine root path
    root_path = getattr(self, 'root_path', None) or getattr(self, 'storage_root', None)
    if not root_path or not isinstance(root_path, str):
        if show_warnings:
            warnings.warn("Root path not defined or invalid; validation aborted.")
        return 0, 0

    # Ensure the root exists
    if not os.path.exists(root_path):
        if show_warnings:
            warnings.warn(f"Root path '{root_path}' does not exist; validation aborted.")
        return 0, 0

    num_objects = 0
    good_objects = 0

    for current_root, dirs, files in os.walk(root_path, topdown=True, onerror=None, followlinks=False):
        # Validate directories
        for dname in dirs:
            dir_path = os.path.join(current_root, dname)
            num_objects += 1
            is_valid = True
            if validate_objects:
                if not os.path.isdir(dir_path):
                    is_valid = False
                else:
                    # Check read/write permissions if needed
                    if not os.access(dir_path, os.R_OK | os.W_OK):
                        is_valid = False
            if is_valid:
                good_objects += 1
            else:
                if show_warnings:
                    warnings.warn(f"Invalid directory detected: {dir_path}")

        # Validate files
        for fname in files:
            file_path = os.path.join(current_root, fname)
            num_objects += 1
            is_valid = True
            if validate_objects:
                if not os.path.isfile(file_path):
                    is_valid = False
                else:
                    if not os.access(file_path, os.R_OK):
                        is_valid = False
            if is_valid and check_digests:
                try:
                    # Compute SHA-256 digest
                    sha256 = hashlib.sha256()
                    with open(file_path, 'rb') as f:
                        for chunk in iter(lambda: f.read(8192), b''):
                            sha256.update(chunk)
                    # Typically you'd compare with an expected digest; here we simply ensure digest can be computed
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        warnings.warn(f"Could not compute digest for {file_path}: {e}")

            if is_valid:
                good_objects += 1
            else:
                if show_warnings:
                    warnings.warn(f"Invalid file detected: {file_path}")

    return num_objects, good_objects

