def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        raise ValueError("Input must be a non-empty string.")
    if not version.isdigit():
        raise ValueError("Input must contain only digits.")
    # Count leading zeros to preserve format
    leading_zero_count = len(version) - len(version.lstrip('0'))
    try:
        numeric_value = int(version)
    except Exception as e:
        raise ValueError("Invalid numeric value.") from e
    next_value = numeric_value + 1
    next_str = str(next_value)
    # Pad with zeros to match original length if applicable
    if leading_zero_count > 0 and len(next_str) < len(version):
        next_str = next_str.rjust(len(version), '0')
    return next_str

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("Version must be a string")
    if not version:
        raise ValueError("Version string cannot be empty")
    if not version.isdigit():
        raise ValueError("Version string must contain only digits")

    # Convert to integer to compute next version
    try:
        current = int(version)
    except ValueError as exc:
        raise ValueError("Invalid numeric value") from exc

    next_val = current + 1
    # Preserve leading zeros if original had them and length > 1
    if len(version) > 1 and version[0] == '0':
        return str(next_val).zfill(len(version))
    return str(next_val)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    stripped = version.strip()
    if not stripped:
        raise ValueError("empty version string")
    parts = stripped.split('.')
    if any(part == '' for part in parts):
        raise ValueError("empty component in version")
    if not all(part.isdigit() for part in parts):
        raise ValueError("non-numeric components in version")

    last = parts[-1]
    orig_len = len(last)
    try:
        next_val = int(last) + 1
    except Exception as exc:
        raise ValueError("invalid numeric value") from exc

    # Determine new string for the last component
    next_str = str(next_val)
    if len(next_str) > orig_len:
        new_last = next_str  # overflow, drop leading zeros
    else:
        # Preserve zero-prefixed width if appropriate
        if orig_len > 1 or (orig_len == 1 and last.startswith('0')):
            new_last = next_str.zfill(orig_len)
        else:
            new_last = next_str
    parts[-1] = new_last
    return '.'.join(parts)

def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        s = str(version).strip()
        if not s.isdigit():
            raise ValueError("Version must be a numeric string")
        num = int(s)
        nxt = num + 1
        if s.startswith('0') and len(s) > 1:  # preserve leading zeros
            width = len(s)
            return str(nxt).zfill(width)
        else:
            return str(nxt)
    except Exception as e:
        raise ValueError(f"Invalid input for next_version: {e}") from e

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root
    inventory so that we can also check them when validating the content.

    `version_dirs` is an array of version directory names and is assumed to
    be in version sequence (1, 2, 3...).

    The inventory file is expected to be named ``inventory`` inside each
    directory and contain lines formatted as ``path|digest``.  The root
    inventory must already be present in ``self.root_inventory`` as a dict
    mapping paths to their expected digests.  Any path missing from a
    version inventory or any digest that differs from the root inventory
    is recorded in ``self.differing_digests``.  Raises ``ValueError`` when
    a specified inventory file cannot be found or when a path is missing
    from the root inventory.
    """
    if not hasattr(self, "root_inventory"):
        raise ValueError("Root inventory not available in instance")

    # Ensure differing digests dict exists
    if not hasattr(self, "differing_digests"):
        self.differing_digests = {}

    root_inv = self.root_inventory

    for vdir in version_dirs:
        inv_path = f"{vdir}/inventory"
        try:
            with open(inv_path, "r", encoding="utf-8") as fp:
                lines = fp.readlines()
        except FileNotFoundError:
            raise ValueError(f"Inventory file missing for version directory: {vdir}")

        inv_map = {}
        for lineno, line in enumerate(lines, start=1):
            line = line.strip()
            if not line:
                continue
            if "|" not in line:
                # Malformed line; skip but note it
                continue
            parts = line.split("|", 1)
            if len(parts) != 2:
                continue
            path, digest = parts[0].strip(), parts[1].strip()
            inv_map[path] = digest

        # Validate each inventory entry against the root inventory
        for path, cur_digest in inv_map.items():
            if path not in root_inv:
                raise ValueError(f"Path '{path}' in inventory {vdir} not found in root inventory")

            root_digest = root_inv[path]
            if cur_digest != root_digest:
                if path not in self.differing_digests:
                    self.differing_digests[path] = {}
                # Store the differing digest per version directory
                self.differing_digests[path][vdir] = cur_digest

        # Optionally, detect missing entries in the version inventory
        for root_path in root_inv:
            if root_path not in inv_map:
                raise ValueError(f"Missing path '{root_path}' in inventory file {inv_path}")
    return True

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a valid list/tuple of directory names
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    import os
    # Gather possible inventory file names
    inventory_filenames = ["inventory.yml", "inventory.yaml", "inventory.json"]

    # Find root inventory file
    root_inv_path = None
    for name in inventory_filenames:
        potential = os.path.join(self.root, name)
        if os.path.isfile(potential):
            root_inv_path = potential
            break
    if root_inv_path is None:
        raise FileNotFoundError("Root inventory file not found in the root directory")

    # Load root inventory
    try:
        with open(root_inv_path, "r", encoding="utf-8") as fh:
            if root_inv_path.endswith(".json"):
                import json
                root_inventory = json.load(fh)
            else:
                import yaml
                root_inventory = yaml.safe_load(fh)
    except Exception as e:
        raise RuntimeError(f"Failed to load root inventory: {e}")

    if not isinstance(root_inventory, dict):
        raise ValueError("Root inventory must be a mapping (dict)")

    # Prepare container for differing digests
    self._different_digests = {}

    # Iterate over each version directory in order
    for idx, version_dir in enumerate(version_dirs, start=1):
        if not isinstance(version_dir, str):
            raise TypeError(f"Version directory name at index {idx-1} must be a string")
        dir_path = os.path.join(self.root, version_dir)
        if not os.path.isdir(dir_path):
            raise FileNotFoundError(f"Version directory '{version_dir}' does not exist")

        # Locate inventory file inside the version directory
        inv_path = None
        for name in inventory_filenames:
            potential = os.path.join(dir_path, name)
            if os.path.isfile(potential):
                inv_path = potential
                break
        if inv_path is None:
            raise FileNotFoundError(f"No inventory file found in version directory '{version_dir}'")

        # Load inventory for this version
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                if inv_path.endswith(".json"):
                    inv_data = json.load(fh)
                else:
                    inv_data = yaml.safe_load(fh)
        except Exception as e:
            raise RuntimeError(f"Failed to load inventory in '{inv_path}': {e}")

        if not isinstance(inv_data, dict):
            raise ValueError(f"Inventory in '{inv_path}' must be a mapping (dict)")

        # Compare digests to root inventory and record differences
        for content_id, digest in inv_data.items():
            root_digest = root_inventory.get(content_id)
            if root_digest is None or root_digest != digest:
                self._different_digests[content_id] = (root_digest, digest)

    # Store a flag indicating inventories were validated
    self._inventories_validated = True

    # Method returns None; state is reflected in instance attributes
    return

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   – the directory looks like an OCFL Storage Root
        'object' – the directory looks like an OCFL Object
        'file'   – the path points to a file (could be an inventory)
        other string – an error description if the type cannot be determined
    """
    from pathlib import Path

    try:
        p = Path(path)
    except Exception as exc:
        return f"Error: invalid path value: {exc!s}"

    if not p.exists():
        return f"Error: path does not exist: {path}"

    if p.is_file():
        return "file"

    if p.is_dir():
        # look for a "0=*" Namaste file directly in the directory
        try:
            entries = list(p.iterdir())
        except PermissionError as exc:
            return f"Error: permission denied while examining {path}: {exc}"
        except OSError as exc:
            return f"Error: cannot read directory {path}: {exc}"

        namaste_files = [e for e in entries if e.is_file() and e.name.startswith("0=")]
        if namaste_files:
            # A Namaste file directly inside suggests a storage root
            return "root"

        # If not found at the top level, check the first-level subdirectories
        for sub in entries:
            if sub.is_dir():
                try:
                    sub_entries = list(sub.iterdir())
                except PermissionError:
                    continue
                except OSError:
                    continue
                sub_namaste = [e for e in sub_entries if e.is_file() and e.name.startswith("0=")]
                if sub_namaste:
                    return "object"

        return f"Error: directory {path} does not contain any '0=*' Namaste files"
    # Fallback for other Path kinds (e.g., symlink to non-file/non-dir, etc.)
    return f"Error: path is neither a regular file nor a directory: {path}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return f"path does not exist: {path}"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            # Look for a Namaste file whose name starts with "0="
            namaste_file = None
            for entry in os.listdir(path):
                if entry.startswith("0="):
                    namaste_file = os.path.join(path, entry)
                    break

            if not namaste_file:
                return "no Namaste file present; not an OCFL structure"

            # Try to read the Namaste file
            try:
                with open(namaste_file, "r", encoding="utf-8") as f:
                    content = f.read().lower()
            except Exception as e:
                return f"error reading Namaste file: {e}"

            # Determine type from content if possible
            if "ocfl-root" in content or "root" in content:
                return "root"

            if "ocfl-object" in content or "object" in content:
                return "object"

            # Fallback: if the directory contains an 'objects' subdirectory, it's a root
            if os.path.isdir(os.path.join(path, "objects")):
                return "root"

            # If the directory contains a 'metadata' or a 'versions' subdirectory, treat as object
            for sub in ("metadata", "versions", "obj"):
                if os.path.isdir(os.path.join(path, sub)):
                    return "object"

            # If we have a Namaste file but can't determine specific type, assume object
            return "object"

        # If it's neither file nor directory (e.g., socket, FIFO)
        return f"unsupported file type: {os.path.realpath(path)}"

    except Exception as exc:
        return f"unexpected error while determining path type: {exc}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import pathlib
    except Exception as e:
        return f'error: failed to import pathlib: {e}'
    p = pathlib.Path(path)
    if not p.exists():
        return f'error: path does not exist'
    if p.is_file():
        return 'file'
    if p.is_dir():
        namaste_file = None
        for child in p.iterdir():
            if child.is_file() and child.name.startswith('0='):
                namaste_file = child
                break
        if not namaste_file:
            return 'error: no namaste file found'
        # Read the namaste file
        try:
            with namaste_file.open('r', encoding='utf-8') as f:
                first_line = f.readline().strip()
        except Exception as e:
            return f'error: could not read namaste file: {e}'
        if not first_line.startswith('0='):
            return 'error: namaste file does not start with "0="'
        # Determine root vs object by counting subdirectories
        subdirs = [c for c in p.iterdir() if c.is_dir()]
        if len(subdirs) > 1:
            return 'root'
        else:
            return 'object'
    return 'error: unknown path type'

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params

        The method validates ``params`` and ``bug_ids`` and ensures that
        the Bugzilla API parameters contain a list of bug identifiers
        under the key ``ids``. Existing values are merged without
        duplication. ``bug_ids`` may be ``None``, an ``int``, a single
        ``str`` representation of an id or a sequence of ids."""


        # ------------ Validate & normalise ``params`` ----------------
        if params is None:
            params = {}
        if not isinstance(params, dict):
            raise TypeError(f"params must be a dict, got {type(params)!r}")

        # ------------ Normalise ``bug_ids`` ----------------------------
        if bug_ids is None:
            # nothing to amend – just return the original ``params``
            return params

        # Convert a single int or str into a list
        if isinstance(bug_ids, (int, str)):
            bug_ids = [bug_ids]

        # Ensure we have a sequence container (list/tuple/iterable)
        if not isinstance(bug_ids, (list, tuple)):
            raise TypeError(f"bug_ids must be a seq, int or str, got {type(bug_ids)!r}")

        # Filter out empty values
        bug_ids = [str(bid).strip() for bid in bug_ids if str(bid).strip()]

        if not bug_ids:
            # nothing to amend – return as is
            return params

        # ------------ Merge the ids into params -----------------------
        existing_ids = params.get("ids")
        if existing_ids:
            # If the existing value is a string, convert it to a list
            if isinstance(existing_ids, (str, bytes)):
                existing_ids = [existing_ids]
            elif not isinstance(existing_ids, (list, tuple)):
                # If its not a list/tuple/string, raise for clarity
                raise TypeError(
                    f"Existing 'ids' in params must be a list, tuple or string, "
                    f"got {type(existing_ids)!r}"
                )

            # Combine, preserving order and avoiding duplicates
            merged = list(existing_ids)  # copy existing list
            for bid in bug_ids:
                if bid not in merged:
                    merged.append(bid)
        else:
            merged = bug_ids

        params["ids"] = merged
        return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        return params
    try:
        # Build a comma separated list of bug IDs
        ids = []
        if isinstance(bug_ids, str):
            ids.append(bug_ids)
        else:
            for bid in bug_ids:
                if isinstance(bid, (int, float)):
                    ids.append(str(int(bid)))
                elif isinstance(bid, str):
                    ids.append(bid)
                else:
                    raise ValueError(f"Unsupported bug id type: {type(bid)}")
        if ids:
            params['id'] = ','.join(ids)
    except Exception as exc:
        raise RuntimeError(f"Failed to amend Bugzilla params: {exc}") from exc
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    try:
        from ruamel.yaml.nodes import MappingNode

        merged = {}
        for key_node, value_node in nodes:
            # Obtain a hashable representation of the key.  For scalar nodes the
            # .value attribute holds the key string.
            try:
                key = key_node.value
            except Exception:
                key = str(key_node)

            if key not in merged:
                merged[key] = (key_node, value_node)
                continue

            # Duplicate key seen – combine the values
            prev_key_node, prev_value_node = merged[key]

            # If both values are MappingNodes, merge their contents recursively.
            if isinstance(prev_value_node, MappingNode) and isinstance(value_node, MappingNode):
                try:
                    merged_pairs = prev_value_node.value + value_node.value
                except Exception:
                    merged_pairs = []
                merged_mapping = MappingNode(
                    tag=prev_value_node.tag,
                    value=deep_merge_nodes(merged_pairs)
                )
                merged[key] = (prev_key_node, merged_mapping)
            else:
                # For non-mapping values, the most recent one wins.
                merged[key] = (prev_key_node, value_node)

        # Preserve the order of first appearance by iterating over the dict items.
        return list(merged.values())
    except Exception:
        # In case ruamel or other unexpected errors occur, fall back to the original nodes
        return nodes

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to detect a MappingNode by class name.
    def is_mapping_node(node):
        return getattr(node, '__class__', None) is not None and node.__class__.__name__ == 'MappingNode'

    # Recursive merging of two mapping nodes.
    def merge_mapping_nodes(node1, node2):
        # Both node1 and node2 are expected to be MappingNode instances.
        merged_entries = {}
        # Helper to merge entries from a single mapping node's value list.
        def add_entries(mapping_node):
            # mapping_node.value is expected to be a list of (key_node, val_node) tuples.
            for k_node, v_node in mapping_node.value:
                key = getattr(k_node, 'value', None)
                if key is None:
                    continue
                if key in merged_entries:
                    existing_val = merged_entries[key]
                    if is_mapping_node(existing_val) and is_mapping_node(v_node):
                        merged_entries[key] = merge_mapping_nodes(existing_val, v_node)
                    else:
                        # Prefer the current (node2) entry
                        merged_entries[key] = (k_node, v_node)
                else:
                    merged_entries[key] = (k_node, v_node)

        add_entries(node1)
        add_entries(node2)

        # Build the list of merged tuples preserving order: node1 order first where not overridden.
        merged_tuples = []
        seen_keys = set()
        for k_node, v_node in node1.value:
            key = getattr(k_node, 'value', None)
            if key in merged_entries:
                merged_tuples.append(merged_entries[key])
                seen_keys.add(key)
        for k_node, v_node in node2.value:
            key = getattr(k_node, 'value', None)
            if key in merged_entries and key not in seen_keys:
                merged_tuples.append(merged_entries[key])
                seen_keys.add(key)
        # In case some keys were added only in node2 but not in node1
        for key, tuple_pair in merged_entries.items():
            if key not in seen_keys:
                merged_tuples.append(tuple_pair)
        # Construct a new MappingNode using the same type and tag as node1
        # If the constructor requires only tag and value, use that.
        try:
            return node1.__class__(node1.tag, merged_tuples)
        except Exception:
            # Fallback: try building with keyword arguments if possible
            return node1.__class__(tag=node1.tag, value=merged_tuples)

    # Main merge logic for the list of nodes
    merged_dict = {}
    for k_node, v_node in nodes:
        key = getattr(k_node, 'value', None)
        if key is None:
            continue
        if key in merged_dict:
            existing_node = merged_dict[key][1]
            if is_mapping_node(existing_node) and is_mapping_node(v_node):
                merged_dict[key] = (k_node, merge_mapping_nodes(existing_node, v_node))
            else:
                merged_dict[key] = (k_node, v_node)
        else:
            merged_dict[key] = (k_node, v_node)

    # Return the merged list preserving order: original order first where not overridden
    result = []
    seen_keys = set()
    for k_node, v_node in nodes:
        key = getattr(k_node, 'value', None)
        if key in merged_dict and key not in seen_keys:
            result.append(merged_dict[key])
            seen_keys.add(key)
    # Add any keys that were only in merged_dict but not in original nodes (unlikely)
    for key, pair in merged_dict.items():
        if key not in seen_keys:
            result.append(pair)
    return result

