def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    try:
        # Ensure we have a list of arguments
        args = list(unparsed_arguments)

        result = {}
        # Start with the global parser
        current_name = "global"
        current_args = []

        for token in args:
            # A token that does not start with '-' and is not empty is interpreted as a subcommand
            if token and not token.startswith('-'):
                # Save arguments collected for the previous command
                if current_name in result:
                    # Append to existing args if the same command occurs again
                    result[current_name].args.extend(current_args)
                else:
                    result[current_name] = argparse.Namespace(args=current_args)
                # Start a new command section
                current_name = token
                current_args = []
            else:
                current_args.append(token)

        # Save arguments for the last command section
        if current_name in result:
            result[current_name].args.extend(current_args)
        else:
            result[current_name] = argparse.Namespace(args=current_args)

        # Clean up empty global namespace if no global args were collected
        if not result["global"].args:
            del result["global"]

        return result

    except Exception as exc:
        # If parsing fails, raise a descriptive error
        raise ValueError(f"Failed to parse arguments: {exc}") from exc

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Ensure unparsed_arguments is a real list to allow repeated processing
    if not isinstance(unparsed_arguments, (list, tuple)):
        try:
            unparsed_arguments = list(unparsed_arguments)
        except Exception:
            raise TypeError("unparsed_arguments must be a sequence of strings") from None

    parsed_results = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        try:
            namespace, unknown = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            # If parsing fails (e.g., due to conflicting options), raise a runtime error
            raise RuntimeError(f"Error while parsing arguments for subparser '{name}'.") from exc

        parsed_results[name] = namespace
        unknown_sets.append(set(unknown))

    # Determine arguments not claimed by any subparser:
    if unknown_sets:
        remaining = [arg for arg in unparsed_arguments if all(arg in s for s in unknown_sets)]
    else:
        remaining = list(unparsed_arguments)

    return parsed_results, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a sequence of arguments")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dictionary mapping name to ArgumentParser")

    parsed = {}
    unknowns_map = {}

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"subparser '{name}' is not an argparse.ArgumentParser")

        try:
            ns, unknown = parser.parse_known_args(unparsed_arguments)
        except SystemExit as e:
            # argparse uses SystemExit to terminate on error or --help
            raise ValueError(f"Argument parsing failed for subparser '{name}'") from e

        parsed[name] = ns
        unknowns_map[name] = set(unknown)

    # Determine arguments that were not consumed by any subparser
    remaining = []
    for arg in unparsed_arguments:
        if all(arg in unknowns_map[name] for name in subparsers):
            remaining.append(arg)

    return parsed, remaining

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    try:
        import argparse
    except ImportError as exc:
        raise RuntimeError("argparse module is required") from exc

    parser = argparse.ArgumentParser(description='Command-line interface')
    # Support for older Python versions where 'required' is not an argument
    try:
        subparsers = parser.add_subparsers(dest='command', required=True)
    except TypeError:
        subparsers = parser.add_subparsers(dest='command')
        subparsers.required = True

    return parser, subparsers

def make_parsers():
    """
    Build a top-level parser and its subparsers and return them as a tuple.
    """
    try:
        import argparse
    except Exception as exc:
        raise RuntimeError('The argparse module is required for CLI parsing') from exc

    parser = argparse.ArgumentParser(description='Command-line interface')
    # Create subparsers
    try:
        # Preferred for Python 3.7+
        subparsers = parser.add_subparsers(dest='command', required=True)
    except TypeError:
        # Fall back for older Python versions
        subparsers = parser.add_subparsers(dest='command')
        # Attempt to enforce required subcommand
        try:
            subparsers.required = True  # type: ignore[attr-defined]
        except AttributeError:
            pass

    return parser, subparsers

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, MappingNode or other Node) tuples.
    Duplicate keys are merged recursively; non-mapping values are overridden
    by the last occurrence.
    """
    # Helper predicates to detect MappingNode-like objects
    def is_mapping_node(node):
        return hasattr(node, "value") and isinstance(node.value, list)

    def merge_value_nodes(prev_node, new_node):
        """
        Merge two nodes corresponding to the same key.
        If both are mapping nodes, merge recursively.
        Otherwise, the new_node (last seen) wins.
        """
        if is_mapping_node(prev_node) and is_mapping_node(new_node):
            # Build a dictionary of children from previous mapping
            children = {}
            for key_node, val_node in prev_node.value:
                key_id = (getattr(key_node, "tag", None), getattr(key_node, "value", None))
                children[key_id] = (key_node, val_node)

            # Merge/overwrite with new mapping's children
            for key_node, val_node in new_node.value:
                key_id = (getattr(key_node, "tag", None), getattr(key_node, "value", None))
                if key_id in children:
                    # Recursive merge
                    _, existing_val = children[key_id]
                    merged_val = merge_value_nodes(existing_val, val_node)
                    children[key_id] = (key_node, merged_val)
                else:
                    children[key_id] = (key_node, val_node)

            # Reconstruct the mapping node
            merged_list = list(children.values())
            return type(new_node)(new_node.tag, merged_list)
        else:
            # For non-mapping nodes, the new node wins
            return new_node

    # Merge top‑level nodes
    merged = {}
    for key_node, val_node in nodes:
        key_id = (getattr(key_node, "tag", None), getattr(key_node, "value", None))
        if key_id in merged:
            _, existing_val = merged[key_id]
            merged_val = merge_value_nodes(existing_val, val_node)
            merged[key_id] = (key_node, merged_val)
        else:
            merged[key_id] = (key_node, val_node)

    return list(merged.values())

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (key_node, value_node) tuples where keys are `ScalarNode`s
    and values are either `MappingNode`s or other node types. Keys that appear more
    than once will have their mapping values merged; if the values are not
    mappings, the last value wins.

    Arguments:
        nodes (list): List of tuples in the form
            (ScalarNode key, ValueNode value).

    Returns:
        list: A new list of tuples with duplicate keys merged.
    """
    # Helper predicates
    def is_mapping_node(node):
        try:
            return getattr(node, "tag", "").startswith("tag:yaml.org,2002:map")
        except Exception:
            return False

    def get_key_value(key_node):
        # Fallback to str if no value attribute
        return getattr(key_node, "value", str(key_node))

    def merge_mapping_values(mapping1, mapping2):
        """
        Merge two MappingNode.value lists (each list of (ScalarNode, ValueNode) tuples).
        """
        merged = {}
        for key_node, val_node in mapping1:
            merged[get_key_value(key_node)] = (key_node, val_node)
        for key_node, val_node in mapping2:
            k = get_key_value(key_node)
            if k in merged:
                existing_key_node, existing_val_node = merged[k]
                if is_mapping_node(existing_val_node) and is_mapping_node(val_node):
                    # Recursively merge nested mappings
                    merged_vals = merge_mapping_values(
                        existing_val_node.value, val_node.value
                    )
                    merged[k] = (
                        existing_key_node,
                        type(existing_val_node)(
                            tag=existing_val_node.tag,
                            value=merged_vals,
                        ),
                    )
                else:
                    # Non-mapping values: last one wins
                    merged[k] = (key_node, val_node)
            else:
                merged[k] = (key_node, val_node)
        return list(merged.values())

    result = {}
    for key_node, val_node in nodes:
        try:
            key = get_key_value(key_node)
        except Exception:
            # If we cannot derive a key, skip this entry
            continue
        if key in result:
            existing_key_node, existing_val_node = result[key]
            if is_mapping_node(existing_val_node) and is_mapping_node(val_node):
                # Merge mapping nodes recursively
                merged_vals = merge_mapping_values(
                    existing_val_node.value, val_node.value
                )
                merged_node = type(existing_val_node)(
                    tag=existing_val_node.tag,
                    value=merged_vals,
                )
                result[key] = (existing_key_node, merged_node)
            else:
                # For non-mapping values, last one wins
                result[key] = (key_node, val_node)
        else:
            result[key] = (key_node, val_node)

    # Return as a list preserving key order from input (first occurrence)
    return [value for _, value in result.values()]

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    # Helper to deep merge two lists of (ScalarNode, Node) tuples that belong to a MappingNode
    def _merge_mapping_values(v1, v2):
        merged = {}
        key_nodes = {}
        # Merge first list
        for k_node, v_node in v1:
            key = k_node.value
            if key not in merged:
                key_nodes[key] = k_node
                merged[key] = v_node
        # Merge second list (override duplicates)
        for k_node, v_node in v2:
            key = k_node.value
            if key in merged:
                # If both values are MappingNodes, merge recursively
                if isinstance(merged[key], MappingNode) and isinstance(v_node, MappingNode):
                    merged[key].value = _merge_mapping_values(merged[key].value, v_node.value)
                else:
                    merged[key] = v_node
                    key_nodes[key] = k_node  # keep the newest key node for consistency
            else:
                key_nodes[key] = k_node
                merged[key] = v_node
        # Build ordered list of tuples
        result = [(key_nodes[key], merged[key]) for key in key_nodes]
        return result

    result_dict = {}
    key_nodes = {}
    for k_node, v_node in nodes:
        key = k_node.value
        if key not in key_nodes:
            key_nodes[key] = k_node
        if key in result_dict:
            existing = result_dict[key]
            if isinstance(existing, MappingNode) and isinstance(v_node, MappingNode):
                # Deep merge MappingNodes
                merged_children = _merge_mapping_values(existing.value, v_node.value)
                existing.value = merged_children
            else:
                # Override with the latter value
                result_dict[key] = v_node
        else:
            result_dict[key] = v_node

    # Reconstruct the list preserving the order of first occurrence of each key
    merged_nodes = [(key_nodes[key], result_dict[key]) for key in key_nodes]
    return merged_nodes

def deep_merge_nodes(nodes):
    """
    Merge nodes that have duplicate keys by recursively merging MappingNodes.
    If duplicate keys have non-MappingNode values, the last value wins.
    """
    try:
        # Validate input type
        if not isinstance(nodes, list):
            raise ValueError("nodes must be a list of (ScalarNode, Node) tuples")

        # Store original order of first appearance
        order = []
        # Map key value to (key_node, merged_value_node)
        mapping = {}

        def is_mapping(node):
            """
            Heuristic to determine if a node is a MappingNode.
            """
            tag = getattr(node, "tag", "")
            return isinstance(tag, str) and tag.startswith("tag:yaml.org,2002:map")

        for key_node, value_node in nodes:
            # Guard against malformed tuples
            if key_node is None or value_node is None:
                continue
            key = getattr(key_node, "value", None)
            if key is None:
                continue

            if key not in mapping:
                order.append(key)
                mapping[key] = (key_node, value_node)
            else:
                old_key_node, old_value_node = mapping[key]
                if is_mapping(old_value_node) and is_mapping(value_node):
                    # Merge MappingNode values recursively
                    # Each MappingNode's .value is a list of (ScalarNode, Node) tuples
                    merged = deep_merge_nodes(old_value_node.value + value_node.value)
                    old_value_node.value = merged
                    mapping[key] = (old_key_node, old_value_node)
                else:
                    # Non-mapping values: last one wins
                    mapping[key] = (old_key_node, value_node)

        return [mapping[k] for k in order]
    except Exception as exc:
        raise RuntimeError(f"deep_merge_nodes error: {exc}") from exc

def deep_merge_nodes(nodes):
    """
    Merge duplicate mapping nodes in a list of (key, value) node tuples.
    Duplicate keys are merged recursively if both values are MappingNode objects.
    For non-mapping values, the last value wins.
    Parameters
    ----------
    nodes : list[tuple]
        A list of tuples where each tuple contains a key node (ScalarNode)
        and a value node (MappingNode or other Node).
    Returns
    -------
    list[tuple]
        A new list of tuples with duplicate keys merged.
    """
    # Helper to detect a MappingNode
    def _is_mapping(node):
        return getattr(node, "tag", None) == "tag:yaml.org,2002:map" and hasattr(node, "value")

    # Helper to create a new node of the same type as ``cls`` with provided tag, value, starts & ends
    def _make_node(cls, tag, value, start=None, end=None):
        try:
            return cls(tag, value)
        except TypeError:
            new_node = cls()
            if hasattr(new_node, "tag"):
                new_node.tag = tag
            if hasattr(new_node, "value"):
                new_node.value = value
            if start is not None and hasattr(new_node, "start_mark"):
                new_node.start_mark = start
            if end is not None and hasattr(new_node, "end_mark"):
                new_node.end_mark = end
            return new_node

    # Merge two MappingNodes recursively
    def _merge_mapping(node_a, node_b):
        # Extract mappings as dictionaries
        dict_a = {}
        for k, v in getattr(node_a, "value", []):
            dict_a[getattr(k, "value")] = (k, v)
        for k, v in getattr(node_b, "value", []):
            key = getattr(k, "value")
            if key in dict_a:
                _, existing_val = dict_a[key]
                if _is_mapping(existing_val) and _is_mapping(v):
                    merged_val = _merge_mapping(existing_val, v)
                else:
                    merged_val = v
                dict_a[key] = (dict_a[key][0], merged_val)
            else:
                dict_a[key] = (k, v)
        merged_list = [(k, v) for k, v in dict_a.values()]
        return _make_node(
            node_a.__class__,
            getattr(node_a, "tag", None),
            merged_list,
            start=getattr(node_a, "start_mark", None),
            end=getattr(node_a, "end_mark", None),
        )

    result = {}
    for key_node, val_node in nodes:
        if not hasattr(key_node, "value"):
            continue  # ignore malformed key nodes
        key = getattr(key_node, "value")
        if key in result:
            existing_key_node, existing_val_node = result[key]
            if _is_mapping(existing_val_node) and _is_mapping(val_node):
                merged_val = _merge_mapping(existing_val_node, val_node)
                result[key] = (existing_key_node, merged_val)
            else:
                result[key] = (existing_key_node, val_node)
        else:
            result[key] = (key_node, val_node)
    return [(k, v) for k, v in result.values()]

def parser_flags(parser):
    '''Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated
    string.'''
    # Validate the input
    if not isinstance(parser, type(None)):
        try:
            actions = parser._actions
        except AttributeError as exc:
            raise TypeError('Expected an argparse.ArgumentParser instance') from exc
    else:
        raise TypeError('Expected an argparse.ArgumentParser instance')

    flags = []
    seen = set()
    for action in actions:
        # option_strings may be an empty list for positional arguments
        for flag in action.option_strings:
            if flag not in seen:
                seen.add(flag)
                flags.append(flag)
    return ' '.join(flags)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string. Duplicate flags are removed while preserving the
    relative order of first appearance. If the parser argument is not a valid
    ArgumentParser instance, a TypeError is raised. If the input is None a
    ValueError is raised. If for any other reason the underlying attribute
    access fails, a RuntimeError is raised.
    """
    # Import inside to avoid unnecessary dependency if function is never called
    try:
        from argparse import ArgumentParser
    except ImportError as exc:
        raise ImportError("argparse module is required") from exc

    if parser is None:
        raise ValueError("parser argument cannot be None")

    if not isinstance(parser, ArgumentParser):
        raise TypeError(f"Expected argparse.ArgumentParser, got {type(parser).__name__}")

    try:
        actions = parser._actions
    except AttributeError as exc:
        raise RuntimeError("The provided parser does not expose '_actions' attribute") from exc

    flags = []
    for action in actions:
        # option_strings may be empty for positional arguments
        if getattr(action, "option_strings", None):
            flags.extend(action.option_strings)

    # Preserve order while removing duplicates
    seen = set()
    unique_flags = []
    for flag in flags:
        if flag not in seen:
            seen.add(flag)
            unique_flags.append(flag)

    return " ".join(unique_flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if not hasattr(parser, 'actions'):
        raise TypeError('Expected an argparse.ArgumentParser instance')
    try:
        # Collect all option strings defined by the parser
        flags = []
        for action in parser._actions:
            # Option strings are a list; skip actions without option strings (positional arguments)
            if hasattr(action, 'option_strings'):
                flags.extend(action.option_strings)
        # Remove duplicates while preserving order
        seen = set()
        unique_flags = []
        for flag in flags:
            if flag not in seen:
                seen.add(flag)
                unique_flags.append(flag)
        return ' '.join(unique_flags)
    except Exception as e:
        raise RuntimeError(f'Error extracting flags: {e}') from None

def parser_flags(parser):
