def bash_completion():
    """
    Return a bash completion script for the borgmatic command.
    Produce this by introspecting borgmatic's command-line argument parsers.
    """
    import importlib
    import traceback
    import argparse

    def _get_parser():
        """
        Attempt to find and invoke the function that returns the
        top-level argparse.ArgumentParser used by borgmatic.
        """
        # Common modules where borgmatic defines the parser
        candidate_modules = [
            'borgmatic.cli.main',
            'borgmatic.cli',
            'borgmatic.commands',
            'borgmatic',
        ]
        for mod_path in candidate_modules:
            try:
                mod = importlib.import_module(mod_path)
            except Exception:
                continue
            # Try to find a callable that returns a parser
            for attr in dir(mod):
                if attr == 'create_parser':
                    try:
                        parser = getattr(mod, attr)()
                        return parser
                    except Exception:
                        continue
                # Some modules expose the parser directly
                if attr == 'parser':
                    try:
                        parser = getattr(mod, attr)
                        if isinstance(parser, argparse.ArgumentParser):
                            return parser
                    except Exception:
                        continue
        return None

    try:
        parser = _get_parser()
        if not parser:
            return "# Error: Could not locate borgmatic's argparse parser."

        # Gather top‑level commands (subparsers) and flags
        commands = []
        if hasattr(parser, "_subparsers"):
            subp = None
            # _subparsers is an instance of argparse._SubParsersAction
            for action in parser._subparsers._actions:
                if isinstance(action, argparse._SubParsersAction):
                    subp = action
                    break
            if subp:
                commands = list(subp.choices.keys())

        flags = [opt for action in parser._actions if action.option_strings for opt in action.option_strings]

        all_words = commands + flags
        word_str = " ".join(all_words)

        script = f'''# Bash completion for borgmatic
_borgmatic_completions() {{
    local cur prev
    COMPREPLY=()
    cur="{{{{COMP_WORDS[COMP_CWORD]}}}}"
    prev="{{{{COMP_WORDS[COMP_CWORD-1]}}}}"
    if [[ $COMP_CWORD == 1 ]]; then
        COMPREPLY=( $(compgen -W "{word_str}" -- "$cur") )
        return 0
    fi
}}
complete -F _borgmatic_completions borgmatic
'''
        return script

    except Exception as exc:
        # Return a helpful error message in the script itself
        error_msg = traceback.format_exc()
        return f"# Error generating completion script:\\n{error_msg}"

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import subprocess, re
    except Exception as exc:
        raise RuntimeError("Required standard library modules could not be imported") from exc

    # Attempt to capture borgmatic help output to discover subcommands
    try:
        result = subprocess.run(
            ['borgmatic', '--help'],
            capture_output=True,
            text=True,
            timeout=5
        )
    except Exception:
        # If borgmatic is not installed or not callable, return an empty completion script
        return ''

    if result.returncode != 0 or not result.stdout:
        return ''

    help_text = result.stdout

    # The output of `borgmatic --help` contains a "Commands:" section listing all subcommands.
    # Extract those names.
    subcommands = []
    capture = False
    for line in help_text.splitlines():
        if capture:
            if line.strip() == '':
                break
            # The first field on each line is the command name
            first = line.split(None, 1)[0]
            if first:
                subcommands.append(first)
        if line.startswith('Commands:'):
            capture = True

    if not subcommands:
        # If no commands appear, fall back to a basic completion that offers nothing.
        return ''

    # Build a simple bash completion script that suggests the discovered subcommands.
    # This script can be sourced from .bashrc or used via the `complete` builtin.
    script = f'''# Bash completion for borgmatic
_borgmatic_completion() {{
    local cur prev words
    read -a words <<< "$(compgen -W "$(printf "%s\\n" {{"{" + " ".join(subcommands) + "}"}}) -- "{{{{COMP_WORDS[COMP_CWORD]}}}}")"
    COMPREPLY=( $(compgen -W "{ " ".join(subcommands) }" -- "$cur") )
    return 0
}}
complete -F _borgmatic_completion borgmatic
'''
    return script.replace('\\n', '\n')

def bash_completion():
    """
    Return a bash completion script for the borgmatic command.
    Produce this by introspecting borgmatic's click command-line
    argument parsers. If borgmatic cannot be imported or does
    not expose a click.Command object, a helpful error message
    is returned instead. The completion script completes the
    top-level subcommands of the borgmatic CLI.
    """
    import importlib, sys
    try:
        import click
    except Exception:
        return "# Error: click module is missing or cannot be imported."
    try:
        borgmod = importlib.import_module("borgmatic")
    except Exception:
        return "# Error: borgmatic module could not be imported."
    # Find the top-level click.Command instance
    root_cmd = None
    for obj in vars(borgmod).values():
        # click 8.1+ uses click.core.Command, older versions use click.Command
        if isinstance(obj, getattr(click.core, "Command", click.Command)):
            root_cmd = obj
            break
    if not root_cmd:
        return "# Error: No click.Command instance found in borgmatic."
    # Build a command completion list
    try:
        subcommands = sorted(root_cmd.commands.keys())
    except Exception:
        subcommands = []
    # Ensure fallback in case of empty subcommands
    if not subcommands:
        subcommands = []
    # Bash completion script
    script = f'''
# Bash completion for borgmatic
_borgmatic_completions()
{{
    local cur prev words
    cur="${{COMP_WORDS[COMP_CWORD]}}"
    prev="${{COMP_WORDS[COMP_CWORD-1]}}"

    case ${{COMP_CWORD}} in
        1)
            COMPREPLY=( $(compgen -W "{" ".join(subcommands)}" -- "$cur") )
            ;;
        *)
            ;;
    esac
}}
complete -F _borgmatic_completions borgmatic
'''
    return script.strip()

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    # Base parser for global options (no specific options known at this level)
    try:
        base_parser = argparse.ArgumentParser(add_help=False, allow_abbrev=False)
    except Exception:
        # If the parser cannot be created, return empty mapping
        return {}

    # Separate global arguments from remaining tokens
    try:
        global_args, remaining = base_parser.parse_known_args(unparsed_arguments)
    except Exception:
        # In case of parsing error, return empty mapping
        return {}

    result = {"global": global_args}

    # Identify the first non-option token as the subparser name
    subparser_name = None
    subparser_index = None
    for idx, token in enumerate(remaining):
        if not token.startswith('-'):
            subparser_name = token
            subparser_index = idx
            break

    if subparser_name is not None:
        # Tokens following the subparser name are its arguments
        sub_tokens = remaining[subparser_index + 1 :]
        try:
            sub_parser = argparse.ArgumentParser(add_help=False, allow_abbrev=False)
            sub_args, unknown = sub_parser.parse_known_args(sub_tokens)
            # Attach any unknown arguments so they are not lost
            sub_args.unknown = unknown
            result[subparser_name] = sub_args
        except Exception:
            # If subparser parsing fails, silently ignore and keep only global
            pass

    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Defensive copy and validation
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of arguments")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping name to ArgumentParser")

    parsed = {}
    unknowns = {}

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            # Skip invalid parser
            parsed[name] = None
            unknowns[name] = set()
            continue
        try:
            ns, unknown = parser.parse_known_args(list(unparsed_arguments))
            parsed[name] = ns
            unknowns[name] = set(unknown)
        except Exception:
            # In case of unexpected error parsing, treat as no claims
            parsed[name] = None
            unknowns[name] = set(unparsed_arguments)

    # Determine remaining arguments that were not claimed by any valid subparser
    remaining = []
    for arg in unparsed_arguments:
        # If all parsers consider this arg unknown, keep it
        if all(arg in unknowns[name] for name in subparsers):
            remaining.append(arg)

    return parsed, remaining

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """

    if not isinstance(response, list):
        raise TypeError("response must be a list")

    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")

    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    def _generator():
        total = len(response)
        for start in range(0, total, max_results):
            yield response[start:start + max_results]

    return _generator()

