def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args."""
    # Validate input types
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        return url

    # Build a mapping from url_args
    if isinstance(url_args, dict):
        args_map = url_args
    else:
        # Accept list/tuple of (key, value) pairs
        try:
            args_map = {k: v for k, v in url_args}
        except Exception:
            raise TypeError("url_args must be a dict or iterable of (key, value) pairs")

    # Replace placeholders in the form {key} with the corresponding values
    result = url
    for key, value in args_map.items():
        placeholder = f"{{{key}}}"
        if placeholder in result:
            try:
                value_str = str(value)
            except Exception:
                # If value cannot be cast to string, skip replacement
                continue
            result = result.replace(placeholder, value_str)

    return result

