def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated
    string.
    '''
    # Validate the input
    try:
        import argparse
    except Exception:
        raise RuntimeError("argparse module could not be imported")
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    # Gather flags from the parser's actions
    flags = []
    try:
        for action in getattr(parser, '_actions', []):
            # Each action has an option_strings attribute containing flags like '-v' or '--verbose'
            if hasattr(action, 'option_strings'):
                for flag in action.option_strings:
                    if flag and flag not in flags:
                        flags.append(flag)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract flags: {exc}") from exc

    return ' '.join(flags)

