def was_processed(processed, path_name, verbose):
    """
    Check if a file or directory has already been processed.
    """
    try:
        # Validate inputs
        if not isinstance(processed, set):
            raise TypeError("`processed` must be a set")
        if not isinstance(path_name, str):
            raise TypeError("`path_name` must be a string")

        # Expand to absolute path if possible
        abs_path = path_name
        if "os" in globals():
            try:
                abs_path = os.path.abspath(path_name)
            except Exception:
                # Fallback: keep original path
                abs_path = path_name

        # Check if already processed
        if abs_path in processed:
            if verbose:
                print(f"Already processed: {abs_path}")
            return True

        # Mark as processed
        processed.add(abs_path)
        return False

    except Exception as exc:
        if verbose:
            print(f"Error in was_processed for '{path_name}': {exc}")
        # In case of an error, treat as already processed to avoid re‑processing
        return True

def was_processed(processed, path_name, verbose):
    """
    Check if a file or directory has already been processed.

    Expands `path_name` to its absolute form, checks against the `processed`
    collection, reports verbose information when requested, and updates the
    collection when appropriate.

    Args:
        processed: Collection that implements ``add`` and membership test.
        path_name: Path to a directory or file.
        verbose:  True to display status messages.

    Returns:
        True if the absolute path was already present in ``processed``; otherwise
        False (and the path is added to ``processed``).
    """
    # Resolve to an absolute path
    try:
        abs_path = os.path.abspath(path_name)
    except Exception:
        if verbose:
            print(f"Unable to resolve path: {path_name!r}")
        return False

    # Already processed?
    try:
        if abs_path in processed:
            if verbose:
                print(f"Already processed: {abs_path}")
            return True
    except Exception:
        if verbose:
            print(f"Membership test failed for: {abs_path}")
        return False

    # Register as processed
    try:
        processed.add(abs_path)
    except Exception:
        if verbose:
            print(f"Failed to add processed path: {abs_path}")
    return False

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise TypeError("number must be an int")
    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("alphabet must be a non-empty list")
    if any(not isinstance(v, str) for v in alphabet):
        raise ValueError("alphabet must contain strings only")
    base = len(alphabet)
    negative = number < 0
    n = abs(number)
    digits = []
    if n == 0:
        digits.append(alphabet[0])
    else:
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
    digits = digits[::-1]
    s = "".join(digits)
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer")
        if len(s) < padding:
            s = alphabet[0] * (padding - len(s)) + s
    if negative:
        s = "-" + s
    return s

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """Convert a non‑negative integer to a string using the supplied alphabet."""
    # Validate input types
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list) or len(alphabet) < 2:
        raise ValueError("alphabet must be a list containing at least two symbols")
    # Ensure each alphabet element is a string
    for sym in alphabet:
        if not isinstance(sym, str):
            raise TypeError("each alphabet symbol must be a string")

    base = len(alphabet)

    # Convert number to base representation
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        digits.reverse()
        result = "".join(digits)

    # Apply optional padding
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer")
        if padding < 0:
            raise ValueError("padding must be non-negative")
        if len(result) < padding:
            pad_char = alphabet[0]
            pad_len = padding - len(result)
            result = pad_char * pad_len + result

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a non‑negative integer to a string using the supplied alphabet.
    The output has the most significant digit first.  If `padding` is
    supplied the result is left‑padded with the first alphabet character
    to the requested minimum width.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non‑negative")
    if not isinstance(alphabet, list) or not all(isinstance(d, str) for d in alphabet):
        raise TypeError("alphabet must be a list of strings")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two characters")
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non‑negative integer or None")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])

    result = "".join(reversed(digits))

    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic input validation
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list) or not all(isinstance(ch, str) and len(ch) == 1 for ch in alphabet):
        raise TypeError("alphabet must be a list of single-character strings")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two characters to represent a base")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("padding must be None or a non-negative integer")

    base = len(alphabet)

    # Handle the sign
    sign = ''
    if number < 0:
        sign = '-'
        number = -number

    # Convert to base representation
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        try:
            while number > 0:
                number, rem = divmod(number, base)
                digits.append(alphabet[rem])
        except Exception as exc:
            raise ValueError(f"Error during base conversion: {exc}") from exc
        result = ''.join(reversed(digits))

    # Apply padding if requested (only to the numeric part)
    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    # Prepend sign if needed
    return sign + result if sign else result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    # Validate types
    if not isinstance(flow_params, dict):
        raise TypeError(f"flow_params must be a dict, got {type(flow_params).__name__}")
    if not isinstance(register_value, (str, int, float, tuple, frozenset)):
        raise TypeError(f"register_value must be a hashable key type, got {type(register_value).__name__}")
    if not isinstance(register_number, (str, int, float, tuple, frozenset)):
        raise TypeError(f"register_number must be a hashable key type, got {type(register_number).__name__}")

    # Create a copy to avoid mutating the original dictionary
    new_params = flow_params.copy()

    # Perform the key replacement if possible
    try:
        value = new_params.pop(register_value)
    except KeyError:
        # If the key does not exist, simply return the original (or copy)
        return new_params

    # If the new register key already exists, merge by creating a list of values
    if register_number in new_params:
        existing = new_params[register_number]
        if isinstance(existing, list):
            if isinstance(value, list):
                existing.extend(value)
            else:
                existing.append(value)
        else:
            new_list = [existing]
            if isinstance(value, list):
                new_list.extend(value)
            else:
                new_list.append(value)
            new_params[register_number] = new_list
    else:
        new_params[register_number] = value

    return new_params

