    if not isinstance(cls, type):
        raise TypeError("The argument must be a class type.")
    result = set()
    try:
        stack = list(cls.__subclasses__())
    except Exception:
        return result
    while stack:
        sub = stack.pop()
        if sub not in result:
            result.add(sub)
            try:
                stack.extend(sub.__subclasses__())
            except Exception:
                pass
    return result

