def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic validation of inputs
    if not isinstance(string, str):
        raise TypeError(f"Expected string for 'string', got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"Expected list for 'alphabet', got {type(alphabet).__name__}")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two distinct characters")

    # Build a mapping from character to its numeric value
    char_to_value = {}
    for idx, ch in enumerate(alphabet):
        if ch in char_to_value:
            raise ValueError(f"Duplicate character '{ch}' found in alphabet")
        char_to_value[ch] = idx

    # Convert the string to an integer
    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        result = result * base + char_to_value[ch]

    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
