    base = len(alphabet)
    if base == 0:
        raise ValueError("alphabet must contain at least one symbol")
    # Empty string yields 0
    if string == "":
        return 0
    # Convert string to integer
    result = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"Character {ch!r} not found in alphabet")
        result = result * base + mapping[ch]
    return result

