def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise ValueError("Input must be a dictionary.")

    result = {}
    for key, value in item.items():
        try:
            # Convert wildcard pattern to regex
            # Escape all regex meta chars except '*'
            escaped_parts = []
            for ch in key:
                if ch == '*':
                    escaped_parts.append('.*')
                else:
                    escaped_parts.append(re.escape(ch))
            regex_key = '^' + ''.join(escaped_parts) + '$'
            result[regex_key] = value
        except Exception as e:
            # Preserve the original key if conversion fails
            result[key] = value
    return result

