    result = {}
    for key, value in item.items():
        if not isinstance(key, str):
            # If key is not a string, keep it as-is
            result[key] = value
            continue
        # Check if key contains wildcard characters
        if '*' in key or '?' in key:
            # Build regex pattern
            pattern_parts = ['^']
            for ch in key:
                if ch == '*':
                    pattern_parts.append('.*')
                elif ch == '?':
                    pattern_parts.append('.')
                elif ch in meta_chars:
                    pattern_parts.append('\\' + ch)
                else:
                    pattern_parts.append(ch)
            pattern_parts.append('$')
            regex_key = ''.join(pattern_parts)
            result[regex_key] = value
        else:
            # No wildcard, keep key unchanged
            result[key] = value
    return result

