def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Validate input string
    if not isinstance(s, str):
        raise TypeError("first argument must be a string")

    # Determine posix mode based on platform argument
    if isinstance(platform, str):
        if platform.lower() == 'this':
            posix_mode = os.name != 'nt'
        else:
            raise ValueError("platform string must be 'this', '1' or '0'")
    elif isinstance(platform, int):
        if platform == 1:
            posix_mode = True
        elif platform == 0:
            posix_mode = False
        else:
            raise ValueError("platform integer must be 1 (POSIX) or 0 (Windows)")
    else:
        raise TypeError("platform must be a string or an integer")

    # Perform split using shlex with appropriate posix setting
    try:
        return shlex.split(s, posix=posix_mode)
    except ValueError as exc:
        raise ValueError(f"Failed to split command string: {s!r}") from exc

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if s is None:
        raise TypeError("None cannot be split as a string")
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s)!r}")

    import os
    import shlex

    # Resolve platform
    if platform == 'this':
        platform = 0 if os.name == 'nt' else 1
    # Determine splitting strategy
    if platform == 1:
        # POSIX style (default shlex behavior)
        try:
            return shlex.split(s, posix=True)
        except ValueError as e:
            raise ValueError(f"POSIX split failed: {e}") from None
    elif platform == 0:
        # Windows CMD style (posix=False)
        try:
            return shlex.split(s, posix=False)
        except ValueError as e:
            raise ValueError(f"Windows split failed: {e}") from None
    else:
        raise ValueError(f"Unsupported platform {platform!r}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess

    tmp_path_str = str(tmp_path).rstrip("/\\")
    # Compute the base name of the archive (without directories)
    base_name = archive_path.rsplit("/", 1)[-1].rsplit("\\", 1)[-1]
    # Determine the destination directory
    if filename:
        repo_dir = tmp_path_str + "/" + filename.strip("/\\")
    else:
        # Strip common archive extensions to get a base folder name
        stripped = None
        for ext in (".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".tar.xz", ".txz", ".zip", ".tar"):
            if base_name.endswith(ext):
                stripped = base_name[:-len(ext)]
                break
        if stripped is None:
            stripped = base_name.rsplit(".", 1)[0]
        repo_dir = tmp_path_str + "/" + stripped

    # Create the destination directory
    try:
        subprocess.run(["mkdir", "-p", repo_dir], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Could not create extraction directory '{repo_dir}': {exc}") from exc

    # Build the extraction command based on the archive type
    if archive_path.endswith(".zip"):
        cmd = ["unzip", "-q", archive_path, "-d", repo_dir]
    elif archive_path.endswith((".tar.gz", ".tgz")):
        cmd = ["tar", "-xzf", archive_path, "-C", repo_dir]
    elif archive_path.endswith((".tar.bz2", ".tbz2")):
        cmd = ["tar", "-xjf", archive_path, "-C", repo_dir]
    elif archive_path.endswith((".tar.xz", ".txz")):
        cmd = ["tar", "-xJf", archive_path, "-C", repo_dir]
    elif archive_path.endswith(".tar"):
        cmd = ["tar", "-xf", archive_path, "-C", repo_dir]
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

    # Execute the extraction
    try:
        subprocess.run(cmd, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Extraction of '{archive_path}' failed: {exc}") from exc

    return f"file://{repo_dir}"

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        result = subprocess.run(
            ["git", "ls-files", "--others", "--ignored", "--exclude-standard"],
            capture_output=True,
            text=True,
            check=True,
        )
    except (subprocess.SubprocessError, FileNotFoundError):
        return ""

    files = [line.strip() for line in result.stdout.splitlines() if line.strip()]
    if ignored:
        files = [f for f in files if ignored in f]
    files.sort()
    return ",".join(files)

