def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string, None, or 'always'")
    if frequency.strip().lower() == "always":
        return None

    import re
    pattern = r'^\s*(\d+)\s*([a-zA-Z]+)\s*$'
    match = re.match(pattern, frequency)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")

    value = int(match.group(1))
    unit = match.group(2).lower()

    if unit in ('d', 'day', 'days'):
        return datetime.timedelta(days=value)
    if unit in ('w', 'week', 'weeks'):
        return datetime.timedelta(weeks=value)
    if unit in ('h', 'hour', 'hours'):
        return datetime.timedelta(hours=value)
    if unit in ('m', 'min', 'mins', 'minute', 'minutes'):
        return datetime.timedelta(minutes=value)
    if unit in ('s', 'sec', 'secs', 'second', 'seconds'):
        return datetime.timedelta(seconds=value)
    if unit in ('month', 'months'):
        return datetime.timedelta(days=30 * value)
    if unit in ('year', 'years'):
        return datetime.timedelta(days=365 * value)

    raise ValueError(f"Unrecognized time unit: {unit!r}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    import datetime
    import re

    if frequency is None:
        return None

    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string, got {type(frequency).__name__}")

    freq_str = frequency.strip()
    if freq_str.lower() == 'always':
        return None

    # Regex to capture number (int or float) and a single unit
    match = re.match(r'^\s*([+-]?\d+(?:\.\d*)?)\s*([A-Za-z]+)?\s*$', freq_str)
    if not match:
        raise ValueError(f"Invalid frequency format: '{frequency}'")

    number_str, unit = match.groups()
    try:
        number = float(number_str)
    except ValueError:
        raise ValueError(f"Cannot parse number from frequency: '{frequency}'")

    if not unit:
        raise ValueError(f"No unit specified in frequency: '{frequency}'")

    unit = unit.lower()
    if unit in ("days", "day", "d"):
        kwargs = {"days": number}
    elif unit in ("weeks", "week", "w"):
        kwargs = {"weeks": number}
    elif unit in ("hours", "hour", "h"):
        kwargs = {"hours": number}
    elif unit in ("minutes", "minute", "m"):
        kwargs = {"minutes": number}
    elif unit in ("seconds", "second", "s"):
        kwargs = {"seconds": number}
    elif unit in ("milliseconds", "millisecond", "ms"):
        kwargs = {"milliseconds": number}
    elif unit in ("microseconds", "microsecond", "us", "µs"):
        kwargs = {"microseconds": number}
    else:
        raise ValueError(f"Unknown time unit '{unit}' in frequency: '{frequency}'")

    return datetime.timedelta(**kwargs)

