def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = str(frequency).strip()
    if freq_str.lower() == "always":
        return None
    if not freq_str:
        raise ValueError("Empty frequency string")

    parts = freq_str.split()
    if len(parts) != 2:
        raise ValueError(f"Frequency '{freq_str}' is not in 'number unit' format")

    number_str, unit_str = parts
    try:
        number = int(number_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{number_str}'")

    unit_str = unit_str.lower()
    unit_map = {
        "day": "days", "days": "days",
        "hour": "hours", "hours": "hours",
        "minute": "minutes", "minutes": "minutes", "min": "minutes", "mins": "minutes",
        "second": "seconds", "seconds": "seconds", "sec": "seconds", "secs": "seconds",
        "week": "weeks", "weeks": "weeks"
    }

    if unit_str not in unit_map:
        raise ValueError(f"Unrecognized unit in frequency: '{unit_str}'")

    kwargs = {unit_map[unit_str]: number}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Validate input
    if not isinstance(host, str) or not host:
        return False
    try:
        # Retrieve all address info for the host (IPv4 and IPv6)
        addr_info = socket.getaddrinfo(host, None)
    except (socket.gaierror, OverflowError, ValueError):
        # Hostname cannot be resolved or invalid input
        return False

    for family, _socktype, _proto, _canon, sockaddr in addr_info:
        # sockaddr for IPv4 is (address, port, flow info, scope id)
        # for IPv6 is (address, port, flow info, scope id)
        ip = sockaddr[0]
        if family == socket.AF_INET:
            # Loopback range for IPv4 is 127.0.0.0/8
            # Accept any IP that starts with '127.'
            if ip == '127.0.0.1' or ip.startswith('127.'):
                return True
        elif family == socket.AF_INET6:
            # Loopback address for IPv6 is ::1
            if ip == '::1':
                return True
    return False

def is_local(host):
    """Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Validate input
    if not isinstance(host, str) or not host.strip():
        return False
    host = host.strip()
    try:
        # Resolve the host to its address info
        addrinfo = socket.getaddrinfo(host, None, 0, socket.SOCK_STREAM)
        for _, _, _, _, sockaddr in addrinfo:
            addr = sockaddr[0]
            # IPv6 loopback
            if ":" in addr and addr == "::1":
                return True
            # IPv4 loopback
            if ":" not in addr and addr == "127.0.0.1":
                return True
        # Direct comparison for typical names
        if host.lower() == "localhost":
            return True
        return False
    except socket.gaierror:
        # Failed to resolve host
        return False
    except Exception:
        # Any other unexpected error
        return False

def is_local(host):
