        return False

def is_gitbash():
    """returns True if you run in a Windows gitbash
    :return: True if gitbash
    """
    try:
        import os
        import sys
        msystem = os.environ.get('MSYSTEM')
        if msystem and msystem.upper().startswith(('MINGW', 'MSYS')):
            return sys.platform.startswith('win')
        # Fallback detection via OSTYPE
        ostype = os.environ.get('OSTYPE', '')
        if 'msys' in ostype.lower():
            return sys.platform.startswith('win')
    except Exception:
        return False
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    # Basic type checks
    if not isinstance(config_filename, (str, os.PathLike)):
        raise TypeError(f"config_filename must be a string or PathLike object, got {type(config_filename)}")
    if not isinstance(rendered_config, str):
        raise TypeError(f"rendered_config must be a string, got {type(rendered_config)}")
    if not isinstance(mode, int):
        raise TypeError(f"mode must be an int, got {type(mode)}")
    if mode < 0 or mode > 0o777:
        raise ValueError(f"mode must be between 0 and 0o777, got {oct(mode)}")
    if not isinstance(overwrite, bool):
        raise TypeError(f"overwrite must be a bool, got {type(overwrite)}")

    # Resolve path
    try:
        path = os.fspath(config_filename)
    except Exception as exc:
        raise ValueError(f"Invalid config_filename: {exc}") from exc

    dir_name = os.path.dirname(path)
    if dir_name and not os.path.exists(dir_name):
        try:
            os.makedirs(dir_name, exist_ok=True)
        except Exception as exc:
            raise OSError(f"Failed to create directories '{dir_name}': {exc}") from exc

    # Check existence
    if os.path.exists(path) and not overwrite:
        raise FileExistsError(f"File '{path}' already exists and overwrite is False")

    # Write the file with the specified mode
    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, mode)
        try:
            with os.fdopen(fd, 'w', encoding='utf-8') as f:
                f.write(rendered_config)
        except Exception:
            os.close(fd)
            raise
    except Exception as exc:
        raise OSError(f"Failed to write configuration to '{path}': {exc}") from exc

    return None

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Input validation
    import os
    if not isinstance(config_filename, (str, os.PathLike)):
