    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Resolve file path
    cfg_path = os.fspath(config_filename)

    # Check if file exists
    if os.path.exists(cfg_path):
        if not overwrite:
            raise FileExistsError(f"The file '{cfg_path}' already exists and overwrite is False.")

    # Ensure parent directories exist
    parent_dir = os.path.dirname(cfg_path)
    if parent_dir and not os.path.isdir(parent_dir):
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except Exception as exc:
            raise OSError(f"Could not create directories for '{cfg_path}': {exc}") from exc

    # Write the configuration
    try:
        with open(cfg_path, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        os.chmod(cfg_path, mode)
    except Exception as exc:
        raise OSError(f"Failed to write configuration to '{cfg_path}': {exc}") from exc

    return cfg_path

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate input types
    if not isinstance(config_filename, str):
        raise TypeError(f'config_filename must be a string, got {type(config_filename).__name__}')
    if not isinstance(rendered_config, (str, bytes)):
        raise TypeError(f'rendered_config must be str or bytes, got {type(rendered_config).__name__}')
    if not isinstance(mode, int):
        raise TypeError(f'mode must be an integer, got {type(mode).__name__}')
    if not isinstance(overwrite, bool):
        raise TypeError(f'overwrite must be a boolean, got {type(overwrite).__name__}')

    # Ensure parent directories exist
    parent_dir = os.path.dirname(os.path.abspath(config_filename))
    try:
        os.makedirs(parent_dir, exist_ok=True)
    except OSError as e:
        raise OSError(f'Failed to create directories for {config_filename}: {e}') from e

    # If file exists and overwrite is False, abort
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f'File {config_filename} already exists and overwrite is False')

    # Write the configuration to the file
    try:
        # Write using binary mode if rendered_config is bytes
        if isinstance(rendered_config, bytes):
            with open(config_filename, 'wb', buffering=0) as f:
                f.write(rendered_config)
        else:
            with open(config_filename, 'w', encoding='utf-8', buffering=1) as f:
                f.write(rendered_config)
        # Apply the desired file mode
        os.chmod(config_filename, mode)
    except OSError as e:
        raise OSError(f'Failed to write configuration to {config_filename}: {e}') from e

    return None

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    # Validate separator
    if not isinstance(seperator, str):
        raise TypeError(f"separator must be a string, got {type(seperator).__name__}")
    # Helper function to normalize a line
    def _normalize_line(line):
        if not isinstance(line, str):
            raise TypeError(f"script line must be a string, got {type(line).__name__}")
        return line.strip()
    # Handle script input type
    if script is None:
        raise ValueError("script cannot be None")
    # If script is a string, split into lines
    if isinstance(script, str):
        raw_lines = script.splitlines()
    # If script is an iterable of lines but not a string, iterate
    elif hasattr(script, "__iter__") and not isinstance(script, (bytes, bytearray)):
        raw_lines = list(script)
    else:
        raise TypeError(f"script must be a string or iterable of strings, got {type(script).__name__}")
    # Normalize and filter empty lines
    try:
        lines = [_normalize_line(line) for line in raw_lines]
    except Exception as e:
        raise RuntimeError(f"Failed to normalize script lines: {e}") from e
    # Remove empty strings
    lines = [line for line in lines if line]
    # Join with separator
    single_line = seperator.join(lines)
    return single_line

