    # Join with the specified separator
    return seperator.join(lines)

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if not isinstance(matcher, str):
        raise TypeError("matcher must be a string")
    if matcher == "":
        raise ValueError("Empty matcher string")
    # Split on the first ':' to separate name and optional default
    if ":" in matcher:
        name, default = matcher.split(":", 1)
    else:
        name, default = matcher, None
    name = name.strip()
    if not name:
        raise ValueError("Variable name missing in matcher")
    value = os.getenv(name)
    if value is not None:
        return value
    if default is not None:
        return default
    raise EnvironmentError(f"Environment variable '{name}' not set and no default provided")

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    try:
        # Extract the variable name and optional default from the matcher
        if isinstance(matcher, (tuple, list)):
            if not matcher:
                raise TypeError("Matcher tuple/list is empty; expected at least a variable name.")
            name = matcher[0]
            default = matcher[1] if len(matcher) > 1 else None
        elif isinstance(matcher, dict):
            # Support a mapping with 'name' and optional 'default' keys
            if 'name' not in matcher:
                raise TypeError("Matcher dictionary missing required 'name' key.")
            name = matcher['name']
            default = matcher.get('default')
        else:
            # If it's something else, treat it as a single variable name
            name = matcher
            default = None

        # Ensure the name is a string
        if not isinstance(name, str):
            raise TypeError(f"Expected variable name to be a string, got {type(name).__name__}.")

        # Retrieve the environment variable
        value = os.environ.get(name)
        if value is not None:
            return value
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not found and no default provided.")
    except Exception as exc:
        # Re-raise with more contextual information
        raise RuntimeError(f"Failed to resolve environment variable: {exc}") from exc

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an
    optional default value. If the variable is not defined in environment
    and no default value is provided, KeyError is raised.
    """
    if matcher is None:
        raise TypeError("`matcher` must not be None")

    # When matcher is a re.Match object (common in templating)
    if hasattr(matcher, "groupdict") and callable(matcher.groupdict):
        groups = matcher.groupdict()
        name = groups.get("name") or groups.get("0")
        default = groups.get("default")

        # Fall back to positional groups if named groups are absent
        if name is None and matcher.lastindex >= 1:
            name = matcher.group(1)
        if default is None and matcher.lastindex >= 2:
            default = matcher.group(2)
    else:
        # Assume matcher is a plain string in the form "VAR" or "VAR:DEFAULT"
        if not isinstance(matcher, str):
            raise TypeError("`matcher` must be a match object or a string")

        # Split using the first occurrence of ':-' or ':'
        if ":-" in matcher:
            name, default = matcher.split(":-", 1)
        elif ":" in matcher:
            name, default = matcher.split(":", 1)
        else:
            name, default = matcher, None

    # Clean up
    name = name.strip() if isinstance(name, str) else ""
    default = default.rstrip("\n") if isinstance(default, str) else default

    if not name:
        raise ValueError("environment variable name is empty")

    # Retrieve the environment variable safely
    try:
        value = os.getenv(name)
    except Exception as exc:
        raise RuntimeError(f"Error accessing environment variable '{name}'") from exc

    if value is not None:
        return value

    if default is not None:
        return default

    raise KeyError(
        f"Environment variable '{name}' is not set and no default value provided"
    )

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    Args:
        image_href: href of an image

    Returns:
        A tuple of (image_id, netloc, use_ssl)

    Raises:
        ValueError: if image_href is not a valid URL or missing components.
    """
    if not isinstance(image_href, str) or not image_href.strip():
        raise ValueError("image_href must be a non-empty string")
    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Unable to parse image_href: {exc}") from exc

    scheme = parsed.scheme.lower()
    use_ssl = scheme == "https"
    if scheme not in ("http", "https"):
        raise ValueError(f"Unsupported URL scheme '{scheme}'. Only http and https are supported.")
    netloc = parsed.netloc
    if not netloc:
        raise ValueError("URL missing network location (netloc).")

    image_id = parsed.path.lstrip("/")
    if not image_id:
        raise ValueError("URL missing image identifier (path).")

    return (image_id, netloc, use_ssl)

def _parse_image_ref(image_href: str) -> tuple:
    """
    Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str) or not image_href.strip():
        raise ValueError("image_href must be a non-empty string")

    try:
        parsed = urllib.parse.urlparse(image_href.strip())
    except Exception as exc:
        raise ValueError(f"Unable to parse URL: {exc}") from exc

    if not parsed.scheme:
        raise ValueError("URL must contain a scheme (e.g., http or https)")

    netloc = parsed.netloc
    if not netloc:
        raise ValueError("URL must contain a network location (netloc)")

    use_ssl = parsed.scheme.lower() == "https"

    # Extract the image identifier from the path.
    path = parsed.path
    if path.endswith("/"):
        path = path[:-1]
    image_id = urllib.parse.unquote(path.split("/")[-1]) if path else ""

    if not image_id:
        raise ValueError("Unable to determine image ID from the provided href")

    return (image_id, netloc, use_ssl)

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError(f"image_href must be a string, got {type(image_href)!r}")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid image href: {image_href}") from exc

    if not parsed.scheme:
        raise ValueError(f"Missing scheme in image href: {image_href}")

    if not parsed.netloc:
        raise ValueError(f"Missing netloc in image href: {image_href}")

    use_ssl = parsed.scheme.lower() == "https"

    # Extract the image identifier from the path component
    # Remove any leading slash and strip trailing slashes
    image_id = parsed.path.lstrip("/")
    if image_id.endswith("/"):
        image_id = image_id.rstrip("/")
    if not image_id:
        raise ValueError(f"Missing image identifier in image href: {image_href}")

    return (image_id, parsed.netloc, use_ssl)

def remove_ending_os_sep(input_list):
    import os
    if not isinstance(input_list, list):
        raise TypeError("input_list must be a list")
    processed = []
    for idx, item in enumerate(input_list):
        if not isinstance(item, str):
            raise TypeError(f"Element at index {idx} is not a string")
        if len(item) > 1 and item.endswith(os.sep):
            processed.append(item[:-1])
        else:
            processed.append(item)
    return processed

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
