def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate `commands`
    if commands is None:
        raise ValueError("`commands` must not be None")
    if isinstance(commands, str):
        import shlex
        try:
            cmd_parts = shlex.split(commands)
        except Exception as e:
            raise ValueError(f"Unable to parse command string: {e}") from e
    else:
        if not hasattr(commands, "__iter__"):
            raise TypeError("`commands` must be a string or an iterable of strings")
        try:
            cmd_parts = [str(item) for item in commands]
        except Exception as e:
            raise TypeError("All elements in `commands` must be strings") from e
    if not cmd_parts:
        raise ValueError("`commands` cannot be empty")

    # Validate `args`
    if args is None:
        args_list = []
    else:
        if isinstance(args, str):
            args_list = [args]
        elif isinstance(args, (list, tuple)):
            try:
                args_list = [str(arg) for arg in args]
            except Exception as e:
                raise TypeError("All elements in `args` must be strings") from e
        else:
            raise TypeError("`args` must be None, a string, or an iterable of strings")
    # Build the final command
    full_cmd = cmd_parts + args_list

    # Inform about execution if verbose
    if verbose:
        print(f"Running command: {' '.join(full_cmd)}")
    # Prepare subprocess run arguments
    run_kwargs = {
        "cwd": cwd,
        "env": env,
        "text": True,
        "capture_output": True,
        "check": False,
    }
    try:
        result = subprocess.run(full_cmd, **run_kwargs)
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except PermissionError as e:
        raise RuntimeError(f"Permission denied while executing: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to execute command: {full_cmd}") from e

    # Handle output
    if verbose:
        if result.stdout:
            print("stdout:")
            print(result.stdout, end='')  # `result.stdout` already ends with newline
        if not hide_stderr and result.stderr:
            print("stderr:")
            print(result.stderr, end='')
    # Raise for non-zero exit code
    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=full_cmd,
            output=result.stdout,
            stderr=result.stderr
        )
    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        cmd = commands.split()
    else:
        try:
            cmd = list(commands)
        except Exception:
            raise TypeError("commands must be a string or an iterable of strings")
    if args:
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple of arguments")
        cmd.extend(args)

    if verbose:
        print(f"Running command: {' '.join(cmd)}")

    # Determine stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            stderr=stderr_target
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    except subprocess.SubprocessError as e:
        raise RuntimeError(f"Failed to execute command: {' '.join(cmd)}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error during command execution: {' '.join(cmd)}") from e

    if result.returncode != 0:
        err_output = result.stderr.strip() if result.stderr else ""
        raise RuntimeError(f"Command {' '.join(cmd)} failed with exit code {result.returncode}\nStderr: {err_output}")

