def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    # Normalize commands to a list
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")

    # Normalize args
    if args is None:
        arg_lists = [[] for _ in commands]
    elif isinstance(args, (list, tuple)):
        # If args is a list of argument lists per command
        if all(isinstance(a, (list, tuple)) for a in args):
            if len(args) != len(commands):
                raise ValueError("Length of args list must match number of commands.")
            arg_lists = args
        else:
            # single argument list applied to all commands
            arg_lists = [args] * len(commands)
    else:
        # Single argument applied to all commands
        arg_lists = [[args]] * len(commands)

    results = []
    for cmd, arg_list in zip(commands, arg_lists):
        # Build full command; support list or string
        if isinstance(cmd, (list, tuple)):
            full_cmd = list(cmd) + list(arg_list)
        else:
            full_cmd = [cmd] + list(arg_list)

        if verbose:
            print(f"Running: {' '.join(full_cmd)}")

        stderr_option = subprocess.DEVNULL if hide_stderr else None

        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                capture_output=True,
                text=True,
                stderr=stderr_option,
                check=True
            )
        except subprocess.CalledProcessError as e:
            # If stderr was hidden, clear the stored stderr for clarity
            if hide_stderr:
                e.stderr = ''
            raise

        results.append(result)

    return results[0] if len(results) == 1 else results

