def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is not None and callable(dumper):
            result = dumper(obj)
        else:
            result = yaml.safe_dump(obj, default_flow_style=False, allow_unicode=True)
    except Exception as exc:
        raise ValueError(f"Failed to dump object: {exc}") from exc
    # Ensure the result is a string type (unicode in Py2, str in Py3)
    if isinstance(result, bytes):
        try:
            result = result.decode("utf-8")
        except Exception:
            # fall back to the original bytes if decoding fails
            pass
    if not isinstance(result, str):
        # In old Python versions result might be 'str' which is a byte string
        try:
            result = str(result)
        except Exception:
            pass
    return result

