def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or int
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate and normalise inputs
    try:
        # Process shape
        if isinstance(shape, int):
            shape = (shape,)
        elif isinstance(shape, (tuple, list)):
            shape = tuple(shape)
        else:
            raise TypeError("shape must be an int, tuple, or list")

        if not all(isinstance(dim, int) and dim >= 0 for dim in shape):
            raise ValueError("All dimensions in shape must be non-negative integers")

        # Validate dtype
        dtype = np.dtype(dtype)
    except Exception as exc:
        raise ValueError(f"Invalid input for make_array: {exc}") from exc

    # Create the array
    try:
        return np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array: {exc}") from exc

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate and normalize the shape argument
    if isinstance(shape, (int, np.integer)):
        shape_tuple = (int(shape),)
    elif isinstance(shape, (list, tuple)):
        try:
            shape_tuple = tuple(int(dim) for dim in shape)
        except Exception as exc:
            raise TypeError(f"All dimensions in shape must be integers, got {shape}") from exc
    else:
        raise TypeError(f"Shape must be an int or an iterable of ints, got {type(shape).__name__}")

    # Ensure dimensions are non‑negative (zero‑dimensional arrays allowed)
    for dim in shape_tuple:
        if dim < 0:
            raise ValueError(f"Shape dimensions must be non‑negative, got {shape_tuple}")

    # Normalise dtype
    if not isinstance(dtype, np.dtype):
        try:
            dtype = np.dtype(dtype)
        except Exception as exc:
            raise TypeError(f"dtype must be a valid numpy dtype, got {dtype}") from exc

    # Allocate the array, handling potential errors
    try:
        return np.empty(shape_tuple, dtype=dtype)
    except MemoryError as exc:
        raise MemoryError(f"Unable to allocate array of shape {shape_tuple} with dtype {dtype}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to create array: {exc}") from exc

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if not isinstance(shape, (tuple, list)):
        raise TypeError(f"shape must be a tuple or list of integers, got {type(shape).__name__}")
    try:
        # Ensure all dimensions are integers and non-negative
        dims = tuple(int(d) for d in shape)
    except (ValueError, TypeError):
        raise ValueError(f"shape must contain integers, got {shape}")
    if any(d < 0 for d in dims):
        raise ValueError(f"shape dimensions must be non-negative, got {shape}")

    # Validate dtype
    try:
        np_dtype = np.dtype(dtype)
    except TypeError:
        raise TypeError(f"dtype must be a valid NumPy dtype or convertible, got {dtype}")

    try:
        # Create the array; using empty to avoid zeroing data if not required
        return np.empty(dims, dtype=np_dtype)
    except Exception as e:
        raise RuntimeError(f"Could not create array with shape {shape} and dtype {dtype}: {e}")

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception:
        raise TypeError("Input must be convertible to float or array-like of floats.")
    mu = 0.2
    sigma = 0.1
    try:
        norm_factor = 1.0 / (sigma * np.sqrt(2 * np.pi))
        exponent = -((x_arr - mu) ** 2) / (2 * sigma ** 2)
        return norm_factor * np.exp(exponent)
    except FloatingPointError:
        raise OverflowError("Numerical under/overflow encountered.")

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x, dtype=np.float64)
    except Exception as e:
        raise TypeError(f"Input x must be convertible to a numeric array. Error: {e}")
    mean = 0.2
    sigma = 0.1
    exponent = -((x_arr - mean) ** 2) / (2 * sigma ** 2)
    return np.exp(exponent)

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        # Convert input to a NumPy array for vectorized computation
        x_arr = np.asarray(x)
        # Compute the Gaussian function
        return np.exp(-((x_arr - 0.2) ** 2) / (2 * (0.1 ** 2)))
    except Exception as exc:
        raise ValueError(f"Invalid input to gaussian: {exc}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import re
    import logging
    from configparser import ConfigParser, NoSectionError, NoOptionError

    logger = logging.getLogger(__name__)
    parsed_configs = {}
    error_records = []

    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def _replace_env(value):
        def repl(match):
            return os.getenv(match.group(1), match.group(0))
        return env_pattern.sub(repl, value)

    for filename in config_filenames:
        try:
            parser = ConfigParser()
            parser.read(filename)
            config_dict = {section: dict(parser.items(section)) for section in parser.sections()}

            if resolve_env:
                for section, options in config_dict.items():
                    for key, val in options.items():
                        config_dict[section][key] = _replace_env(val)

            if overrides and isinstance(overrides, dict):
                file_overrides = overrides.get(filename, {})
                if isinstance(file_overrides, dict):
                    for section, opts in file_overrides.items():
                        if section not in config_dict:
                            config_dict[section] = {}
                        for key, val in opts.items():
                            config_dict[section][key] = val

            parsed_configs[filename] = config_dict
        except Exception as exc:
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                pathname=__file__ if '__file__' in globals() else filename,
                lineno=0,
                msg=f"Failed to load configuration '{filename}': {exc}",
                args=(),
                exc_info=True
            )
            error_records.append(record)

    return parsed_configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import sys
    import logging

    results = {}
    errors = []

    def _resolve_env_vars(value):
        """Recursively resolve environment variables in a configuration value."""
        if isinstance(value, dict):
            return {k: _resolve_env_vars(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_resolve_env_vars(item) for item in value]
        if isinstance(value, str):
            # Replace ${VAR} or $VAR patterns with environment values.
            import re
            pattern = re.compile(r'\$(?:\{([^}]+)\}|([A-Za-z0-9_]+))')
            def repl(match):
                var_name = match.group(1) or match.group(2)
                return os.getenv(var_name, match.group(0))
            return pattern.sub(repl, value)
        return value

    for filename in config_filenames:
        try:
            # Ensure we have a string path
            path = str(filename) if not isinstance(filename, str) else filename
            with open(path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if resolve_env:
                data = _resolve_env_vars(data)
            if overrides and isinstance(data, dict):
                data.update(overrides)
            results[filename] = data
        except Exception as e:
            exc_info = sys.exc_info()
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to load {filename}: {e}',
                args=(),
                exc_info=exc_info
            )
            errors.append(record)

    return results, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    logger = logging.getLogger(__name__)
    results = {}
    error_records = []
    # Helper to resolve environment variables in a data structure
    def _resolve_env(value):
        try:
            import os
            import re
            if isinstance(value, dict):
                return {k: _resolve_env(v) for k, v in value.items()}
            if isinstance(value, list):
                return [_resolve_env(v) for v in value]
            if isinstance(value, str):
                pattern = r'\$\{([^}]+)\}'
                def repl(match):
                    return os.environ.get(match.group(1), match.group(0))
                return re.sub(pattern, repl, value)
            return value
        except Exception as e:
            # If any error occurs during env resolution, record it and continue
            record = logger.makeRecord(
                logger.name,
                logging.ERROR,
                fn='',
                lno=0,
                msg='Error resolving environment variables: {0}'.format(e),
                args=None,
                exc_info=None
            )
            error_records.append(record)
            return value

    # Helper to create a LogRecord for an exception
    def _make_log_record(exc, filename):
        exc_type, exc_value, tb = exc.__class__, exc, exc.__traceback__
        record = logger.makeRecord(
            logger.name,
            logging.ERROR,
            fn=filename,
            lno=0,
            msg='Failed to load {0}: {1}'.format(filename, exc),
            args=None,
            exc_info=(exc_type, exc_value, tb)
        )
        return record

    # Ensure we have an iterable of filenames
    try:
        filenames = list(config_filenames)
    except Exception:
        # If config_filenames is not iterable, wrap it in a list
        filenames = [config_filenames]

    for fname in filenames:
        try:
            # Determine parser based on file extension
            ext = fname.rsplit('.', 1)[-1].lower()
            if ext == 'json':
                try:
                    import json
                    with open(fname, 'r', encoding='utf-8') as f:
                        data = json.load(f)
                except Exception as e:
                    error_records.append(_make_log_record(e, fname))
                    continue
            elif ext in ['ini', 'cfg']:
                try:
                    import configparser
                    parser = configparser.ConfigParser()
                    parser.read(fname)
                    data = {s: dict(parser[s]) for s in parser.sections()}
                except Exception as e:
                    error_records.append(_make_log_record(e, fname))
                    continue
            else:
                # Unsupported file type
                error_records.append(_make_log_record(
                    Exception('Unsupported configuration file extension: {0}'.format(ext)),
                    fname
                ))
                continue

            # Apply overrides if provided
            if overrides and isinstance(overrides, dict):
                if isinstance(data, dict):
                    data.update(overrides)
                else:
                    error_records.append(_make_log_record(
                        Exception('Overrides cannot be applied to non-dict config for file {0}'.format(fname)),
                        fname
                    ))

            # Resolve environment variables if requested
            if resolve_env:
                data = _resolve_env(data)

            results[fname] = data

        except Exception as e:
            error_records.append(_make_log_record(e, fname))

    return (results, error_records)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import re
    import logging

    def _replace_env(values):
        """Recursively replace ${VAR} placeholders in string values using os.environ."""
        try:
            import os
        except Exception:
            return values
        if isinstance(values, dict):
            return {k: _replace_env(v) for k, v in values.items()}
        if isinstance(values, list):
            return [_replace_env(v) for v in values]
        if isinstance(values, str):
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                return os.getenv(match.group(1), match.group(0))
            return pattern.sub(repl, values)
        return values

    configurations = {}
    error_records = []

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            try:
                parsed = json.loads(raw)
            except json.JSONDecodeError as e:
                raise ValueError(f'JSON parsing failed for {fname}: {e}')

            if not isinstance(parsed, dict):
                raise ValueError(f'Top-level object in {fname} is not a JSON object')

            if overrides:
                if not isinstance(overrides, dict):
                    raise ValueError('Overrides must be a dictionary')
                parsed.update(overrides)

            if resolve_env:
                parsed = _replace_env(parsed)

            configurations[fname] = parsed
        except Exception as exc:
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=None
            )
            error_records.append(record)

    return configurations, error_records

def from_ticks(cls, ticks, tz=None):
        """Create a time from ticks (nanoseconds since midnight).

        :param ticks: nanoseconds since midnight
        :type ticks: int
        :param tz: optional timezone
        :type tz: datetime.tzinfo

        :rtype: Time

        :raises ValueError: if ticks is out of bounds
            (0 <= ticks < 86400000000000)
        """
        if not isinstance(ticks, int):
            raise TypeError("ticks must be an integer")
        if ticks < 0 or ticks >= 86400000000000:
            raise ValueError("ticks must be in the range [0, 86400000000000)")
        # Compute components
        ns_per_second = 1_000_000_000
        total_seconds = ticks // ns_per_second
        nano_remainder = ticks % ns_per_second
        hour = total_seconds // 3600
        minute = (total_seconds % 3600) // 60
        second = total_seconds % 60
        microsecond = nano_remainder // 1000
        nanosecond = nano_remainder % 1000
        # Try instantiating with nanosecond support, fallback to without
        try:
            return cls(hour, minute, second, microsecond, nanosecond, tz)
        except TypeError:
            try:
                return cls(hour, minute, second, microsecond, tz)
            except TypeError:
                # Final fallback using keyword arguments
                kwargs = {
                    "hour": hour,
                    "minute": minute,
                    "second": second,
                    "microsecond": microsecond,
                    "tzinfo": tz,
                }
                # Include nanosecond if possible
                if hasattr(cls, "__init__") and "nanosecond" in cls.__init__.__code__.co_varnames:
                    kwargs["nanosecond"] = nanosecond
                return cls(**kwargs)

def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
