        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Retrieve the registry of protocol handlers defined on the class.
        # The registry is expected to be a dict mapping version tuples to handler classes.
        handlers = {}
        try:
            handlers = getattr(cls, "_protocol_handlers", {})
            if not isinstance(handlers, dict):
                # In case the attribute exists but is not a dict, ignore it.
                handlers = {}
        except Exception:
            # Any unforeseen error retrieving the registry leads to an empty result.
            handlers = {}

        if protocol_version is None:
            # Return a copy of all available handlers
            return dict(handlers)

        # Explicit version requested; validate type.
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )

        # Return a dictionary with the single requested handler if available.
        return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}}

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Retrieve the internal mapping of available handlers.  If the
        # class doesn't define one, start with an empty mapping.
        handlers = getattr(cls, "_available_protocol_handlers", {})

        if protocol_version is None:
            # Return a shallow copy to prevent accidental mutation.
            return dict(handlers)

        # Ensure that a protocol version, if supplied, is a tuple.
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                "protocol_version must be a tuple (e.g. (3, 5)) or None"
            )

        # Return a dictionary containing only the matching handler, if any.
        return (
            {protocol_version: handlers[protocol_version]}
            if protocol_version in handlers
            else {}
        )

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Basic validation
        if values is None:
            return cls()

        if not hasattr(values, "__iter__"):
            raise TypeError("values must be an iterable of strings")

        parsed = []

        # Detect if a Bookmark class is available in the current global scope
        bookmark_cls = globals().get("Bookmark", None)

        for raw in values:
            if not isinstance(raw, str):
                raise TypeError(f"Each bookmark value must be a string, got {type(raw).__name__}")

            # Attempt to parse using a dedicated Bookmark method if it exists
            try:
                if bookmark_cls and hasattr(bookmark_cls, "from_raw"):
                    bookmark = bookmark_cls.from_raw(raw)
                else:
                    # Fallback: try to split key and data by the first colon
                    if ":" in raw:
                        key, data = raw.split(":", 1)
                        key = key.strip()
                        data = data.strip()
                    else:
                        key, data = None, raw.strip()

                    # Create a simple tuple representation if Bookmark constructor is unknown
                    if bookmark_cls:
                        # Try common constructor signatures
                        try:
                            if key is not None:
                                bookmark = bookmark_cls(key, data)
                            else:
                                bookmark = bookmark_cls(data)
                        except Exception:
                            # If constructor fails, fall back to tuple
                            bookmark = (key, data)
                    else:
                        bookmark = (key, data)
            except Exception as exc:
                raise ValueError(f"Failed to parse bookmark '{raw}': {exc}") from exc

            parsed.append(bookmark)

        return cls(parsed)

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Basic validation of the input
    if values is None:
        raise ValueError("values cannot be None")
    if isinstance(values, (str, bytes)):
        raise TypeError("values must be an iterable of strings, not a single string")
    try:
        iter(values)
    except TypeError:
        raise TypeError(f"values must be iterable, got {type(values)!r}")
    # Ensure each element is a string
    for v in values:
        if not isinstance(v, str):
            raise TypeError(f"each bookmark value must be a string, got {type(v)!r}")

    # Try creating the Bookmarks instance directly with the values
    try:
        bookmarks = cls(values)
    except Exception:
        # Fall back to the no‑argument constructor
        try:
            bookmarks = cls()
        except Exception as e:
            raise RuntimeError("Failed to create Bookmarks instance") from e
        # Add each raw value individually, accounting for common container APIs
        for v in values:
            try:
                if hasattr(bookmarks, "add"):
                    bookmarks.add(v)
                elif hasattr(bookmarks, "extend"):
                    bookmarks.extend([v])
                elif hasattr(bookmarks, "__iadd__"):
                    bookmarks += [v]
                else:
                    # If the object has no known mutating method, store the raw
                    if not hasattr(bookmarks, "_raw_bookmarks"):
                        bookmarks._raw_bookmarks = []
                    bookmarks._raw_bookmarks.append(v)
            except Exception as e:
                raise RuntimeError(f"Failed to add bookmark {v!r}") from e

    return bookmarks

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

