    :type values: Iterable[str]
    :return: Bookmarks instance containing the decoded bookmarks
    :raises ValueError: If any value is not a string or contains non-ASCII characters
    :raises TypeError: If values is not iterable or cls cannot be instantiated
    """
    # Validate that values is an iterable
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError(f"'{values!r}' is not an iterable of strings") from None

    raw_list = []
    for idx, v in enumerate(iterator):
        if not isinstance(v, str):
            raise ValueError(f"Value at position {idx} is not a string: {v!r}")
        try:
            # Test ASCII encoding
            v.encode("ascii")
        except UnicodeEncodeError:
            raise ValueError(f"Non-ASCII characters found in bookmark at position {idx}: {v!r}")
        raw_list.append(v)

    # Attempt to create an instance of cls with the raw list
    try:
        return cls(raw_list)
    except Exception as exc:
        # Provide a clearer error message if construction fails
        raise TypeError(f"Failed to instantiate {cls.__name__} from raw values: {exc}") from None

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

