        try:
            return cls(raw_list)
        except Exception as exc:
            raise ValueError(f"Failed to create {cls.__name__} from raw values: {exc}") from exc

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Helper to detect empty sequences
    def _elem_type_from_seq(s):
        if isinstance(s, (str, bytes, bytearray)):
            # Characters in str are str, in bytes are int
            return int if isinstance(s, (bytes, bytearray)) else str
        # list, tuple, set, range
        if isinstance(s, (list, tuple, set, range)):
            return type(s[0]) if s else object
        # if it's a bytes-like read object
        if hasattr(s, "__len__") and isinstance(s, (bytes, bytearray)):
            return int
        # fallback
        return type(s)

    # Determine if seq itself is a sequence type that we can use directly
    if isinstance(seq, (str, bytes, bytearray, list, tuple, set, range)):
        seq_out = seq
    else:
        # seq is not a built-in sequence; try to read from a file-like object or convert iterable
        try:
            # If seq has a .read method, read from it
            if hasattr(seq, "read") and callable(seq.read):
                if bufsize is not None:
                    data = seq.read(bufsize)
                else:
                    data = seq.read()
                seq_out = data
            else:
                # Treat as iterable and collect into a list
                seq_out = list(seq)
        except Exception as exc:
            raise TypeError(f"Cannot derive a sequence from {seq!r}") from exc

    # Determine element type; if seq_out is empty, use object as a generic fallback
    try:
        elem_type = _elem_type_from_seq(seq_out)
    except Exception:
        elem_type = object

    return seq_out, elem_type

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise TypeError("Argument 'seq' must not be None")
    # Determine if seq is already a sequence type
    try:
        from collections.abc import Sequence
    except Exception:
        # If Sequence cannot be imported, fallback to basic types check
        Sequence = (list, tuple, str, bytes, bytearray)
    if isinstance(seq, Sequence):
        return seq, type(seq)
    # Otherwise treat it as an iterable and convert to a list
    try:
        if bufsize is None:
            seq_list = list(seq)
        else:
            import itertools
            seq_list = list(itertools.islice(seq, bufsize))
    except Exception as exc:
        raise TypeError(f"Argument 'seq' must be an iterable: {exc}") from exc
    return seq_list, type(seq_list)

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Handle None explicitly
    if seq is None:
        return [], list

    # Types that are considered already sequences
    seq_types = (list, tuple, str, bytes, bytearray, memoryview, set, frozenset, range)
    if isinstance(seq, seq_types):
        return seq, type(seq)

    # Try to obtain an iterator; if not possible, wrap in a list
    try:
        it = iter(seq)
    except TypeError:
        return [seq], list

    # Convert the iterator to a sequence
    try:
        if bufsize is None:
            # Consume the entire iterator
            new_seq = list(it)
        else:
            # Consume up to bufsize elements
            from itertools import islice
            new_seq = list(islice(it, bufsize))
    except Exception:
        # Fallback: manual iteration with a buffer limit if needed
        new_seq = []
        count = 0
        for item in it:
            new_seq.append(item)
            if bufsize is not None:
                count += 1
                if count >= bufsize:
                    break

    return new_seq, list

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Handle explicit None
    if seq is None:
        return (None, type(None))
    # Sequence types typically provide __len__ and __getitem__
    if hasattr(seq, "__len__") and hasattr(seq, "__getitem__"):
        return (seq, type(seq))
    # Otherwise, if it's iterable, convert it to a list (or limited slice if bufsize is given)
    try:
        from collections.abc import Iterable
    except Exception:
        raise ImportError("collections.abc.Iterable is not available")
    if isinstance(seq, Iterable):
        try:
            if bufsize is not None:
                import itertools
                seq_list = list(itertools.islice(seq, bufsize))
            else:
                seq_list = list(seq)
            return (seq_list, list)
        except Exception as exc:
            raise TypeError(f"Failed to convert object of type {type(seq).__name__} into a sequence: {exc}") from exc
    # If it is not iterable, raise an error
    raise TypeError(f"Object of type {type(seq).__name__} is not an iterable or valid sequence type.")

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Try to detect if input is already a sequence type
    try:
        from collections.abc import Sequence
        if isinstance(seq, Sequence) and not isinstance(seq, (str, bytes, bytearray)):
            return (seq, type(seq))
    except Exception:
        # ignore import errors, fall back to conversion below
        pass

    # If not a known sequence, try to convert to a list
    # Use bufsize to limit the conversion if required
    try:
        if bufsize is not None:
            import itertools
            seq_list = list(itertools.islice(seq, bufsize))
        else:
            seq_list = list(seq)
    except Exception:
        # seq was not iterable or conversion failed; return as-is
        return (seq, type(seq))
    return (seq_list, type(seq_list))

def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).  Note that after changing (filling)
    the histogram one must explicitly recompute the scale if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # ----- helpers -------------------------------------------------------
    def _compute_integral():
        """
        Compute the integral of the histogram.
        Assumes the histogram class provides an `integral()` method.
        Raises an exception if the integral cannot be computed.
        """
        if not hasattr(self, "integral"):
            raise AttributeError(
                "Histogram object has no method `integral` for computing its scale."
            )
        return float(self.integral())

    # ----- retrieve current scale ----------------------------------------
    if other is None:
        # Only query or recompute the scale
        if recompute or not hasattr(self, "_scale") or self._scale is None:
            try:
                self._scale = _compute_integral()
            except Exception as exc:
                # Ensure that an invalid scale value is not cached
                if hasattr(self, "_scale"):
                    del self._scale
                raise exc
        return self._scale

    # ----- rescaling ------------------------------------------------------
    # Validate `other`
    try:
        target_scale = float(other)
    except Exception as exc:
        raise TypeError("`other` must be a numeric value (int or float).") from exc

    # Retrieve current scale (recomputes if needed)
    current_scale = self.scale(recompute=recompute)

    # Check for zero scale
    if current_scale == 0:
        raise ValueError("Histogram with scale zero cannot be rescaled.")

    # Compute factor and apply it to each bin
    try:
        factor = target_scale / current_scale
        # Use the most common attribute names for bin contents;
        # fall back to any iterable attribute named 'bins' or 'contents'.
        for attr in ("bins", "contents", "data", "values"):
            if hasattr(self, attr):
                bin_contents = getattr(self, attr)
                # Support both list/tuple and other sequences.
                for i in range(len(bin_contents)):
                    bin_contents[i] = bin_contents[i] * factor
                # Set scale after successful rescaling
                self._scale = target_scale
                return self._scale
        # If no suitable attribute found, raise an error.
        raise AttributeError(
            "Cannot find bin content attribute for rescaling."
        )
    except Exception as exc:
        # Ensure no corrupted state is left
        if hasattr(self, "_scale"):
            del self._scale
        raise RuntimeError("Failed to rescale histogram.") from exc

def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Check that the graph has a scale attribute
    if not hasattr(self, "scale"):
        raise LenaValueError("Graph has no scale attribute.")
    current_scale = getattr(self, "scale", None)

    # Return current scale if no new value was provided
    if other is None:
        return current_scale

    # Validate the provided new scale
    if not isinstance(other, (int, float)):
        raise TypeError("The new scale must be a numeric value.")
    if current_scale is None or not isinstance(current_scale, (int, float)):
        raise LenaValueError("Current graph scale is unknown.")
    if current_scale == 0:
        raise LenaValueError("Current graph scale is zero and cannot be used for rescaling.")

    # Determine the scaling factor
    factor = other / current_scale

    # Store the new scale
    self.scale = other

    # Identify the last coordinate field
    fields = getattr(self, "fields", None)
    if fields is None:
        # Fallback: look for attributes ending with 'data'
        fields = []
        for attr in dir(self):
            if attr.endswith("data") and hasattr(self, attr):
                fields.append(attr[:-4])  # strip 'data'
        # If still empty, look for numeric attributes
        if not fields:
            for attr in dir(self):
                if isinstance(getattr(self, attr), (list, tuple)):
                    fields.append(attr)
    if not fields:
        raise LenaValueError("Graph has no coordinate fields to rescale.")
    last_field = fields[-1]

    # Rescale the data for the last field
    data_container = getattr(self, "data", None)
    if data_container is None and hasattr(self, last_field):
        # Some objects store fields directly
        try:
            new_val = getattr(self, last_field) * factor
            setattr(self, last_field, new_val)
        except Exception as exc:
            raise LenaValueError(f"Unable to rescale field '{last_field}'.") from exc
    elif isinstance(data_container, dict):
        if last_field not in data_container:
            raise LenaValueError(f"Field '{last_field}' not found in graph data.")
        try:
            data_container[last_field] = data_container[last_field] * factor
        except Exception as exc:
            # Fall back to list comprehension if multiplication fails
            try:
                data_container[last_field] = [v * factor for v in data_container[last_field]]
            except Exception as exc2:
                raise LenaValueError(f"Unable to rescale field '{last_field}'.") from exc2
    else:
        # Unknown data storage layout
        raise LenaValueError("Graph data layout is unsupported for rescaling.")

    # Rescale related errors if present
    errors_container = getattr(self, "errors", None)
    if isinstance(errors_container, dict) and last_field in errors_container:
        try:
            errors_container[last_field] = errors_container[last_field] * factor
        except Exception as exc:
            try:
                errors_container[last_field] = [e * factor for e in errors_container[last_field]]
            except Exception as exc2:
                raise LenaValueError(f"Unable to rescale errors for field '{last_field}'.") from exc2

    return None

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # If no argument is supplied, simply return current scale
        if other is None:
            return getattr(self, "scale", None)

        # Ensure the new scale is numeric
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value")

        # Check for known and non‑zero current scale
        current_scale = getattr(self, "scale", None)
        if current_scale in (None, 0):
            raise LenaValueError("Cannot rescale an unknown or zero scale")

        # Compute the conversion factor
        try:
            factor = other / current_scale
        except Exception as exc:
            raise RuntimeError("Failed to compute scale factor") from exc

        # Apply the new scale
        setattr(self, "scale", other)

        # Helper to find likely coordinate attributes
        def _coord_attrs():
            """Yield possible coordinate attribute names in the order they appear."""
            for name in ["x", "y", "z", "xx", "yy", "zz"]:
                if hasattr(self, name):
                    val = getattr(self, name)
                    if isinstance(val, (list, tuple)):
                        yield name

        coords = list(_coord_attrs())
        if not coords:
            return None  # nothing to rescale

        # Rescale only the last coordinate
        last_coord = coords[-1]
        try:
            vals = getattr(self, last_coord)
            if isinstance(vals, list):
                rescaled_vals = [float(v) * factor for v in vals]
                setattr(self, last_coord, rescaled_vals)
        except Exception:
            pass  # Silently ignore malformed data

        # Rescale the error for the same coordinate, if present
        err_name = f"{last_coord}_err"
        if hasattr(self, err_name):
            try:
                errs = getattr(self, err_name)
                if isinstance(errs, list):
                    rescaled_errs = [float(e) * factor for e in errs]
                    setattr(self, err_name, rescaled_errs)
            except Exception:
                pass  # Silently ignore malformed data

        return None

def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Helper: determine axis count
    try:
        n_axes = len(self.values[0]) if isinstance(self.values, (list, tuple)) and self.values else 0
    except Exception:
        n_axes = 0

    if other is None:
        # Return current scale
        return getattr(self, "_scale", 1.0)

    # Validate numeric
    if not isinstance(other, (int, float)):
        raise TypeError(f"Scale must be numeric, got {type(other).__name__}")

    # Current scale
    cur_scale = getattr(self, "_scale", None)
    if cur_scale is None:
        raise LenaValueError("Cannot rescale because the current scale is unknown.")
    if cur_scale == 0:
        raise LenaValueError("Cannot rescale because the current scale is zero.")

    # Compute scaling factor
    factor = other / cur_scale

    # Rescale the last coordinate in values
    if isinstance(self.values, (list, tuple)):
        for idx, row in enumerate(self.values):
            if isinstance(row, (list, tuple)) and len(row) == n_axes:
                try:
                    val = row[-1]
                    if isinstance(val, (int, float)):
                        row[-1] = val * factor
                except Exception:
                    pass  # ignore malformed rows

    # Rescale corresponding errors if present
    if hasattr(self, "errors") and isinstance(self.errors, (list, tuple)):
        for idx, err_row in enumerate(self.errors):
            if isinstance(err_row, (list, tuple)) and len(err_row) == n_axes:
                try:
                    err = err_row[-1]
                    if isinstance(err, (int, float)):
                        err_row[-1] = err * factor
                except Exception:
                    pass  # ignore malformed rows

    # Update stored scale
    self._scale = other
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a histogram-like object to a graph (list of dicts).

    Parameters
    ----------
    hist : object
        An object representing a histogram. It must expose the following:
          * A readable number of bins via ``nbins`` attribute or ``len(hist)``.
          * Methods ``get_bin_low_edge(i)``, ``get_bin_high_edge(i)`` (0‑based
            index) returning the left and right edges of bin *i*.
          * Method ``get_bin_content(i)``, or attribute ``bin_contents``.
          * Optional attribute ``scale``.
    make_value : callable, optional
        Function to transform a raw bin content into the graph's y value.
        It receives the raw content (or a tuple if the bin contains a
        namedtuple) and returns either a single number or an iterable of
        numbers. If None, the raw contents are used directly.
    get_coordinate : str, optional
        Specifies which bin edge to use for the graph's x coordinate.
        Options are ``"left"``, ``"right"``, and ``"middle"``.
    field_names : tuple of str, optional
        Names for fields of the graph. Its length must match the number of
        components of the result (x + y components). The first name is the
        x coordinate's name, the rest are for the y values.
    scale : bool or any, optional
        The scale to attach to the resulting graph. If ``True``, uses
        ``hist.scale`` if present. Otherwise uses the provided value.

    Returns
    -------
    list of dict
        Each element represents a point in the graph with keys given by
        ``field_names``.  Additionally, each dict contains a ``"scale"``
        key if a scale was supplied.

    Raises
    ------
    ValueError
        If input data is missing essential histogram attributes,
        if the number of field names is inconsistent,
        or if an unknown coordinate type is requested.
    """

    # ---- Helper to obtain bin counts ----
    try:
        n_bins = hist.nbins
    except AttributeError:
        try:
            n_bins = len(hist)
        except Exception as exc:
            raise ValueError("Cannot determine number of bins") from exc

    # ---- Helper to obtain bin edges ----
    def low_edge(i):
        if hasattr(hist, "get_bin_low_edge"):
            return hist.get_bin_low_edge(i)
        if hasattr(hist, "bin_edges"):
            return hist.bin_edges[i]
        raise ValueError("Histogram object has no method or attribute to provide low edges")

    def high_edge(i):
        if hasattr(hist, "get_bin_high_edge"):
            return hist.get_bin_high_edge(i)
        if hasattr(hist, "bin_edges"):
            return hist.bin_edges[i+1]
        raise ValueError("Histogram object has no method or attribute to provide high edges")

    # ---- Helper to get bin content ----
    def bin_content(i):
        if hasattr(hist, "get_bin_content"):
            return hist.get_bin_content(i)
        if hasattr(hist, "bin_contents"):
            return hist.bin_contents[i]
        # Some histograms may expose contents directly as an attribute
        if hasattr(hist, "contents"):
            return hist.contents[i]
        raise ValueError("Histogram object has no method or attribute to provide bin contents")

    # ---- Validate field names ----
    if not isinstance(field_names, (list, tuple)):
        raise ValueError("field_names must be a sequence")
    if len(field_names) < 2:
        raise ValueError("At least two field names (x and y) are required")
    y_dim = len(field_names) - 1

    # ---- Determine scale ----
    final_scale = None
    if scale is True:
        final_scale = getattr(hist, "scale", None)
    else:
        final_scale = scale

    # ---- Build graph points ----
    graph = []
    for i in range(n_bins):
        try:
            lo = low_edge(i)
            hi = high_edge(i)
        except Exception as e:
            raise ValueError(f"Could not obtain edges for bin {i}") from e

        if get_coordinate == "left":
            coord = lo
        elif get_coordinate == "right":
            coord = hi
        elif get_coordinate == "middle":
            coord = (lo + hi) / 2
        else:
            raise ValueError(f'Unknown get_coordinate "{get_coordinate}"')

        raw_val = bin_content(i)

        if make_value is None:
            value = raw_val
        else:
            try:
                value = make_value(raw_val)
            except Exception as e:
                raise ValueError(f"make_value failed for bin {i}") from e

        # Ensure value is iterable if multiple y components are expected
        if isinstance(value, (list, tuple)):
            val_seq = value
        else:
            val_seq = (value,)

        if len(val_seq) != y_dim:
            raise ValueError(
                f"Number of y values ({len(val_seq)}) does not match "
                f"field_names ({y_dim}) for bin {i}"
            )

        point = {field_names[0]: coord}
        for idx, v in enumerate(val_seq, start=1):
            point[field_names[idx]] = v
        if final_scale is not None:
            point["scale"] = final_scale
        graph.append(point)

    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a histogram object into a graph representation.

    Parameters
    ----------
    hist : object
        Histogram-like object which must provide an iterable of bins and
        optionally an ``edges`` attribute or individual ``left``/``right``/``center``
        attributes on each bin.
    make_value : callable, optional
        Function that accepts a bin and returns a numeric value or a tuple of
        numeric values.  If omitted the bin itself (or its ``content``/``value`` attribute)
        is used as the graph value.
    get_coordinate : {"left", "right", "middle"}, default "left"
        Which side of the bin to use as the graph x‑coordinate.
    field_names : tuple of str, default ("x", "y")
        Names of columns in the resulting graph.  The first name is used
        for the x‑coordinate; the remaining names are taken from the return
        value of ``make_value``.
    scale : bool or any, default None
        If ``True`` the graph inherits the histogram's scale.

    Returns
    -------
    list[dict]
        Graph points where each point is a mapping from field names to values.
    """

    # Helper to obtain bin content/value
    def _get_bin_value(b):
        if make_value is not None:
            return make_value(b)
        # Try to extract content
        try:
            return getattr(b, "content", getattr(b, "value", b))
        except Exception:
            return b

    # Determine edges if available
    edges = None
    for attr in ("edges", "edge", "xedges", "yedges"):
        try:
            edges = getattr(hist, attr)
            break
        except AttributeError:
            pass

    # Build graph points
    graph = []
    try:
        bins = list(hist)
    except TypeError:
        raise ValueError("hist must be iterable over bins")

    for idx, bin_ in enumerate(bins):
        # Determine bin coordinates
        left, right = None, None
        if hasattr(bin_, "left") and hasattr(bin_, "right"):
            left, right = bin_.left, bin_.right
        elif hasattr(bin_, "center"):
            left = right = bin_.center
        elif isinstance(bin_, (tuple, list)) and len(bin_) >= 3:
            left, right = bin_[0], bin_[1]
        elif edges is not None and idx < len(edges) - 1:
            left, right = edges[idx], edges[idx + 1]
        else:
            raise ValueError(f"Cannot determine coordinates for bin at index {idx}")

        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        elif get_coordinate == "middle":
            coord = (left + right) / 2
        else:
            raise ValueError(f"Invalid get_coordinate value: {get_coordinate!r}")

        # Get bin value(s)
        val = _get_bin_value(bin_)
        # Normalise to tuple
        if isinstance(val, (list, tuple)):
            vals = tuple(val)
        else:
            vals = (val,)

        # Sanity check field_names length
        if len(field_names) != 1 + len(vals):
            raise ValueError(
                "field_names length must be equal to 1 (coordinate) "
                "plus the number of values returned by make_value"
            )

        point = {field_names[0]: coord}
        for name, v in zip(field_names[1:], vals):
            point[name] = v
        graph.append(point)

    # Attach scale if requested (and graph object supports it)
    if scale is True:
        # Try to copy histogram's scale attribute if present
        if hasattr(hist, "scale"):
            graph_scale = getattr(hist, "scale")
        else:
            graph_scale = None
    else:
        graph_scale = scale

    # If graph is an object supporting scale attribute, attach it
    if hasattr(graph, "__setattr__"):
        try:
            setattr(graph, "scale", graph_scale)
        except Exception:
            pass

    return graph

