def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Collect error messages
    errors = []

    # Check that candidate provides the interface (unless tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"Candidate {candidate!r} does not claim to provide {iface!r}"
                )
        except Exception as exc:
            errors.append(f"Error checking providedBy: {exc!r}")

    # Helper to obtain signature using inspect via __import__
    _inspect = None
    try:
        _inspect = __import__('inspect')
    except Exception as exc:
        errors.append(f"Could not import inspect module for signature checks: {exc!r}")

    # Helper to compare signatures (very basic comparison)
    def _compare_signatures(name, iface_member, cand_member):
        if _inspect is None:
            return  # Skip
        try:
            iface_sig = _inspect.signature(iface_member)
            cand_sig = _inspect.signature(cand_member)
        except Exception:
            # Cannot obtain signature, skip comparison
            return
        # Very basic check: compare number of parameters and presence of *args/**kwargs
        iface_params = iface_sig.parameters
        cand_params = cand_sig.parameters
        # Remove the 'self' parameter if it exists in both (instance methods)
        def strip_self(params):
            if len(params) > 0:
                first = list(params.values())[0]
                if first.name == 'self' or first.kind == first.VAR_KEYWORD:
                    return tuple(params.values())[1:]
            return tuple(params.values())
        iface_params_strip = strip_self(iface_params)
        cand_params_strip = strip_self(cand_params)
        if len(iface_params_strip) != len(cand_params_strip):
            errors.append(
                f"Signature mismatch for method {name!r}: "
                f"expected {len(iface_params_strip)} args, got {len(cand_params_strip)} args"
            )

    # Determine required names from interface
    try:
        required_names = getattr(iface, '_required_names_', None)
        if required_names is None:
            required_names = getattr(iface, '__required_names__', [])
    except Exception as exc:
        # Fall back to empty list if interface does not expose required names
        required_names = []

    # Check each required name
    for name in required_names:
        try:
            cand_attr = getattr(candidate, name)
        except AttributeError:
            errors.append(f"Candidate {candidate!r} missing required member {name!r}")
            continue
        except Exception as exc:
            errors.append(f"Error accessing member {name!r} of candidate: {exc!r}")
            continue

        # If member is callable, check method existence and signature
        if callable(cand_attr):
            # Ensure interface has a corresponding method
            try:
                iface_member = getattr(iface, name, None)
            except Exception:
                iface_member = None
            if iface_member is None:
                # Interface did not declare method; treat as attribute
                continue
            # Compare signatures if possible
            _compare_signatures(name, iface_member, cand_attr)
        # If not callable, just ensure attribute exists (checked above)

    # Raise exception if errors present
    if errors:
        # If zope.interface.Invalid is available, use it; otherwise use generic Exception
        try:
            Invalid = __import__('zope.interface').Invalid
        except Exception:
            Invalid = Exception
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid(errors)

    # All checks passed
    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Import required exception type, falling back to generic Exception
    try:
        from zope.interface import Invalid
    except Exception:
        class Invalid(Exception):
            pass

    errors = []

    # Step 1: check that candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append("candidate does not claim to provide the interface")
        except Exception as e:
            errors.append(f"error checking providedBy: {e}")

    # Helper to get signature arg count (excluding self if present)
    def _arg_count(method):
        try:
            code = method.__code__
            # exclude 'self' parameter if apparent
            argcount = code.co_argcount
            varnames = code.co_varnames
            if argcount > 0 and varnames[0] == "self":
                return argcount - 1
            return argcount
        except Exception:
            # if we cannot introspect, assume mismatch
            return None

    # Retrieve required attributes and methods from the interface
    # Use introspection of interface namespace where attributes are defined as
    # zope.interface.Attribute instances for required attributes and plain
    # callables for required methods.
    req_attrs = set()
    req_methods = set()
    # Attempt to use public API if available
    if hasattr(iface, "getRequiredCustomAttributes"):
        try:
            req_attrs = set(iface.getRequiredCustomAttributes())
        except Exception:
            pass
    else:
        req_attrs = set(getattr(iface, "__required_attrs__", []))

    if hasattr(iface, "getRequiredCustomMethods"):
        try:
            req_methods = set(iface.getRequiredCustomMethods())
        except Exception:
            pass
    else:
        # Gather all names in iface namespace that are callables and do not
        # start with underscore
        for name, attr in iface.__dict__.items():
            if callable(attr) and not name.startswith("_"):
                req_methods.add(name)

    # Verify attributes
    for name in req_attrs:
        if not hasattr(candidate, name):
            errors.append(f"missing required attribute: {name!r}")

    # Verify methods
    for name in req_methods:
        cand_attr = getattr(candidate, name, None)
        iface_attr = getattr(iface, name, None)
        if cand_attr is None or not callable(cand_attr):
            errors.append(f"missing required method: {name!r}")
            continue
        if iface_attr is None or not callable(iface_attr):
            # Interface method missing - shouldn't happen
            continue
        # Compare signatures (argument count)
        cand_arg_count = _arg_count(cand_attr)
        iface_arg_count = _arg_count(iface_attr)
        if cand_arg_count is None or iface_arg_count is None:
            continue  # unable to compare; skip
        if cand_arg_count != iface_arg_count:
            errors.append(
                f"signature mismatch for {name!r}: "
                f"expected {iface_arg_count} arguments, got {cand_arg_count}"
            )

    # Raise appropriate errors
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid("Multiple verification errors: " + "; ".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.
    Returns True if all checks pass; otherwise raises zope.interface.Invalid.
    """
    errors = []

    # Check that candidate claims to provide the interface (unless tentative)
    try:
        if not tentative and not iface.providedBy(candidate):
            errors.append(f"Candidate {candidate!r} does not claim to provide {iface!r}")
    except Exception as exc:
        errors.append(f"Error checking providedBy: {exc!r}")

    # Helper to get the raw function from a method
    def _func_of_method(method):
        if hasattr(method, "__func__"):
            return method.__func__
        return method

    # Helper to estimate argument count (ignoring defaults, varargs)
    def _arg_count(fn):
        try:
            code = fn.__code__
            return code.co_argcount + code.co_kwonlyargcount
        except Exception:
            return None

    # Examine interface methods
    try:
        iface_methods = getattr(iface, "methods", {})
    except Exception:
        iface_methods = {}

    for name, iface_method in iface_methods.items():
        # Ensure the candidate has the method
        if not hasattr(candidate, name):
            errors.append(f"Missing method {name}")
            continue
        cand_method = getattr(candidate, name)
        if not callable(cand_method):
            errors.append(f"Attribute {name} is not callable")
            continue

        # Compare signatures (argument counts)
        iface_func = _func_of_method(iface_method)
        cand_func = _func_of_method(cand_method)
        iface_argc = _arg_count(iface_func)
        cand_argc = _arg_count(cand_func)
        if iface_argc is None or cand_argc is None:
            # If unable to determine, skip
            continue
        if iface_argc != cand_argc:
            errors.append(
                f"Method {name} has argument count {cand_argc} but interface expects {iface_argc}"
            )

    # Examine interface attributes
    try:
        iface_attrs = getattr(iface, "attributes", {})
    except Exception:
        iface_attrs = {}

    for name in iface_attrs:
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute {name}")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(candidate, iface, errors[0])
        else:
            raise zope.interface.Invalid(candidate, iface, "; ".join(errors))
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # First, validate that iface is a class or interface-like object
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or interface-like type, got %r" % iface)

    # Convert candidate to a class object for introspection
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)

    # Quick check: if candidate is already a subclass of iface
    try:
        if issubclass(candidate_cls, iface):
            return True
    except TypeError:
        # issubclass may raise if candidate_cls is not a class; ignore and continue
        pass

    # If iface is an Abstract Base Class, check that all abstract methods are implemented
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    if abstract_methods:
        missing = [name for name in abstract_methods if not hasattr(candidate_cls, name)]
        if missing:
            if tentative:
                return False
            raise TypeError(
                f"Candidate {candidate_cls.__name__} does not implement "
                f"abstract methods required by {iface.__name__}: {', '.join(missing)}"
            )
        return True

    # General heuristic: ensure candidate has all attributes that iface has
    # Exclude dunder methods to avoid false positives
    iface_attrs = [
        name for name in dir(iface)
        if not (name.startswith("__") and name.endswith("__"))
    ]

    missing_attrs = [name for name in iface_attrs if not hasattr(candidate, name)]
    if missing_attrs:
        if tentative:
            return False
        raise TypeError(
            f"Candidate {candidate_cls.__name__} is missing attributes required by {iface.__name__}: "
            f"{', '.join(missing_attrs)}"
        )

    # If we reach this point, candidate seems to satisfy iface
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if the candidate seems to satisfy the interface, otherwise raises a TypeError.
    """
    # Basic sanity checks
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a class, got {type(iface).__name__}")
    if candidate is None:
        raise TypeError(f"candidate cannot be None")
    # Resolve candidate class
    try:
        candidate_cls = candidate if isinstance(candidate, type) else type(candidate)
    except Exception as exc:  # pragma: no cover
        raise TypeError(f"unable to determine type of candidate: {exc}") from exc
    # If tentative, only check attribute presence
    try:
        if tentative:
            missing = []
            for name in dir(iface):
                # Skip special dunder attributes
                if name.startswith("__") and name.endswith("__"):
                    continue
                if not hasattr(candidate_cls, name):
                    missing.append(name)
            if missing:
                raise TypeError(f"{candidate_cls.__name__} missing required attributes: {', '.join(missing)}")
        else:
            # Strict: candidate must be a subclass of iface (or implement the interface)
            if not issubclass(candidate_cls, iface):
                raise TypeError(f"{candidate_cls.__name__} is not a subclass of {iface.__name__}")
    except Exception as exc:
        raise  # re‑raise any validation errors
    return True

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine the metaclass for a new type, given its bases and an
    optional explicit metaclass argument.  The algorithm follows the
    semantics of CPython: if an explicit metaclass is supplied, all
    bases must be compatible with it; otherwise find the most derived
    metaclass that is compatible with all bases.  Incompatible bases
    raise a TypeError.
    """
    # Basic validation
    try:
        base_list = tuple(bases)
    except TypeError as exc:
        raise TypeError("bases must be an iterable of types") from exc

    # Compute metaclasses of the bases
    base_metas = []
    for b in base_list:
        if not isinstance(b, type):
            raise TypeError(f"Base {b!r} is not a type")
        base_metas.append(type(b))

    # If an explicit metaclass is given, validate compatibility
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a type")
        for b, m in zip(base_list, base_metas):
            if not issubclass(m, explicit_mc):
                raise TypeError(
                    f"explicit metaclass {explicit_mc.__name__!r} is not a supertype "
                    f"of {b.__name__!r}'s metaclass {m.__name__!r}")
        return explicit_mc

    # No explicit metaclass – compute the most derived common metaclass
    # Start with the metaclass of the first base, or `type` if no bases.
    if not base_metas:
        return type

    selected_meta = base_metas[0]
    for m in base_metas[1:]:
        if issubclass(m, selected_meta):
            selected_meta = m
        elif not issubclass(selected_meta, m):
            # Conflict: neither metaclass is a subclass of the other
            raise TypeError(
                f"metaclass conflict: {selected_meta.__name__!r} and {m.__name__!r} are not compatible")
    return selected_meta

def pop(self, key, default=__marker):
    """
    Remove the specified key from the dictionary and return its value.
    If the key is not found:
        - return ``default`` if it has been supplied.
        - otherwise, raise a ``KeyError``.
    """
    # Check if ``default`` was omitted (sentinel value)
    if default is __marker:
        if key in self:
            return super().pop(key)
        raise KeyError(key)
    else:
        if key in self:
            return super().pop(key)
        return default

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    except Exception as exc:
        # Re-raise unexpected exceptions (e.g., unhashable type, etc.)
        raise
    try:
        del self[key]
    except Exception as exc:
        # If deletion fails, re-raise the exception
        raise
    return value

def popitem(self):
    """
    Remove and return the `(key, value)` pair least frequently used.
    """
    # Determine required attributes, raise informative errors if absent
    try:
        key_to_value = getattr(self, "_key_values")
        if not isinstance(key_to_value, dict):
            raise TypeError
    except Exception:
        raise AttributeError("The cache must have a `_key_values` dict attribute.")
    try:
        key_to_freq = getattr(self, "_key_freq")
        if not isinstance(key_to_freq, dict):
            raise TypeError
    except Exception:
        raise AttributeError("The cache must have a `_key_freq` dict attribute.")
    try:
        freq_to_keys = getattr(self, "_freq_keys")
        if not isinstance(freq_to_keys, dict):
            raise TypeError
    except Exception:
        raise AttributeError("The cache must have a `_freq_keys` dict attribute.")

    # Raise KeyError if cache is empty
    if not key_to_freq:
        raise KeyError("Attempted to popitem from an empty LFU cache")

    # Identify the current minimum frequency
    min_freq = getattr(self, "_min_freq", None)
    if min_freq is None or min_freq not in freq_to_keys:
        # Fallback: compute it from the frequency map
        min_freq = min(key_to_freq.values())
    # Grab the OrderedDict corresponding to the minimum frequency
    keys_at_min = freq_to_keys.get(min_freq)
    if not keys_at_min:
        # Inconsistent state: recompute
        min_freq = min(key_to_freq.values())
        keys_at_min = freq_to_keys.get(min_freq)
        if not keys_at_min:
            raise RuntimeError("LFU cache frequency state is corrupted")

    # Get the least recently used key from the keys_at_min OrderedDict
    # (in Python 3.7+, dict preserves insertion order)
    key = next(iter(keys_at_min))
    value = key_to_value.pop(key, None)

    # Remove key from frequency mappings
    key_to_freq.pop(key, None)
    keys_at_min.pop(key, None)

