            if len(dclean) == 4:
                year = int(dclean)
                month, day = 1, 1
            elif len(dclean) == 6:
                year = int(dclean[:4])
                month = int(dclean[4:6])
                day = 1
            elif len(dclean) == 8:
                year = int(dclean[:4])
                month = int(dclean[4:6])
                day = int(dclean[6:8])
            else:
                raise ValueError
        except Exception:
            raise ValueError(f"Unsupported date format: {date_str}")

