    if dt is None:
        raise TypeError("dt must be a datetime instance")
    if not hasattr(dt, "tzinfo"):
        raise TypeError("dt must have a tzinfo attribute")
    if tzinfo is not None and not hasattr(tzinfo, "utcoffset"):
        raise TypeError("tzinfo must be a datetime.tzinfo instance or None")

    # Determine whether dt is naive. A naive datetime has no offset.
    try:
        offset = dt.tzinfo.utcoffset(dt)
    except Exception:
        offset = None

    # If dt is already aware, return it unchanged. Otherwise attach tzinfo.
    if offset is None:
        try:
            return dt.replace(tzinfo=tzinfo)
        except Exception as exc:
            raise ValueError(f"Failed to attach tzinfo to datetime: {exc}") from exc
    else:
        return dt

