    def _looks_like_legacy(req):
        # Legacy payloads might be url‑encoded form data or plain XML
        try:
            # Check form data
            form = {}
            if hasattr(req, "form"):
                # For async frameworks form might be async iterator
                try:
                    if hasattr(req.form, "__iter__"):
                        for k, v in req.form:
                            form[k] = v
                    else:  # sync mapping
                        form = dict(req.form)
                except Exception:
                    pass
            if form and ("content" in form or "message" in form):
                return True

            # Check body for XML or old JSON without the expected keys
            body = None
            if hasattr(req, "body"):
                body = req.body
            if body is None:
                if hasattr(req, "text"):
                    body = req.text
            if isinstance(body, bytes):
                body = body.decode(errors="ignore")
            if isinstance(body, str):
                body = body.strip()
                if body.lower().startswith("<"):
                    return True  # XML
                try:
                    import json
                    parsed = json.loads(body)
                    if isinstance(parsed, dict) and ("verb" not in parsed and "type" not in parsed):
                        return True
                except Exception:
                    pass
        except Exception:
            pass
        return False

    # Main detection logic
    try:
        payload = None
        if hasattr(request, "json"):
            try:
                payload = request.json()
            except Exception:
                pass
        if payload is None and hasattr(request, "body"):
            try:
                import json
                body = request.body
                if isinstance(body, bytes):
                    body = body.decode(errors="ignore")
                payload = json.loads(body)
            except Exception:
                pass

        if payload:
            if _looks_like_public(payload):
                return True
            if _looks_like_private(payload):
                return True

        if _looks_like_legacy(request):
            return True
    except Exception:
        # In case of any unexpected error, fall through to False
        pass

    return False

