    """
    Format a datetime in the way that D* nodes expect.

    The expected format is the ISO‑8601 UTC representation without
    separators, e.g. ``20231123T142530Z``.  The function accepts a
    :class:`datetime.datetime`, :class:`datetime.date`, timestamp (int/float)
    or a string that can be parsed by :func:`datetime.datetime.fromisoformat`
    or a few common ``strftime`` patterns.  If the input cannot be parsed
    a :class:`ValueError` is raised.

    Parameters
    ----------
    dt : datetime.datetime | datetime.date | int | float | str | None
        The date/time value to format.

    Returns
    -------
    str
        A string in the ``YYYYMMDDTHHMMSSZ`` format.
    """
    import datetime

    if dt is None:
        raise ValueError("None is not a valid datetime input")

    # Helper to convert to datetime and set UTC
    def to_utc_datetime(value):
        if isinstance(value, datetime.datetime):
            dt_obj = value
        elif isinstance(value, datetime.date):
            dt_obj = datetime.datetime.combine(value, datetime.time.min)
        elif isinstance(value, (int, float)):
            # Assume Unix timestamp in seconds
            dt_obj = datetime.datetime.fromtimestamp(value, tz=datetime.timezone.utc)
        else:
            raise TypeError(f"Unsupported type {type(value)!r}")
        # Ensure timezone-aware UTC datetime
        if dt_obj.tzinfo is None:
            dt_obj = dt_obj.replace(tzinfo=datetime.timezone.utc)
        else:
            dt_obj = dt_obj.astimezone(datetime.timezone.utc)
        return dt_obj

    # If already datetime/datetime.date or timestamp
    if isinstance(dt, (datetime.datetime, datetime.date, int, float)):
        try:
            utc_dt = to_utc_datetime(dt)
        except Exception as exc:
            raise ValueError(f"Failed to convert {dt!r} to UTC datetime: {exc}") from exc
    # If a string, attempt to parse
    elif isinstance(dt, str):
        parsed = None
        # Try ISO 8601
        try:
            parsed = datetime.datetime.fromisoformat(dt)
        except Exception:
            parsed = None
        # Try common strptime patterns
        if parsed is None:
            patterns = [
                "%Y-%m-%d %H:%M:%S",
                "%Y/%m/%d %H:%M:%S",
                "%Y-%m-%dT%H:%M:%S",
                "%Y%m%dT%H%M%S",
                "%Y%m%d %H%M%S",
                "%Y-%m-%d",
                "%Y%m%d",
            ]
            for p in patterns:
                try:
                    parsed = datetime.datetime.strptime(dt, p)
                    break
                except Exception:
                    continue
        if parsed is None:
            raise ValueError(f"String {dt!r} is not a recognized datetime representation")
        utc_dt = to_utc_datetime(parsed)
    else:
        raise TypeError(f"Unsupported input type {type(dt)!r}")

    # Format to expected string
    return utc_dt.strftime("%Y%m%dT%H%M%SZ")

