def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    try:
        import re

        # Split the text into parts separated by <a> tags (with their content)
        anchor_split_pattern = r'(<a\s+[^>]*>.*?</a>)'
        parts = re.split(anchor_split_pattern, text, flags=re.DOTALL)

        def process_anchor(anchor_str):
            # Find the part between <a ...> and </a>
            def repl(match):
                attrs = match.group(1)
                inner = match.group(2)

                # Add target and rel if missing
                if not re.search(r'\btarget\s*=', attrs):
                    attrs += ' target="_blank"'
                if not re.search(r'\brel\s*=', attrs):
                    attrs += ' rel="noopener noreferrer"'

                return f'<a{attrs}>{inner}</a>'

            anchor_pattern = r'<a\s+([^>]*?href=[\'"][^\'"]+[\'"][^>]*?)>(.*?)</a>'
            return re.sub(anchor_pattern, repl, anchor_str, flags=re.DOTALL)

        def linkify_text(text_chunk):
            url_pattern = r'\b(?:(?:https?://|www\.)[^\s<>"\']+)'
            def repl_url(match):
                url = match.group(0)
                href = url
                if url.startswith('www.'):
                    href = 'http://' + url
                return f'<a href="{href}">{url}</a>'
            return re.sub(url_pattern, repl_url, text_chunk)

        processed_parts = []
        for part in parts:
            if part and part.startswith('<a '):
                processed_parts.append(process_anchor(part))
            else:
                processed_parts.append(linkify_text(part))

        return ''.join(processed_parts)
    except Exception:
        return text

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.

    Returns the Content-Type header value if available, otherwise None.
    """
    try:
        import urllib.request
        from urllib.error import HTTPError, URLError

        if not isinstance(url, str) or not url:
            return None

        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except (ValueError, URLError, HTTPError, Exception):
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Ensure the input is a string
    if not isinstance(tag, str):
        return False

    # Remove leading/trailing whitespace
    tag = tag.strip()

    # Tag must not be empty
    if not tag:
        return False

    # Enforce a maximum length (commonly 30 characters for many tagging systems)
    if len(tag) > 30:
        return False

    # First character must be a letter (a-z or A-Z)
    first_char = tag[0]
    if not first_char.isalpha():
        return False

    # Allowed characters: alphanumerics, hyphen, underscore
    for ch in tag:
        if not (ch.isalnum() or ch in ("-", "_")):
            return False

    # Disallow a tag that consists solely of digits
    if tag.isdigit():
        return False

    return True

