    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, e.g. https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("The 'url' parameter must be a non-empty string.")
    lower_url = url.lower()
    if not (lower_url.startswith("http://") or lower_url.startswith("https://")):
        raise ValueError("The 'url' must start with http:// or https://.")

    # Prepare the base part without a trailing slash
    base = url.rstrip("/")

    # Determine the NodeInfo document path
    if document_path is None:
        path = "/nodeinfo/1.0"
    else:
        if not isinstance(document_path, str):
            raise ValueError("The 'document_path' must be a string if provided.")
        path = document_path
        if not path.startswith("/"):
            path = "/" + path

    # Construct the full href
    href = base + path

    # Build the well-known document
    well_known = {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }
    return well_known

