def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic input validation
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    url = url.strip()
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")

    # Use default document path if none provided
    path = "nodeinfo" if document_path is None else str(document_path).strip()
    if path.startswith("/"):
        path = path[1:]
    if path.endswith("/"):
        path = path[:-1]
    if not path:
        raise ValueError("document_path cannot be empty")

    # Construct base URL without trailing slash
    base = url.rstrip("/")

    # NodeInfo schema versions to expose
    versions = ["2.0", "2.1"]
    links = []
    for ver in versions:
        href = f"{base}/{path}/{ver}"
        links.append(
            {
                "rel": f"http://nodeinfo.diaspora.software/ns/schema/{ver}",
                "href": href,
            }
        )

    return {"links": links}

