def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    Returns a dictionary with keys:
        - subject (str, if present)
        - aliases (list of str, if any)
        - types (list of str, if any)
        - links (list of dict, each with 'rel', 'href', 'type' and any additional attributes)
    """
    # Attempt JSON parsing first
    try:
        import json  # imported lazily to comply with no import at top-level
        data = json.loads(document)
        if isinstance(data, dict):
            # Ensure lists for aliases and links if missing
            data.setdefault('aliases', [])
            data.setdefault('links', [])
            return data
        else:
            raise ValueError("JSON content is not an object")
    except Exception:
        pass  # fall through to XRD parsing

    # XRD parsing fallback
    try:
        import xml.etree.ElementTree as ET
    except Exception:
        raise ImportError("xml.etree.ElementTree is required for XRD parsing")

    def _local_name(tag: str) -> str:
        return tag.split("}")[-1] if "}" in tag else tag

    try:
        root = ET.fromstring(document)
    except Exception as exc:
        raise ValueError(f"Failed to parse Diaspora webfinger: {exc}")

    subject = None
    aliases: list = []
    types: list = []
    links: list = []

    # Helper to get text safely
    def _text(elem: ET.Element) -> str | None:
        return elem.text.strip() if elem is not None and elem.text else None

    # Iterate over all elements in tree
    for elem in root.iter():
        tag = _local_name(elem.tag)
        if tag == "Subject":
            subject = _text(elem)
        elif tag == "Alias":
            alias = _text(elem)
            if alias:
                aliases.append(alias)
        elif tag == "Types":
            types_text = _text(elem)
            if types_text:
                # Types element may contain multiple space-separated types
                types.extend(types_text.split())
        elif tag == "Link":
            # Capture attributes of Link element
            link_dict: Dict[str, str | None] = {k: v for k, v in elem.attrib.items()}
            # Ensure essential keys are present as None if missing
            for key in ("rel", "href", "type"):
                link_dict.setdefault(key, None)
            links.append(link_dict)

    output: Dict[str, Any] = {}
    if subject:
        output["subject"] = subject
    if aliases:
        output["aliases"] = aliases
    if types:
        output["types"] = types
    if links:
        output["links"] = links
    return output

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except Exception:
        # Not JSON, fall back to XRD parsing
        pass

    # Parse as XRD XML
    try:
        import xml.etree.ElementTree as ET

        def strip_ns(tag: str) -> str:
            return tag.split("}")[-1] if "}" in tag else tag

        root = ET.fromstring(document)

        result: Dict = {}

        # Helper to find first element by tag ignoring namespace
        def find_first(tag_name: str):
            for elem in root.iter():
                if strip_ns(elem.tag) == tag_name:
                    return elem
            return None

        # Subject
        subject_elem = find_first("Subject")
        if subject_elem is not None and subject_elem.text:
            result["subject"] = subject_elem.text.strip()

        # Links
        links = []
        for link_elem in root.iter():
            if strip_ns(link_elem.tag) == "Link":
                rel = link_elem.attrib.get("rel")
                href = link_elem.attrib.get("href")
                if rel or href:
                    links.append({"rel": rel, "href": href})
        if links:
            result["links"] = links

        # PublicKey
        pk_elem = find_first("PublicKey")
        if pk_elem is not None and pk_elem.text:
            result["public_key"] = pk_elem.text.strip()

        return result
    except Exception:
        # If parsing fails, fall back to empty dict
        return {}

def parse_diaspora_webfinger(document: str):
