            break
    result['subject'] = subject

    # Aliases
    aliases = []
    for elem in root.iter():
        if strip_ns(elem.tag) == 'Alias' and elem.text:
            aliases.append(elem.text)
    result['aliases'] = aliases

    # Links
    links = []
    for link_elem in root.iter():
        if strip_ns(link_elem.tag) == 'Link':
            link_data: Dict = {}
            # Attributes of <Link>
            for attr_name, attr_value in link_elem.attrib.items():
                link_data[attr_name] = attr_value
            # Child elements of <Link> (Type, Href, Template, etc.)
            for child in link_elem:
