def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    from typing import Dict, Any
    import json
    import xml.etree.ElementTree as ET

    result: Dict[str, Any] = {}

    if not document or not isinstance(document, str):
        return result

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            result['subject'] = data.get('subject')
            links = data.get('links', [])
            if isinstance(links, list):
                processed_links = []
                for link in links:
                    if isinstance(link, dict):
                        link_obj = {
                            'rel': link.get('rel'),
                            'href': link.get('href')
                        }
                        if 'type' in link:
                            link_obj['type'] = link['type']
                        processed_links.append(link_obj)
                result['links'] = processed_links
        return result
    except json.JSONDecodeError:
        pass

    # Fallback to XRD (XML)
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        # Invalid document, return empty dict
        return result

    ns = {
        'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0',
        'xrd2': 'http://docs.oasis-open.org/ns/xri/xrd-1.0',
    }

    # Attempt to find Subject with namespace
    subject = root.findtext('xrd:Subject', namespaces=ns)
    if subject is None:
        subject = root.findtext('Subject')
    result['subject'] = subject

    links = []
    for link_el in root.findall('xrd:Link', namespaces=ns):
        attrib = link_el.attrib
        link_obj = {
            'rel': attrib.get('rel'),
            'href': attrib.get('href')
        }
        if 'type' in attrib:
            link_obj['type'] = attrib.get('type')
        links.append(link_obj)

    # If no namespaced links found, try without prefix
    if not links:
        for link_el in root.findall('Link'):
            attrib = link_el.attrib
            link_obj = {
                'rel': attrib.get('rel'),
                'href': attrib.get('href')
            }
            if 'type' in attrib:
                link_obj['type'] = attrib.get('type')
            links.append(link_obj)

    result['links'] = links

    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
