    try:
        # urllib.request and xml.etree.ElementTree are expected to be imported
        with urllib.request.urlopen(url, timeout=10) as response:
            # Ensure we got a 200 OK
            if response.getcode() != 200:
                raise RuntimeError(
                    f"HTTP error {response.getcode()} while retrieving host-meta from {host}"
                )
            content = response.read()
    except Exception as exc:
        raise RuntimeError(
            f"Unable to retrieve host-meta from {host}."
        ) from exc

    # Parse the XML into an ElementTree element (XRD instance)
    try:
        return xml.etree.ElementTree.fromstring(content)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to parse the host-meta XML for {host}."
        ) from exc

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Attempt to fetch the host-meta document.
    try:
        url = f"https://{host}/.well-known/xrd.xml"
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except Exception as exc:
        raise ValueError(f"Could not retrieve host-meta from {host}") from exc

    # Attempt to parse the response into an XRD instance.
    try:
        # Assuming the XRD module provides a parse() or from_string() class method.
        if hasattr(XRD, "parse"):
            return XRD.parse(response.content)
        elif hasattr(XRD, "from_string"):
            return XRD.from_string(response.content)
        else:
            # Fallback: return raw text if parsing utilities are unavailable.
            return response.content
    except Exception as exc:
        raise ValueError(f"Failed to parse host-meta for {host}") from exc

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Import requests inside the function to avoid global imports
    try:
        import requests
    except ImportError as ie:
        return None, ie

    # Validate URL
    if not isinstance(url, str):
        return None, TypeError("url must be a string")

    # Validate method
    if not isinstance(method, str):
        return None, TypeError("method must be a string")
    method_lower = method.lower()

    # Retrieve the request function (e.g., requests.post)
    request_func = getattr(requests, method_lower, None)
    if request_func is None or not callable(request_func):
        return None, ValueError(f"Unsupported HTTP method '{method}'")

    # Validate timeout
    try:
        timeout_val = float(timeout)
        if timeout_val <= 0:
            raise ValueError
    except Exception:
        return None, ValueError("timeout must be a positive number")

    # Prepare arguments for the request
    req_kwargs = {
        "timeout": timeout_val,
    }
    # Merge user-provided kwargs; user kwargs override defaults if needed
    req_kwargs.update(kwargs)

    # Set data appropriately
    # If data is a dict, let requests handle form encoding
    # If it's bytes or file-like, pass as raw data
    try:
        if isinstance(data, dict) or data is None:
            req_kwargs["data"] = data
        else:
            # Assume bytes or file-like
            req_kwargs["data"] = data
    except Exception:
        return None, ValueError("data must be a dict, bytes, or file-like object")

    # Send the request with exception handling
    try:
        response = request_func(url, **req_kwargs)
        return response.status_code, None
    except Exception as e:
        return None, e

