def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1', 'key2')

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError(f"Expected dic to be dict, got {type(dic).__name__}")
    all_keys = [key] + list(keys)
    if not all_keys:
        raise ValueError("At least one key must be provided")
    if not all(isinstance(k, str) for k in all_keys):
        raise TypeError("All keys must be strings")
    current = dic
    try:
        for k in all_keys[:-1]:
            if k not in current:
                current[k] = {}
            elif not isinstance(current[k], dict):
                raise TypeError(f"Intermediate key '{k}' is not a dictionary")
            current = current[k]
        current[all_keys[-1]] = val
    except Exception as exc:
        raise RuntimeError(f"Failed to insert nested key {'.'.join(all_keys)}: {exc}") from exc
    return dic

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # Validate dictionary
    if not isinstance(dic, dict):
        raise TypeError(f"dic must be a dict, got {type(dic).__name__}")
    # Build the key chain
    chain = []
    # Helper to process a key element
    def _add_key(part):
        if isinstance(part, (list, tuple)):
            for sub in part:
                _add_key(sub)
        elif isinstance(part, str):
            chain.append(part)
        else:
            raise TypeError(f"Key parts must be str or iterable of str, got {type(part).__name__}")

    _add_key(key)
    for k in keys:
        _add_key(k)

    if not chain:
        # nothing to insert
        return dic

    current = dic
    # iterate through all but the last key
    for i, k in enumerate(chain[:-1]):
        if k in current:
            if isinstance(current[k], dict):
                current = current[k]
            else:
                # existing key is not a dict, cannot nest further
                raise ValueError(f"Cannot create nested key under '{'.'.join(chain[:i+1])}' because it is not a dict")
        else:
            # create a new nested dict
            current[k] = {}
            current = current[k]
    # set the final value
    current[chain[-1]] = val
    return dic

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file names found in the given directories that match the spec_option.

    Parameters
    ----------
    settings_dirs : list[str] | str
        One or more directory paths to search. If a single string is supplied it is treated as a
        single directory.
    spec_option : str | callable
        File name filter. If a string, it is interpreted as a file extension (case‐insensitive).
        If a callable, it is called with the file name and must return ``True`` for the name
        to be included. Other values are ignored and all files are included.

    Returns
    -------
    list[str]
        All file names that satisfy the filter. The list is flat (no directory prefix) and the
        order is undefined.

    Notes
    -----
    The function is tolerant of invalid inputs: non‑existent directories, non‑file entries,
    and errors during listing are silently skipped.  If the ``os`` module cannot be imported,
    a :class:`RuntimeError` is raised.
    """
    # We purposefully avoid a top‑level import; instead we lazy‑load os via __import__.
    try:
        os = __import__("os")
    except Exception as exc:
        raise RuntimeError("Unable to import 'os' module needed for file system access") from exc

    # Normalise settings_dirs to an iterable list of directory paths.
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    elif hasattr(settings_dirs, "__iter__"):
        dirs = list(settings_dirs)
    else:
        dirs = []

    result = []

    for dir_path in dirs:
        # Skip non‑string entries.
        if not isinstance(dir_path, (str, bytes)):
            continue

        # Only process existing directories.
        try:
            if not os.path.isdir(dir_path):
                continue
        except Exception:
            continue

        # List directory contents safely.
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue

                # Apply the spec_option filter.
                include = False
                if callable(spec_option):
                    try:
                        include = bool(spec_option(entry))
                    except Exception:
                        include = False
                elif isinstance(spec_option, (str, bytes)):
                    # Treat the string as a case‑insensitive file extension.
                    try:
                        include = entry.lower().endswith(spec_option.lower())
                    except Exception:
                        include = False
                else:
                    include = True

                if include:
                    result.append(entry)
        except Exception:
            # Any error listing this directory is ignored; continue with the next one.
            continue

    return result

def list_of_file_names(settings_dirs, spec_option=None):
    """Create a new IniType complex type"""
    # Ensure imports are available without global imports
    import os
    import fnmatch

    # Normalize settings_dirs to an iterable
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)

    result = []

    # Determine filter function based on spec_option
    if callable(spec_option):
        filter_func = spec_option
    elif isinstance(spec_option, str):
        pattern = spec_option
        def filter_func(name):
            return fnmatch.fnmatch(name, pattern)
    else:
        # No filtering
        def filter_func(name):
            return True

    for dir_path in dirs:
        try:
            # Check if path is a directory
            if not os.path.isdir(dir_path):
                continue
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                try:
                    if os.path.isfile(full_path) and filter_func(entry):
                        result.append(full_path)
                except OSError:
                    # Skip entries that cause errors (e.g., permissions)
                    continue
        except (OSError, PermissionError):
            # Skip directories that cannot be accessed
            continue

    # Sort for consistent ordering
    result.sort()
    return result

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    # Normalize input: ensure a list or tuple of directory paths
    if settings_dirs is None:
        return []
    if isinstance(settings_dirs, (str, bytes)):
        settings_dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple)):
        settings_dirs = list(settings_dirs)
    else:
        raise TypeError("settings_dirs must be a string or a list/tuple of strings")

    # Determine the file extension or pattern to filter on
    if spec_option is None:
        pattern = '.ini'
    elif isinstance(spec_option, str):
        pattern = spec_option if spec_option.startswith('.') else '.' + spec_option
    else:
        raise TypeError("spec_option must be a string representing a file extension")

    matched_files = []
    os_mod = __import__('os')
    for dir_path in settings_dirs:
        try:
            for entry in os_mod.listdir(dir_path):
                full_path = os_mod.path.join(dir_path, entry)
                if os_mod.path.isfile(full_path) and entry.endswith(pattern):
                    matched_files.append(full_path)
        except Exception:
            # Skip directories that cannot be accessed
            continue
    return matched_files

