def validate_from_content(cls, spec_content=None):
    """
    validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Ensure spec_content is provided
    if spec_content is None:
        raise IRValidatorException("spec_content cannot be None")

    # If it is not a string already loaded (e.g., dict), handle accordingly
    if isinstance(spec_content, dict):
        data = spec_content
    else:
        # Accept str (even bytes) but reject other types
        if not isinstance(spec_content, (str, bytes)):
            raise IRValidatorException(
                f"spec_content must be a str or dict, got {type(spec_content).__name__}"
            )
        if isinstance(spec_content, bytes):
            try:
                spec_content = spec_content.decode("utf-8")
            except Exception as exc:
                raise IRValidatorException(
                    f"Could not decode bytes content: {exc}"
                ) from exc
        # Parse YAML content safely
        try:
            # Import yaml lazily to avoid global import
            import yaml
            data = yaml.safe_load(spec_content)
        except ImportError as exc:
            raise IRValidatorException(
                "YAML parser 'yaml' is not available. Install pyyaml to parse spec content."
            ) from exc
        except Exception as exc:  # covers yaml.YAMLError and others
            raise IRValidatorException(f"Failed to parse YAML content: {exc}") from exc

    # Ensure parsed data is a mapping
    if not isinstance(data, dict):
        raise IRValidatorException(
            f"Spec content must resolve to a mapping, got {type(data).__name__}"
        )

    # Define required fields for the specification.
    # These can be adjusted based on actual spec requirements.
    REQUIRED_FIELDS = ("name", "description", "type")

    missing_fields = [fld for fld in REQUIRED_FIELDS if fld not in data]
    if missing_fields:
        raise IRValidatorException(
            f"Missing mandatory fields in spec: {', '.join(missing_fields)}"
        )

    return data

def validate_from_file(cls, yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields.

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file or file is invalid
    :return: Dictionary with data loaded from a YAML file
    """
    # Define required keys – adjust as needed for your schema
    REQUIRED_KEYS = {"name", "version", "settings"}

    # Import libraries inside the function to avoid module-level imports
    try:
        import os
        import yaml
    except Exception as exc:
        raise Exception(f"Required modules missing: {exc}") from exc

    if not yaml_file:
        raise TypeError("yaml_file must be a valid file path")

    if not os.path.isfile(yaml_file):
        raise FileNotFoundError(f"YAML file does not exist: {yaml_file}")

    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            content = f.read()
    except OSError as exc:
        raise TypeError(f"Could not read YAML file: {exc}") from exc

    try:
        data = yaml.safe_load(content)
    except yaml.YAMLError as exc:
        raise Exception(f"YAML parsing error: {exc}") from exc

    if not isinstance(data, dict):
        raise Exception(f"YAML root must be a mapping/object, got {type(data).__name__}")

    missing = REQUIRED_KEYS - data.keys()
    if missing:
        raise Exception(f"Missing required fields in YAML: {sorted(missing)}")

    return data

