        )

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    visited = set()

    def _resolve(node):
        if isinstance(node, dict):
            keys = list(node.keys())
            for key in keys:
                val = node[key]
                if key == "include" and isinstance(val, dict):
                    # Remove the include directive to prevent re-processing
                    node.pop(key)
                    for alias, path in val.items():
                        # Avoid circular includes
                        if alias in visited:
                            continue
                        visited.add(alias)
                        try:
                            with open(path, "r", encoding="utf-8") as fh:
                                if path.lower().endswith((".yaml", ".yml")):
                                    try:
                                        import yaml
                                    except Exception:
                                        raise RuntimeError(
                                            f"YAML parser not available for file: {path}"
                                        )
                                    included = yaml.safe_load(fh)
                                else:
                                    try:
                                        import json
                                    except Exception:
                                        raise RuntimeError(
                                            f"JSON parser not available for file: {path}"
                                        )
                                    included = json.load(fh)
                        except Exception as exc:
                            raise RuntimeError(f"Failed to include '{path}'") from exc

                        # Merge the included content into the current dict
                        node[alias] = _resolve(included)
                else:
                    _resolve(val)
        elif isinstance(node, list):
            for item in node:
                _resolve(item)
        return node

    return _resolve(parser_dict)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Retrieve spec from the instance; it can be named `spec`, `_spec`, or `default_spec`.
    spec = None
    for attr in ('spec', '_spec', 'default_spec'):
        if hasattr(self, attr):
            spec = getattr(self, attr)
            break
    if spec is None:
        # No spec attribute; nothing to resolve.
        return defaults
    # Ensure the spec is a mapping. It might be a dict, a list of tuples, or an object with .items.
    try:
        if isinstance(spec, dict):
            spec_items = spec.items()
        elif hasattr(spec, '__iter__') and not isinstance(spec, str):
            # Try to treat as iterable of key-value pairs.
            spec_items = spec
        else:
            raise TypeError(f"Unsupported spec type: {type(spec).__name__}")
    except Exception:
        # Unable to iterate over spec; return empty dict.
        return defaults

    for key, value in spec_items:
        # Skip non-string keys, as they likely don't represent argument names.
        if not isinstance(key, str):
            continue
        # Resolve default value:
        resolved_val = value
        # If the value is a callable, call it lazily.
        if callable(value):
            try:
                resolved_val = value()
            except Exception:
                # If callable raises, set default to None and continue.
                resolved_val = None
        # If the resolved value is a special sentinel, skip it.
        if resolved_val is None:
            continue
        defaults[key] = resolved_val
    return defaults

def get_spec_defaults(self):
    """
    Resolve argument defaults from the object's spec and other potential sources.
    Returns a dictionary mapping argument names to their default values.
    """
    defaults = {}
    try:
        # Attempt to gather defaults from the spec attribute if present
        spec = getattr(self, "spec", None)
        if isinstance(spec, dict):
            # Handle a 'parameters' list format
            for param in spec.get("parameters", []):
                if not isinstance(param, dict):
                    continue
                # Look for a name and a default value
                name = param.get("name") or param.get("property")
                if name and "default" in param:
                    defaults[name] = param["default"]

            # Handle a 'properties' dict format
            for key, value in spec.get("properties", {}).items():
                if isinstance(value, dict) and "default" in value:
                    defaults[key] = value["default"]

        # Merge additional defaults if the object provides a 'defaults' dictionary
        extra = getattr(self, "defaults", {})
        if isinstance(extra, dict):
            for key, value in extra.items():
                if key not in defaults:
                    defaults[key] = value

        # As a last resort, populate defaults from environment variables
        import os
        for key in set(defaults.keys()):
            if defaults[key] is None:
                env_val = os.getenv(key.upper())
                if env_val is not None:
                    defaults[key] = env_val

    except Exception:
        # In case of any unexpected issues, return what we have (possibly empty)
        pass

    return defaults

