def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Define a set of known deprecated keys. This could be overridden or extended elsewhere.
    DEPRECATED_KEYS = {
        "old_flag",
        "enable_legacy",
        "debug",
        "use_stubs",
        "legacy_mode",
    }

    # Helper to collect deprecated arguments from a dictionary
    def _collect_deprecated(arg_dict, source_name):
        deprecated = {}
        if not isinstance(arg_dict, dict):
            return deprecated
        for key, value in arg_dict.items():
            if key in DEPRECATED_KEYS:
                deprecated[key] = value
        return deprecated

    try:
        cli_deprecated = _collect_deprecated(cli_args, "CLI arguments")
        file_deprecated = _collect_deprecated(answer_file_args, "Answer file arguments")

        # Combine and report
        for source, d in [("CLI arguments", cli_deprecated), ("Answer file arguments", file_deprecated)]:
            for key, value in d.items():
                self.logger.warning(
                    f"The argument '{key}' in {source} is deprecated and may be removed in future releases. "
                    f"Consider using the updated option if available."
                )
        # Also check if the same deprecated argument appears in both sources
        for key in set(cli_deprecated).intersection(file_deprecated):
            self.logger.warning(
                f"Deprecated argument '{key}' is specified in both CLI and answer file. "
                "The CLI value will take precedence."
            )
    except Exception as exc:
        # If any unexpected error occurs, log it but do not interrupt validation flow
        self.logger.error(f"Error while validating deprecated arguments: {exc}")

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args: the dict of arguments from files
    """
    try:
        # Retrieve the deprecated arguments mapping from the instance
        deprecated_map = getattr(self, "deprecated_args", {})
        # Normalize deprecated map to dict if it was provided as a list
        if isinstance(deprecated_map, list):
            deprecated_map = {arg: None for arg in deprecated_map}
        # If the map is still not a dict, skip deprecation handling
        if not isinstance(deprecated_map, dict):
            return

        # Define source names for clearer messages
        sources = [("CLI", cli_args), ("Answer file", answer_file_args)]

        for source_name, arg_dict in sources:
            if not isinstance(arg_dict, dict):
                continue
            for deprecated_key, replacement in deprecated_map.items():
                if deprecated_key in arg_dict:
                    if replacement:
                        msg = (
                            f"Argument '{deprecated_key}' is deprecated "
                            f"and will be removed in a future release; "
                            f"please use '{replacement}' instead."
                        )
                    else:
                        msg = (
                            f"Argument '{deprecated_key}' is deprecated "
                            f"and will be removed in a future release."
                        )
                    print(f"{source_name} argument deprecation: {msg}")

    except Exception as exc:
        # In case of unexpected errors, print a concise message
        print(f"Error while validating deprecated arguments: {exc}")
    return None

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    Parameters
    ----------
    cli_args : dict
        Dictionary of arguments parsed from the command line.
    answer_file_args : dict
        Dictionary of arguments parsed from answer files.

    Raises
    ------
    TypeError
        If either `cli_args` or `answer_file_args` is not a dictionary.
    """
    # Basic input validation
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args should be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args should be a dict, got {type(answer_file_args).__name__}")

    # Retrieve the deprecated arguments mapping from the instance.
    # The mapping can be either an iterable of argument names or a dict mapping old names to new ones.
    deprecated = getattr(self, "_DEPRECATED_ARGS", None)
    if deprecated is None:
        return  # No deprecated arguments configured

    # If the mapping is a set/list/tuple, treat it as a list of names.
    if isinstance(deprecated, (list, tuple, set)):
        deprecated_map = {arg: None for arg in deprecated}
    elif isinstance(deprecated, dict):
        deprecated_map = deprecated
    else:
        raise TypeError(
            f"_DEPRECATED_ARGS should be a dict or iterable, got {type(deprecated).__name__}"
        )

    # Helper to check and warn
    def _warn_deprecated(arg_name, arg_source, source_dict):
        if arg_name in source_dict:
            new_name = deprecated_map.get(arg_name)
            if new_name:
                print(
                    f"Warning: Argument '{arg_name}' from {arg_source} is deprecated; "
                    f"please use '{new_name}' instead."
                )
            else:
                print(
                    f"Warning: Argument '{arg_name}' from {arg_source} is deprecated."
                )
            # Flag it in the dictionary to avoid double warnings if the same arg is seen twice.
            source_dict[arg_name] = f"__deprecated__"

    # Check CLI arguments
    for dep_arg in deprecated_map:
        _warn_deprecated(dep_arg, "CLI stream", cli_args)

    # Check answer file arguments
    for dep_arg in deprecated_map:
        _warn_deprecated(dep_arg, "answer file", answer_file_args)

