        try:
            # Some frameworks store options in a dict, e.g., self.command_options
            options_dict = getattr(self, "command_options", None)
            if isinstance(options_dict, dict):
                opts = options_dict.get(command_name)
                if isinstance(opts, list):
                    # Normalise each option to a dict for consistency
                    return [self._action_to_dict(a) for a in opts]
        except Exception:
            pass

        # 2. Attempt to extract from argparse subparsers if present
        try:
            subparsers_action = None
            # Access private _subparsers attribute if exists
            subparsers_obj = getattr(self, "parser", None)
            if subparsers_obj:
                # The subparsers action is usually stored in _subparsers
                subparsers = getattr(subparsers_obj, "_subparsers", None)
                if subparsers:
                    # subparsers._actions contains the _SubParsersAction
                    for action in getattr(subparsers, "_actions", []):
                        if isinstance(action, type(subparsers_obj.add_subparsers())):
                            subparsers_action = action
                            break
                if subparsers_action:
                    # Retrieve the specific subparser for the command: name -> parser
                    subparser = subparsers_action.choices.get(command_name)
                    if subparser:
                        # Convert all actions to a list of dicts
                        output = []
                        for action in getattr(subparser, "_actions", []):
                            # Skip help actions to avoid duplicates
                            if action.option_strings or action.dest == "help":
                                output.append(self._action_to_dict(action))
                        return output
        except Exception:
            pass

        # 3. Fallback: if the object itself has attributes named after the command
        try:
            cmd_obj = getattr(self, command_name, None)
            if cmd_obj:
                # If it has an 'add_arguments' or similar method, we can't introspect
                # Without knowledge, just return empty list
                return []
        except Exception:
            pass

        # If nothing found, return empty list
        return []

    def _action_to_dict(self, action):
        """Helper to convert an argparse action to a simple dict."""
        try:
            return {
                "dest": getattr(action, "dest", None),
                "option_strings": getattr(action, "option_strings", []),
                "help": getattr(action, "help", ""),
                "default": getattr(action, "default", None),
