    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Ensure that the parser has a command registry
    if not hasattr(self, "_commands"):
        raise AttributeError("This parser implementation does not expose a '_commands' attribute")

    # Retrieve the command object, if it exists
    try:
        cmd_obj = self._commands[command_name]
    except KeyError:
        raise KeyError(f"Command '{command_name}' not found in the parser's command registry")

    # Fetch the options from the command object
    if hasattr(cmd_obj, "options"):
        options = cmd_obj.options
    elif hasattr(cmd_obj, "get_option_specs") and callable(cmd_obj.get_option_specs):
        options = cmd_obj.get_option_specs()
    else:
        raise AttributeError(f"Command object for '{command_name}' does not expose options")

    # Normalize the options to a list
    if isinstance(options, (list, tuple)):
        return list(options)
