    return [options]

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command.

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    parser = getattr(self, "parser", None)
    if parser is None:
        raise AttributeError("The object does not have a 'parser' attribute")

    # Determine the target parser
    if command_name == "main":
        target_parser = parser
    else:
        # Try to find the subparser for the given command
        target_parser = None
        try:
            # The subparsers action is usually the first action that has a 'choices' attribute
            subparsers_action = next(
                (
                    action
                    for action in getattr(parser, "_subparsers", type("tmp", (), {"_actions": []}))._actions
                    if hasattr(action, "choices")
                ),
                None,
            )
            if subparsers_action and isinstance(subparsers_action, type(parser)):
                target_parser = subparsers_action.choices.get(command_name)
        except Exception:
            pass

        if target_parser is None:
            raise ValueError(f"Command '{command_name}' not found in the parser")

    # Gather options
    options = []
    for action in getattr(target_parser, "_actions", []):
        option_strings = getattr(action, "option_strings", [])
        # Only include options (i.e., actions that have at least one option string)
        if option_strings:
            options.append(
                {
                    "flags": option_strings,
                    "help": getattr(action, "help", None),
                }
            )

    return options

