            options = getattr(command_entry, 'args', None)  # fallback
        if options is None or not isinstance(options, dict):
            raise AttributeError(f"Command '{command_name}' has no options dictionary")

        # Fetch the option specification
        option_spec = options.get(argument_name)
        if option_spec is None:
            raise ValueError(f"Option '{argument_name}' not found for command '{command_name}'")

