def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Define a set of keywords that usually mark sensitive arguments
    _SILENT_KEYWORDS = {
        'password', 'pwd', 'secret', 'token',
        'key', 'api_key', 'api_token', 'secret_key'
    }

    silent_names = []

    try:
        # Support mapping or list/tuple of values
        if isinstance(args, dict):
            # Each key is an argument name
            for name in args:
                if isinstance(name, str) and any(k in name.lower() for k in _SILENT_KEYWORDS):
                    silent_names.append(name)
        elif isinstance(args, (list, tuple)):
            # Items can be simple names or (name, value) pairs
            for item in args:
                if isinstance(item, (list, tuple)) and len(item) > 0:
                    name = item[0]
                else:
                    name = item
                if isinstance(name, str) and any(k in name.lower() for k in _SILENT_KEYWORDS):
                    silent_names.append(name)
        else:
            # Unsupported type: return empty list
            return []

    except Exception:
        # In case of any unexpected error, return empty list to avoid crashes
        return []

    return silent_names

def get_silent_args(self, args):
    """
    Return the names of arguments that are considered 'silent'.

    In this implementation, an argument is considered silent if its key is a
    dictionary key that starts with a single underscore (e.g. `_foo`) and does not
    start with a double underscore. If the input is not a dictionary but an
    iterable of names, it is returned unchanged after validation.

    :param args: The received arguments. Expected to be a dict or an iterable
                 of argument names (strings).
    :return:   A list of argument names that are considered silent.
    """
    # Validate input
    if args is None:
        return []

    silent = []

    # Handle dictionary input
    if isinstance(args, dict):
        for key in args.keys():
            if isinstance(key, str) and key.startswith('_') and not key.startswith('__'):
                silent.append(key)

    # Handle iterable input (e.g., list, tuple, set)
    elif isinstance(args, (list, tuple, set)):
        for item in args:
            if isinstance(item, str):
                # No additional filtering; include all string names
                silent.append(item)

    else:
        raise TypeError("Unsupported type for args: expected dict or iterable of strings")

    # Ensure return type is a list
    return list(silent)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a dictionary-like object
    if args is None or not isinstance(args, dict):
        raise TypeError("args must be a dictionary representing the arguments.")
    # Retrieve the list or set of required argument names.
    # If the attribute does not exist or is not iterable, treat it as no requirements.
    required = getattr(self, "requires_args", None)
    if required is None:
        return
    # Ensure required is iterable
    try:
        iter(required)
    except TypeError:
        raise ValueError("requires_args attribute must be iterable (e.g., list or set).")
    # Identify missing arguments
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(map(str, missing))}")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the list of required argument names.
    required = getattr(self, "required_args", None) or getattr(self, "_required_args", None)
    if not required:
        # No required arguments defined; nothing to validate.
        return True

    # Normalize args to a dictionary.
    if args is None:
        args = {}
    elif not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception as exc:
            raise TypeError(f"args must be a mapping-like object; got {type(args).__name__}") from exc

    # Identify any missing keys or values that are considered "empty".
    missing = []
    for key in required:
        if key not in args:
            missing.append(key)
        else:
            val = args[key]
            # Consider None or an empty string as missing.
            if val is None or (isinstance(val, str) and val.strip() == ""):
                missing.append(key)

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    try:
        for opt in options_spec or []:
            name = opt.get('name')
            if not name:
                continue
            cond = opt.get('required_when')
            if not cond:
                continue
            # Normalise to a list of dictionaries
            conditions = cond if isinstance(cond, list) else [cond]
            matched = True
            for c in conditions:
                if isinstance(c, dict):
                    for key, val in c.items():
                        if isinstance(val, (list, tuple, set)):
                            if args.get(key) not in val:
                                matched = False
                                break
                        else:
                            if args.get(key) != val:
                                matched = False
                                break
                    if not matched:
                        break
                else:
                    # Unsupported condition format
                    matched = False
                    break
            if matched:
                required.append(name)
    except Exception:
        # In case of any unexpected error, return an empty list
        return []
    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Ensure we can look up values by key
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception:
            args = {}

    required = []
    for opt in options_spec or []:
        try:
            cond = opt.get('required_when')
            if not cond:
                continue

            matched = False
            # Handle dict or mapping conditions: all key/value pairs must match
            if isinstance(cond, dict):
                matched = all(args.get(k) == v for k, v in cond.items())
            elif isinstance(cond, (list, tuple)):
                # A list/tuple of (key, value) pairs
                matched = all(args.get(k) == v for k, v in cond)
            else:
                # Fallback: treat condition as a python expression string or callable
                try:
                    # If callable, call it with args
                    if callable(cond):
                        matched = bool(cond(args))
                    else:
                        # Safe eval with only 'args' in namespace
                        matched = bool(eval(cond, {}, {'args': args}))
                except Exception:
                    matched = False

            if matched:
                # Option name may be stored under 'name' or 'option_name'
                opt_name = opt.get('name') or opt.get('option_name')
                if opt_name:
                    required.append(opt_name)
        except Exception:
            # Skip broken specification entries
            continue
    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required_args = []
        if not isinstance(options_spec, (list, tuple)):
            return required_args

        # Normalize args to a dictionary for easier access
        if isinstance(args, dict):
            arg_dict = args
        else:
            # Attempt to convert to dict via keys-positions if possible
            try:
                arg_dict = {opt['name']: opt['value'] for opt in args}
            except Exception:
                arg_dict = {}

        for spec in options_spec:
            try:
                name = spec.get('name')
                condition = spec.get('required_when')
                if not name or condition is None:
                    continue

                matched = False
                # Callable condition
                if callable(condition):
                    try:
                        matched = bool(condition(arg_dict))
                    except Exception:
                        matched = False
                # String expression
                elif isinstance(condition, str):
                    try:
                        matched = bool(eval(condition, {}, arg_dict))
                    except Exception:
                        matched = False
                # List of option names (any present triggers)
                elif isinstance(condition, (list, tuple)):
                    matched = any(opt in arg_dict for opt in condition)
                # Dict of option names to expected values
                elif isinstance(condition, dict):
                    matched = all(
                        arg_dict.get(opt) == val for opt, val in condition.items()
                    )
                # Unsupported type: ignore
                if matched:
                    required_args.append(name)
            except Exception:
                # Skip any spec that causes unexpected errors
                continue

        return required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    try:
        conditionally_required = []

        # Helper to get the arg name from a spec entry
        def _get_name(opt):
            return opt.get('name') or opt.get('arg') or opt.get('option')

        # helper to assess a condition
        def _condition_met(cond):
            # boolean constants
            if isinstance(cond, bool):
                return cond
            # callables
            if hasattr(cond, '__call__'):
                try:
                    return bool(cond(args, command_name))
                except Exception:
                    return False
            # string expressions (try eval first, otherwise treat as a key)
            if isinstance(cond, str):
                try:
                    # eval in safe namespace
                    return bool(eval(cond, {}, {**args, 'command_name': command_name}))
                except Exception:
                    # if eval fails, interpret as key in args
                    return bool(args.get(cond))
            # iterable of conditions (any True)
            if isinstance(cond, (list, tuple, set)):
                return any(_condition_met(c) for c in cond)
            return False

        for opt in options_spec:
            if not isinstance(opt, dict):
                continue
            cond = opt.get('required_when')
            if cond is None:
                continue
            name = _get_name(opt)
            if not name:
                continue
            if _condition_met(cond):
                conditionally_required.append(name)

        return conditionally_required
    except Exception:
        # Return empty list if something goes wrong
        return []

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: A mapping of argument names to the values to be validated.
    """
    # Ensure we have a dictionary of arguments
    if not isinstance(args, dict):
        raise TypeError(f"'args' must be a dict, got {type(args).__name__}")

    # Retrieve per-argument max length definitions, if any.
    # Preference order: self.max_lengths dict, then individual class attributes like NAME_MAX_LENGTH, or a global MAX_LENGTH.
    max_lengths = getattr(self, "max_lengths", {}) or {}

    for arg_name, value in args.items():
        # Skip validation for None values
        if value is None:
            continue

        # Determine the maximum allowed length for this argument
        if isinstance(max_lengths, dict) and arg_name in max_lengths:
            max_len = max_lengths[arg_name]
        else:
            # Look for a class attribute that defines the max length (e.g., NAME_MAX_LENGTH)
            attr_name = f"{arg_name.upper()}_MAX_LENGTH"
            max_len = getattr(self, attr_name, None)

        # Fallback to a generic MAX_LENGTH attribute if specific one is not defined
        if max_len is None:
            max_len = getattr(self, "MAX_LENGTH", None)

        # If no max length is defined, skip this argument
        if max_len is None:
            continue

        try:
            length = len(value)
        except Exception as e:
            # If length cannot be determined, skip this argument; it might not be a string/sequence.
            continue

        if length > max_len:
            raise ValueError(
                f"Argument '{arg_name}' is too long: {length} > {max_len}"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments as a dictionary.
    :raises TypeError: If args is not a dictionary.
    :raises ValueError: If any argument value exceeds its declared maximum length.
    """
    if not isinstance(args, dict):
        raise TypeError("Expected args to be a dictionary.")

    # Optional custom maximum lengths per argument; defaults to 255.
    max_lengths = getattr(self, "max_lengths", {})

    for name, value in args.items():
        try:
            # Determine if the value is a length-eligible type
            if isinstance(value, (str, bytes, list, tuple, set, dict)):
                max_len = max_lengths.get(name, 255)
                if len(value) > max_len:
                    raise ValueError(
                        f"Argument '{name}' length "
                        f"({len(value)}) exceeds maximum allowed "
                        f"({max_len})."
                    )
        except TypeError:
            # Skip values that do not support len()
            continue

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure args is a dictionary
    if not isinstance(args, dict):
        raise ValueError(f"Arguments must be a dictionary, got {type(args).__name__}")

    # Required keys
    required_keys = {"value", "max_length"}
    missing = required_keys - args.keys()
    if missing:
        raise ValueError(f"Missing required keys in arguments: {', '.join(sorted(missing))}")

    value = args["value"]
    max_length = args["max_length"]

    # Validate max_length is an integer
    if not isinstance(max_length, int):
        raise ValueError(f"max_length must be an integer, got {type(max_length).__name__}")

    # Validate that value has a length
    try:
        length = len(value)
    except Exception as exc:
        raise ValueError(f"Provided value does not support len(): {type(value).__name__}") from exc

    if length > max_length:
        raise ValueError(f"Length of value ({length}) exceeds maximum allowed ({max_length})")

    # Optional: return True for clarity
    return True

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    The object is expected to have an attribute ``choices`` which is a mapping
    from an argument name to an iterable of valid values for that argument.

    Parameters
    ----------
    args : dict or object
        The received arguments.  If a ``dict`` is supplied, the values are
        retrieved via ``args[key]``.  For other objects, ``getattr`` is used.

    Raises
    ------
    ValueError
        If any argument value is not among the defined choices.
    """
    # Ensure we have a mapping of valid choices
    choices = getattr(self, "choices", None)
    if not isinstance(choices, dict):
        # Nothing to validate or invalid configuration
        return

    # Helper to fetch a value from args
    if isinstance(args, dict):
        def get_value(name):
            return args.get(name)
    else:
        def get_value(name):
            return getattr(args, name, None)

    for arg_name, valid_vals in choices.items():
        # Allow valid_vals to be any iterable; convert to a set for speed
        try:
            val_set = set(valid_vals)
        except TypeError:
            # If not iterable, treat as a single value
            val_set = {valid_vals}

        value = get_value(arg_name)

        # Skip missing or None values; other logic may handle required checks.
        if value is None:
            continue

        # If the passed value is a container (list/tuple/set) but not a string,
        # validate each element individually.
        if isinstance(value, (list, tuple, set)) and not isinstance(value, str):
            for elem in value:
                if elem not in val_set:
                    raise ValueError(
                        f"Invalid choice '{elem}' for argument '{arg_name}'. "
                        f"Allowed values: {sorted(val_set)}."
                    )
        else:
            if value not in val_set:
                raise ValueError(
                    f"Invalid choice '{value}' for argument '{arg_name}'. "
                    f"Allowed values: {sorted(val_set)}."
                )

def validate_choices_args(self, args):
        """
        Check if value of choice arguments is one of the available choices.

        :param args: The received arguments (dict of arg name to value).
        :raises ValueError: If an argument value is not within its defined choices.
        """
        # No args provided, nothing to validate
        if not args:
            return

        # Retrieve the mapping of allowable choices.
        # The parent class is expected to provide `self.choices` as a dict:
        #   {'arg_name': {'choice1', 'choice2', ...}}
        if not hasattr(self, 'choices') or not isinstance(self.choices, dict):
            raise AttributeError("The object must define a 'choices' dictionary mapping "
                                  "argument names to an iterable of accepted values.")

        for name, value in args.items():
            # Skip if the argument is not defined with choices
            if name not in self.choices:
                continue

            # Resolve the allowed set; make sure it is iterable
            try:
                allowed = set(self.choices[name])
            except TypeError:
                raise TypeError(f"Choices for argument '{name}' must be an iterable of allowed values.")

            # If the value is a collection (but not a string/bytes) handle each
            if isinstance(value, (list, tuple, set)):
                for v in value:
                    if v not in allowed:
                        raise ValueError(f"Invalid value '{v}' for argument '{name}'. "
                                         f"Expected one of {sorted(allowed)}.")
            else:
                # Single value validation
                if value not in allowed:
                    raise ValueError(f"Invalid value '{value}' for argument '{name}'. "
                                     f"Expected one of {sorted(allowed)}.")

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure args is a dictionary-like object
    if not isinstance(args, dict):
        raise TypeError(f"'args' must be a dict, got {type(args).__name__}")

    # If the instance has no defined choices, nothing to validate
    if not hasattr(self, 'choices') or not isinstance(self.choices, dict):
        return

    # Validate each provided argument against the allowed choices
    for key, value in args.items():
        if key in self.choices:
            allowed = self.choices[key]
            # Allow any iterable of allowed values
            try:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{key}': {value!r}. "
                        f"Allowed choices are: {allowed}"
                    )
            except TypeError:
                # In case 'allowed' is not iterable, raise a clear error
                raise ValueError(
                    f"Choices for argument '{key}' must be an iterable, got {type(allowed).__name__}"
                )

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        if not isinstance(args, dict):
            raise TypeError("`args` must be a dictionary of argument names to values.")
        # Retrieve the option that maps argument names to allowed values.
        choices = getattr(self, "choices", None)
        if choices is None:
            raise AttributeError("Instance does not have a 'choices' attribute.")
        for arg_name, arg_value in args.items():
            # Skip arguments that are not defined in the choice mapping.
            if arg_name not in choices:
                continue
            allowed = choices[arg_name]
            # Ensure the allowed collection is iterable; if not, treat as a single choice.
            try:
                if arg_value not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {arg_value}. "
                        f"Must be one of {list(allowed)}."
                    )
            except TypeError:
                # If allowed is not iterable (e.g., a single value), compare directly.
                if arg_value != allowed:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {arg_value}. "
                        f"Must be {allowed}."
                    ) from None

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.
    Each argument may be:
    - Already a numeric value, in which case the instance should provide
      generic ``self.min_value`` and ``self.max_value`` attributes.
    - A mapping containing a ``value`` key, and optional ``min`` and ``max`` keys.
    - If the argument is a dict mapping ``arg_name`` to such a mapping or a
      raw numeric value, the instance may provide per‑argument limits via
      ``<arg_name>_min`` and ``<arg_name>_max`` attributes.

    Parameters
    ----------
    args : Mapping or Sequence
        The arguments to validate.

    Raises
    ------
    ValueError
        If any argument value is missing, cannot be converted to a number,
        or is outside its allowed range.
    TypeError
        If *args* is not a mapping or sequence of the expected form.
    """
    # Helper to fetch per‑argument limits from the instance
    def _get_limits(name):
        min_attr = getattr(self, f"{name}_min", None)
        max_attr = getattr(self, f"{name}_max", None)
        return min_attr, max_attr

    # Helper to validate a single value against its limits
    def _check(name, value, min_val, max_val):
        try:
            num = float(value)
        except (TypeError, ValueError):
            raise ValueError(f"Argument '{name}' value {value!r} is not numeric")
        if min_val is not None and num < min_val:
            raise ValueError(
                f"Argument '{name}' value {num} < minimum {min_val}"
            )
        if max_val is not None and num > max_val:
            raise ValueError(
                f"Argument '{name}' value {num} > maximum {max_val}"
            )

    if args is None:
        raise ValueError("No arguments provided")

    # Accept dictionary: name -> value or name -> dict with 'value', 'min', 'max'
    if isinstance(args, dict):
        for name, val in args.items():
            if isinstance(val, dict):
                value = val.get("value")
                min_val = val.get("min")
                max_val = val.get("max")
            else:
                value = val
                # Use per‑argument limits if available, otherwise fall back to instance defaults
                min_val, max_val = _get_limits(name)
                if min_val is None:
                    min_val = getattr(self, "min_value", None)
                if max_val is None:
                    max_val = getattr(self, "max_value", None)
            if value is None:
                raise ValueError(f"Argument '{name}' value is missing")
            _check(name, value, min_val, max_val)

    # Accept sequence of items: each item can be a dict or a tuple/list
    elif isinstance(args, (list, tuple)):
        for item in args:
            if isinstance(item, dict):
                name = item.get("name")
                if name is None:
                    raise ValueError("Dictionary item missing 'name' key")
                value = item.get("value")
                min_val = item.get("min")
                max_val = item.get("max")
            elif isinstance(item, (list, tuple)):
                if len(item) < 4:
                    raise ValueError("Tuple/sequence item must have at least 4 elements: name, value, min, max")
                name, value, min_val, max_val = item[0], item[1], item[2], item[3]
            else:
                continue  # skip unsupported item types
            if value is None:
                raise ValueError(f"Argument '{name}' value is missing")
            _check(name, value, min_val, max_val)

    else:
        raise TypeError("Args must be a dict or a sequence (list/tuple)")

    # If we made it here all values are valid
    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Expected to be a dict containing
                 the keys 'value', 'min', and 'max'.
    :raises TypeError: If args is not a dict or values cannot be converted
                       to float.
    :raises ValueError: If any key is missing, if min > max, or if value
                        is outside the inclusive range [min, max].
    :return: True if value is within the specified range.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary containing 'value', 'min', and 'max' keys")

    # Retrieve values with informative error if any key is missing
    for key in ("value", "min", "max"):
        if key not in args:
            raise ValueError(f"Missing required key '{key}' in arguments")

    try:
        value = float(args["value"])
        minimum = float(args["min"])
        maximum = float(args["max"])
    except (TypeError, ValueError) as exc:
        raise TypeError("All of 'value', 'min', and 'max' must be convertible to float") from exc

    if minimum > maximum:
        raise ValueError("Minimum value cannot be greater than maximum value")

    if not (minimum <= value <= maximum):
        raise ValueError(
            f"Value {args['value']} is not between minimum {args['min']} and maximum {args['max']}"
        )

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if args is None:
        raise ValueError("No arguments provided to validate")
    # Determine if args is a mapping or a sequence
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        items = enumerate(args)
    else:
        raise TypeError(f"args must be a dict or list/tuple, got {type(args).__name__}")
    for idx_or_key, element in items:
        key = idx_or_key
        # Case: dictionary element that may contain 'value', 'min', 'max'
        if isinstance(element, dict):
            val = element.get('value')
            if val is None:
                continue  # nothing to validate
            min_ = element.get('min')
            max_ = element.get('max')
            if min_ is not None and val < min_:
                raise ValueError(f"Argument '{key}' value {val} is below minimum {min_}")
            if max_ is not None and val > max_:
                raise ValueError(f"Argument '{key}' value {val} exceeds maximum {max_}")
        # Case: tuple or list of length 3: (value, min, max)
        elif isinstance(element, (list, tuple)):
            if len(element) != 3:
                raise TypeError(f"Tuple argument at '{key}' must be length 3 (value, min, max), got {len(element)}")
            val, min_, max_ = element
            if not isinstance(val, (int, float)):
                raise TypeError(f"Value at '{key}' is not a number: {val!r}")
            if min_ is not None and val < min_:
                raise ValueError(f"Argument '{key}' value {val} is below minimum {min_}")
            if max_ is not None and val > max_:
                raise ValueError(f"Argument '{key}' value {val} exceeds maximum {max_}")
        # Case: numeric value directly (no bounds specified)
        elif isinstance(element, (int, float)):
            continue
        else:
            raise TypeError(f"Unsupported argument type at '{key}': {type(element).__name__}")
    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
        """
        Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        try:
            # Basic type checks
            if not isinstance(subcommand, str):
                raise TypeError("subcommand must be a string")
            if not isinstance(type_name, str):
                raise TypeError("type_name must be a string")
            if not isinstance(option_name, str):
                raise TypeError("option_name must be a string")
            if not isinstance(spec_option, dict):
                raise TypeError("spec_option must be a dictionary")

            # Ensure required keys in spec_option
            required_keys = {"type", "required", "help"}
            missing = required_keys - spec_option.keys()
            if missing:
                raise ValueError(f"spec_option is missing required keys: {missing}")

            # Construct a simple complex type representation
            complex_type = {
                "subcommand": subcommand,
                "type_name": type_name,
                "option_name": option_name,
                "spec": spec_option,
            }
            return complex_type

        except Exception as exc:
            # Log or re-raise with context if desired
            raise RuntimeError(f"Failed to create complex argument type: {exc}") from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
