    """Build the complex argument type

    This method creates a representation of a complex argument type from the
    specification.  It validates inputs, constructs a dictionary containing
    the type information and recursively processes any nested complex
    specifications that may be present.

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications (expected to be a dict)
    :return: the complex type instance (dictionary) or ``None`` on error
    """
    try:
        # Basic input validation
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")
        if not isinstance(spec_option, dict):
            raise ValueError("spec_option must be a dictionary")

        # Construct the base complex type representation
        complex_type = {
            "subcommand": subcommand,
            "type_name": type_name,
            "option_name": option_name,
            "spec_option": spec_option.copy(),
        }

        # Handle nested complex options recursively, if defined
        nested = spec_option.get("nested") or spec_option.get("suboptions")
        if isinstance(nested, dict):
            complex_type["nested"] = {}
            for key, sub_spec in nested.items():
                if isinstance(sub_spec, dict):
                    nested_complex = self.create_complex_argumet_type(
                        subcommand, key, key, sub_spec
                    )
                    complex_type["nested"][key] = nested_complex
        elif isinstance(nested, list):
            complex_type["nested"] = []
            for idx, sub_spec in enumerate(nested):
                if isinstance(sub_spec, dict):
                    nested_complex = self.create_complex_argumet_type(
                        subcommand,
                        f"{type_name}_{idx}",
                        f"{option_name}_{idx}",
                        sub_spec,
                    )
                    complex_type["nested"].append(nested_complex)

        return complex_type
    except Exception as exc:
        # Simple error reporting – in production code replace with logging
        import traceback

        traceback.print_exc()
        return None

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Helper to parse a single item into key and value
    def _parse_item(item):
        if isinstance(item, str):
            if '=' in item:
                key, val = item.split('=', 1)
                return key.strip(), val.strip()
            else:
                return item.strip(), True
        elif isinstance(item, tuple) and len(item) == 2:
            key, val = item
            return str(key).strip(), val
        elif isinstance(item, dict):
            return item
        else:
            raise ValueError(f"Unsupported argument format: {item!r}")

    # Resolve args into a dict of key => value
    raw_kwargs = {}
    try:
        if args is None:
            raw_kwargs = {}
        elif isinstance(args, dict):
            raw_kwargs = dict(args)  # copy
        elif isinstance(args, (list, tuple)):
            for itm in args:
                if isinstance(itm, dict):
                    raw_kwargs.update(itm)
                else:
                    key, val = _parse_item(itm)
                    raw_kwargs[key] = val
        else:
            # Attempt to treat as iterable of items
            for itm in args:
                key, val = _parse_item(itm)
                raw_kwargs[key] = val
    except Exception as exc:
        raise ValueError(f"Failed to parse args: {exc}") from exc

    # Determine which keys are control arguments
    control_possibilities = set()
    # If the object has an attribute listing control keys, use it
    if hasattr(self, "CONTROL_ARGS") and isinstance(getattr(self, "CONTROL_ARGS"), (list, set, tuple)):
        control_possibilities.update(getattr(self, "CONTROL_ARGS"))
    # Heuristic: any key containing 'control' in its name
    for key in raw_kwargs:
        if "control" in key.lower() or key.lower().startswith("ctrl"):
            control_possibilities.add(key)

    control_args = {}
    nested_args = {}
    for k, v in raw_kwargs.items():
        if k in control_possibilities:
            control_args[k] = v
        else:
            nested_args[k] = v

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args or dictionary.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}

        # Accept either a dict or an iterable of (key, value) pairs
        try:
            if isinstance(args, dict):
                items = args.items()
            else:
                # Convert to list of tuples to ensure correct unpacking
                items = list(args)
                # Validate each element is a two‑item sequence
                for item in items:
                    if not (isinstance(item, (tuple, list)) and len(item) == 2):
                        raise ValueError("Each argument must be a (key, value) pair.")
        except Exception as exc:
            raise TypeError("args must be a dict or an iterable of (key, value) pairs") from exc

        for key, val in items:
            if not isinstance(key, str):
                # Skip non‑string keys as they are not valid argument names
                continue
            if key.startswith("control_"):
                control_args[key] = val
            elif key.startswith("custom_"):
                # Custom arguments are not included in nested_args
                continue
            else:
                nested_args[key] = val

        return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    try:
        # If args is None, treat as empty
        if args is None:
            return control_args, nested_args

        # Dict style input
        if isinstance(args, dict):
            iterable = args.items()
        else:
            # Try to iterate over args; if it's not iterable, ignore
            try:
                iterable = iter(args)
            except TypeError:
                return control_args, nested_args

        for item in iterable:
            # For dict items, already key/value tuple
            if isinstance(item, tuple) or isinstance(item, list):
                if len(item) != 2:
                    continue
                key, value = item
            else:
                # Unsupported item format; skip
                continue

            # Ensure key is string
            if not isinstance(key, str):
                continue

            # Separate control arguments (prefix "control_")
            if key.startswith("control_"):
                key_name = key[len("control_") :]
                control_args[key_name] = value
            # Custom arguments (prefix "custom_") treated as nested
            elif key.startswith("custom_"):
                nested_key = key[len("custom_") :]
                nested_args[nested_key] = value
            else:
                # Default nested argument
                nested_args[key] = value

    except Exception:
        # In case of unexpected error, return empty dicts
        return {}, {}

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """
        Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args or dict of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Prepare input: if a dict, use its items; if a list of strings, parse each
        if isinstance(args, dict):
            items = list(args.items())
        else:
            items = []
            for item in args:
                if isinstance(item, tuple) and len(item) == 2:
                    items.append(item)
                else:
                    # assume string like key=value or key
                    if isinstance(item, str):
                        if '=' in item:
                            key, val = item.split('=', 1)
                        else:
                            key, val = item, True
                        items.append((key, val))
                    else:
                        # unsupported format, skip
                        continue

        control_args = {}
        nested_args = {}

        def insert_nested(d, key_parts, value):
            """Insert value into nested dict d using list of key_parts."""
            for part in key_parts[:-1]:
                if part not in d or not isinstance(d[part], dict):
                    d[part] = {}
                d = d[part]
            d[key_parts[-1]] = value

        for key, val in items:
            # Convert string "True"/"False" to bool for convenience
            if isinstance(val, str):
                if val.lower() == 'true':
                    val = True
                elif val.lower() == 'false':
                    val = False

            # Determine type by prefixes
            if isinstance(key, str) and key.startswith('control.'):
                # Control argument: strip prefix and store as flat key
                control_key = key[len('control.') :]
                control_args[control_key] = val
            elif isinstance(key, str) and key.startswith('custom.'):
                # Custom: insert under 'custom' node in nested dict
                custom_path = key[len('custom.') :].split('.')
                insert_nested(nested_args, ['custom'] + custom_path, val)
            else:
                # Regular nested argument
                path = key.split('.') if isinstance(key, str) else [str(key)]
                insert_nested(nested_args, path, val)

        return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: Updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

    if extra_vars is None:
        return vars_dict

    try:
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)

        elif isinstance(extra_vars, (list, tuple)):
            for item in extra_vars:
                if isinstance(item, dict):
                    vars_dict.update(item)
                elif isinstance(item, str):
                    # try key=value syntax
                    if '=' in item:
                        key, value = item.split('=', 1)
                        key = key.strip()
                        value = value.strip()
                        if key:
                            vars_dict[key] = value
                    # try key: value syntax
                    elif ':' in item:
                        key, value = item.split(':', 1)
                        key = key.strip()
                        value = value.strip()
                        if key:
                            vars_dict[key] = value
                    # otherwise ignore the item
                # ignore unsupported item types
                else:
                    pass

        # For unsupported extra_vars types, nothing is done
    except Exception:
        # swallow any unexpected errors to avoid breaking the caller
        pass

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
        """
        Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: Iterable of extra-vars.  Each item may be in the form
                           ``key=value`` or a JSON string like ``{"key": "value"}``.
        :return: The updated dictionary.
        """
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        if extra_vars is None:
            return vars_dict

        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError(f"extra_vars must be a list or tuple, got {type(extra_vars).__name__}")

        for var in extra_vars:
            if var is None:
                continue

            # Support JSON objects
            if isinstance(var, str) and var.strip():
                stripped = var.strip()
                if stripped.startswith("{") and stripped.endswith("}"):
                    try:
                        import json
                        parsed = json.loads(stripped)
                        if isinstance(parsed, dict):
                            vars_dict.update(parsed)
                        else:
                            # Ignore if not a dict
                            continue
                    except Exception:
                        # If JSON parsing fails, fall back to key=value parsing
                        pass
                if isinstance(var, str) and "=" in var:
                    try:
                        key, val = map(str.strip, var.split("=", 1))
                        if key:
                            vars_dict[key] = val
                    except Exception:
                        # ignore malformed entries
                        continue

        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars, optionally a dict or iterable of key=value strings
        :return: The merged dictionary (modified in place)
        """
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        if extra_vars is None:
            return vars_dict

        # If extra_vars is already a mapping, just update
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # Otherwise expect an iterable of strings of the form key=value
        try:
            iterator = iter(extra_vars)
        except TypeError:
            raise TypeError(f"extra_vars must be a mapping or an iterable of strings, got {type(extra_vars).__name__}")

        for item in iterator:
            if not isinstance(item, str):
                raise TypeError(f"Each element of extra_vars must be a string, got {type(item).__name__}")
            if '=' not in item:
                # Ignore malformed entries silently
                continue
            key, value = item.split('=', 1)
            key = key.strip()
            value = value.strip()
            if key:
                vars_dict[key] = value

        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        # Validate input
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return vars_dict
        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError("extra_vars must be a list or tuple of strings")

        # Process each extra var
        for var in extra_vars:
            if not isinstance(var, str):
                # skip non-string entries
                continue
            # Split on the first '='
            if '=' in var:
                key, value = var.split('=', 1)
                key = key.strip()
                value = value.strip()
                # Try to convert value to a Python literal if possible
                try:
                    # This covers numbers, booleans, None
                    literal_value = eval(value, {})
                except Exception:
                    literal_value = value
                vars_dict[key] = literal_value
            else:
                # No value given: treat as boolean flag
                key = var.strip()
                if key:
                    vars_dict[key] = True

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import os

    # Validate playbook path
    if not os.path.exists(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Build base command
    cmd = ["ansible-playbook"]

    # Add ansible_args
    if ansible_args:
        for key, value in ansible_args.items():
            if not key.startswith("--"):
                key = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
            elif value is None:
                # Skip keys with None value
                continue
            else:
                cmd.extend([key, str(value)])

    # Add verbosity
    if verbose:
        if isinstance(verbose, int) and 1 <= verbose <= 4:
            cmd.append("-" + "v" * verbose)
        else:
            # If passed as string, use directly
            cmd.append(str(verbose))

    # Add playbook path
    cmd.append(playbook_path)

    # Add extra vars
    if extra_vars:
        try:
            json_vars = json.dumps(extra_vars, ensure_ascii=False)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Invalid extra_vars, must be JSON serializable: {exc}")
        cmd.extend(["--extra-vars", json_vars])

    # Log the command if plugin provides logging
    try:
        ir_plugin.log_debug(f"Running command: {' '.join(cmd)}")
    except Exception:
        pass  # ignore if logging not available

    # Execute
    try:
        result = subprocess.run(
            cmd,
            text=True,
            capture_output=True,
            check=False,  # do not raise on non-zero exit so caller can inspect
        )
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"ansible-playbook command not found: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    # Return return code, stdout, stderr
    return result.returncode, result.stdout, result.stderr

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.
    Executes the given playbook with optional verbosity, extra-vars, and additional arguments.
    Raises RuntimeError if the command fails or if the executable is not found.
    Returns the CompletedProcess object on success.
    """
    # Ensure modules are available without using import statements
    subprocess = __import__('subprocess')
    json = __import__('json')

    # Base command
    cmd = ['ansible-playbook', playbook_path]

    # Verbosity
    if verbose is not None:
        try:
            v_level = int(verbose)
        except Exception:
            v_level = 0
        if v_level > 0:
            cmd.append('-' + 'v' * v_level)

    # Extra vars
    if isinstance(extra_vars, dict) and extra_vars:
        # Convert to JSON string
        extra_json = json.dumps(extra_vars)
        cmd.extend(['--extra-vars', extra_json])

    # Additional ansible-playbook arguments
    if isinstance(ansible_args, dict) and ansible_args:
        for key, value in ansible_args.items():
            flag = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            else:
                cmd.extend([flag, str(value)])

    # Execute the command
    try:
        result = subprocess.run(cmd, capture_output=True, text=True)
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command 'ansible-playbook' not found: {exc}") from None

    # Check the result
    if result.returncode != 0:
        err_msg = result.stderr.strip()
        if not err_msg:
            err_msg = f"ansible-playbook exited with code {result.returncode}"
        raise RuntimeError(f"ansible-playbook failed: {err_msg}")

    return result

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results as a dict with keys 'stdout', 'stderr', 'rc'
    """
    import subprocess
    import json

    # Prepare the ansible-playbook command
    cmd = ["ansible-playbook"]
    try:
        if not isinstance(cli_args, list):
            ir_plugin.log_error("cli_args must be a list")
            return {"stdout": "", "stderr": "Invalid cli_args type", "rc": -1}

        # Append user provided arguments
        cmd.extend(cli_args)

        # Serialize the vars_dict as JSON for --extra-vars
        if vars_dict is None:
            vars_dict = {}
        if not isinstance(vars_dict, dict):
            ir_plugin.log_error("vars_dict must be a dictionary")
            return {"stdout": "", "stderr": "Invalid vars_dict type", "rc": -1}
        ev = json.dumps(vars_dict)
        cmd.append("--extra-vars")
        cmd.append(ev)

        # Determine working directory (if workspace has a path)
        cwd = None
        try:
            cwd = getattr(ir_workspace, "path", None)
        except Exception:
            cwd = None

        # Execute the command
        result = subprocess.run(
            cmd,
            cwd=cwd,
            text=True,
            capture_output=True,
            check=True,
        )
        return {"stdout": result.stdout, "stderr": result.stderr, "rc": result.returncode}

    except subprocess.CalledProcessError as e:
        # Ansible returned non-zero exit code
        ir_plugin.log_error(f"Ansible playbook failed: {e.stderr.strip()}")
        return {"stdout": e.stdout or "", "stderr": e.stderr or "", "rc": e.returncode}
    except FileNotFoundError:
        # ansible-playbook command not found
        ir_plugin.log_error("ansible-playbook command not found.")
        return {"stdout": "", "stderr": "ansible-playbook command not found", "rc": -1}
    except Exception as exc:
        # Generic failure
        ir_plugin.log_error(f"Unexpected error running ansible playbook: {exc}")
        return {"stdout": "", "stderr": str(exc), "rc": -1}

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.
    All values are received as strings; this method attempts to convert
    them to bool, int, float, or a list of strings when appropriate.
    """
    if not isinstance(values_dict, dict):
        return
    for key, value in list(values_dict.items()):
        # Only process string inputs
        if not isinstance(value, str):
            continue
        val = value.strip()

        # Convert booleans
        lowered = val.lower()
        if lowered in ("true", "false"):
            values_dict[key] = lowered == "true"
            continue

        # Convert comma-separated values to list
        if ',' in val:
            values_dict[key] = [item.strip() for item in val.split(',')]
            continue

        # Convert to integer
        if val.lstrip('-').isdigit():
            try:
                values_dict[key] = int(val)
                continue
            except Exception:
                pass

        # Convert to float
        try:
            # Avoid converting plain integers again
            if '.' in val or 'e' in val.lower():
                values_dict[key] = float(val)
            else:
                # If it parsed as int earlier, keep int
                pass
        except Exception:
            pass
    return  # The dictionary is modified in place.

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in-place.

    By default all the values are strings. This method attempts to convert
    each value to a more appropriate Python type based on a predefined
    conversion map for the given parser_name. If no conversion map
    exists for the parser, a generic conversion rule is applied:
    - strings that represent booleans are turned into bool
    - numeric strings are converted to int or float
    - the strings "null" or "none" (case‑insensitive) become None

    If a conversion fails for a particular value, the original string
    is left untouched, and the error is swallowed.

    Parameters
    ----------
    parser_name : str
        The command name, e.g. 'main', 'virsh', 'ospd', etc.
    values_dict : dict
        The dictionary of arguments with string values.

    Raises
    ------
    TypeError
        If values_dict is not a dictionary or parser_name is not a string.
    """

    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")
    if parser_name is not None and not isinstance(parser_name, str):
        raise TypeError("parser_name must be a string or None")

    # Define type conversion maps for specific parsers
    # The values are callables that perform the conversion.
    type_maps = {
        # Example parser-specific conversions
        # The actual mapping should be extended to match your application
        "main": {
            "verbose": bool,
            "threshold": int,
            "alpha": float,
        },
        "virsh": {
            "memory": int,
            "cpu": int,
        },
        "ospd": {
            "debug": bool,
            "timeout": int,
        },
    }

    where_to_convert = type_maps.get(parser_name, {})

    for key, raw_value in values_dict.items():
        # Skip None values
        if raw_value is None:
            continue

        # If a parser-specific conversion is defined
        if key in where_to_convert:
            target = where_to_convert[key]
            try:
                if target is bool:
                    # Handle common boolean string representations
                    if isinstance(raw_value, str):
                        lowered = raw_value.strip().lower()
                        if lowered in ("true", "1", "yes", "on"):
                            values_dict[key] = True
                            continue
                        if lowered in ("false", "0", "no", "off"):
                            values_dict[key] = False
                            continue
                        # If it does not match, fall back to bool(raw_value)
                    values_dict[key] = bool(raw_value)
                else:
                    values_dict[key] = target(raw_value)
            except Exception:
                # Invalid conversion, keep original value
                pass
            continue

        # Generic conversion rules
        if isinstance(raw_value, str):
            lowered = raw_value.strip().lower()

            # Boolean conversion
            if lowered in ("true", "1", "yes", "on"):
                values_dict[key] = True
                continue
            if lowered in ("false", "0", "no", "off"):
                values_dict[key] = False
                continue

            # None conversion
            if lowered in ("null", "none"):
                values_dict[key] = None
                continue

            # Integer conversion
            try:
                if raw_value.strip().lstrip("-").isdigit():
                    values_dict[key] = int(raw_value)
                    continue
            except Exception:
                pass

            # Float conversion
            try:
                # Avoid strings like '1e4' if you don't want that
                values_dict[key] = float(raw_value)
                continue
            except Exception:
                pass

            # If the string contains commas, treat it as a list of values
            if "," in raw_value:
                try:
                    parts = [x.strip() for x in raw_value.split(",")]
                    # Attempt to convert each part recursively
                    for i, part in enumerate(parts):
                        if part.lower() in ("true", "false", "null", "none"):
                            parts[i] = _convert_non_cli_args(
                                self, parser_name, {"value": part}
                            ).get("value")
                        else:
                            try:
                                parts[i] = int(part)
                                continue
                            except Exception:
                                pass
                            try:
                                parts[i] = float(part)
                                continue
                            except Exception:
                                pass
                    values_dict[key] = parts
                except Exception:
                    pass
    # No return value; values_dict is modified in place
    return None

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Optional explicit casting rules per-parser
    cast_map = getattr(self, "_arg_type_map", {}).get(parser_name, {})
    for key, val in list(values_dict.items()):
        # Skip non-string values
        if not isinstance(val, str):
            continue
        # If explicit cast function defined, use it
        cast_func = cast_map.get(key)
        if cast_func:
            try:
                values_dict[key] = cast_func(val)
                continue
            except Exception:
                # Fall back to heuristic mapping if casting fails
                pass
        # Heuristic casting
        lowered = val.lower()
        # Handle boolean-like values
        if lowered in ("true", "false", "1", "0"):
            values_dict[key] = lowered in ("true", "1")
            continue
        # Handle None
        if lowered == "none":
            values_dict[key] = None
            continue
        # Try integer
        if val.lstrip("-").isdigit():
            try:
                values_dict[key] = int(val)
                continue
            except Exception:
                pass
        # Try float
        if "." in val:
            try:
                values_dict[key] = float(val)
                continue
            except Exception:
                pass
        # Try comma-separated list
        if "," in val:
            try:
                values_dict[key] = [x.strip() for x in val.split(",")]
                continue
            except Exception:
                pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Validate plugin_dir
    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"The directory {plugin_dir} does not exist or is not a directory")

    # Candidate spec file names
    spec_filenames = [
        'plugin.json', 'plugin.yml', 'plugin.yaml',
        'spec.json', 'spec.yml', 'spec.yaml'
    ]

    spec_data = None
    for fname in spec_filenames:
        spec_path = os.path.join(plugin_dir, fname)
        if os.path.isfile(spec_path):
            try:
                with open(spec_path, 'r', encoding='utf-8') as f:
                    try:
                        spec_data = json.load(f)
                    except json.JSONDecodeError:
                        # Try loading YAML if PyYAML is available
                        try:
                            import yaml  # type: ignore
                            spec_data = yaml.safe_load(f)
                        except Exception as yaml_exc:
                            raise ValueError(f"Unable to parse spec file '{fname}': {yaml_exc}") from yaml_exc
                break  # Successfully loaded
            except Exception as e:
                raise ValueError(f"Error reading spec file '{fname}': {e}") from e

    if spec_data is None:
        # No spec file found; return empty dict
        return {}

    if not isinstance(spec_data, dict):
        raise ValueError("The spec file content is not a dictionary")

    flat_dict = _flatten(spec_data)
    return flat_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        from pathlib import Path
        import json
    except Exception as exc:
        raise RuntimeError(f"Failed to import required modules: {exc}") from exc

    # Resolve plugin directory
    plugin_path = Path(plugin_dir)
    if not plugin_path.is_dir():
        raise ValueError(f"Provided plugin_dir '{plugin_dir}' is not a directory")

    # Known spec file names
    spec_files = ["plugin.yaml", "plugin.yml", "plugin.json"]
    spec_file_path = None

    # Find the spec file
    for filename in spec_files:
        candidate = plugin_path / filename
        if candidate.is_file():
            spec_file_path = candidate
            break

    if spec_file_path is None:
        raise FileNotFoundError(
            f"No plugin spec file found in '{plugin_dir}'. "
            f"Expected one of: {', '.join(spec_files)}"
        )

    # Load the spec
    try:
        if spec_file_path.suffix in {".yaml", ".yml"}:
            import yaml
            with spec_file_path.open("r", encoding="utf-8") as fp:
                data = yaml.safe_load(fp)
        elif spec_file_path.suffix == ".json":
            with spec_file_path.open("r", encoding="utf-8") as fp:
                data = json.load(fp)
        else:
            raise ValueError(f"Unsupported spec file type: {spec_file_path.suffix}")
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec from '{spec_file_path}': {exc}") from exc

    # Helper to flatten nested dicts
    def _flatten(d, parent_key="", sep="."):
        items = {}
        if not isinstance(d, dict):
            return {parent_key: d}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Ensure root is dict
    if not isinstance(data, dict):
        raise ValueError(f"Expected the root of the plugin spec to be a dict, got {type(data).__name__}")

    flat_dict = _flatten(data)
    return flat_dict

