def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    def _flatten_dict(d, parent_key=''):
        """Recursively flattens a dictionary using dot notation"""
        items = {}
        for key, value in d.items():
            compound_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                items.update(_flatten_dict(value, compound_key))
            else:
                items[compound_key] = value
        return items

    import os
    import json

    try:
        if not isinstance(plugin_dir, str) or not os.path.isdir(plugin_dir):
            return {}

        # Look for a JSON spec file in the directory
        spec_file = None
        for fname in os.listdir(plugin_dir):
            if fname.lower().endswith('.json'):
                spec_file = os.path.join(plugin_dir, fname)
                break

        if not spec_file:
            return {}

        with open(spec_file, 'r', encoding='utf-8') as f:
            spec_data = json.load(f)

        if not isinstance(spec_data, dict):
            return {}

        return _flatten_dict(spec_data)
    except Exception:
        # On any error (e.g., file not found, JSON syntax error, permission issues)
        # return an empty dictionary to avoid raising
        return {}

