            cwd = os.getcwd()
            default_path = os.path.join(cwd, 'config.yaml')
            os.environ['CONFIG_PATH'] = default_path
    except Exception as exc:
        raise RuntimeError(f"Unable to set CONFIG_PATH environment variable: {exc}") from exc

