def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    if root == "":
        raise ValueError("root cannot be an empty string")

    # Ensure root does not have a trailing separator
    # but allow it if path also contains it
    if not path.startswith(root):
        # special case: root ends with separator and path starts with followed by separator
        if not root.endswith(('/', '\\')) and path.startswith(root + '/' ) or path.startswith(root + '\\'):
            # this case is already handled by the previous check
            pass
        else:
            raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
    stripped = path[len(root):]
    # Remove a leading separator left after stripping, if present
    if stripped and (stripped[0] == '/' or stripped[0] == '\\'):
        stripped = stripped[1:]
    return stripped

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings.")
    if not path or not root:
        raise ValueError("Both path and root must be non-empty strings.")
    import os
    abs_path = os.path.abspath(path)
    abs_root = os.path.abspath(root)
    try:
        common = os.path.commonpath([abs_path, abs_root])
    except ValueError as exc:
        raise ValueError(f"Could not determine common path for '{path}' and '{root}': {exc}") from exc
    if common != abs_root:
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'.")
    rel_path = os.path.relpath(abs_path, abs_root)
    if rel_path == '.':
        raise ValueError("After stripping root, the resulting path would be empty (path equals root).")
    return rel_path
